# %% ===========================================================================
#    ENUMERATIONS
# =============================================================================
class RefSource(StrEnum):
    """Reference oscillator selection, as accepted by ``ROSC:SOUR`` [R1]."""

    INTERNAL = "INT"
    EXTERNAL = "EXT"


class FMMode(IntEnum):
    """``FM:MODE`` argument values [R1, Table 5].

    Rate ranges are quoted from [R2] Step 5-2 and [R4] FSW specifications.
    """

    PHASE = 1        # DC to 100 kHz
    FM_WIDE = 2      # 50 kHz to 1 MHz
    FM_NARROW1 = 3   # 100 Hz to 10 kHz
    FM_NARROW2 = 4   # 10 kHz to 100 kHz

    @property
    def label(self) -> str:
        """Human-readable name including the documented modulation rate."""
        return {
            FMMode.PHASE: "Phase modulation (DC - 100 kHz)",
            FMMode.FM_WIDE: "FM wideband (50 kHz - 1 MHz)",
            FMMode.FM_NARROW1: "FM narrowband 1 (100 Hz - 10 kHz)",
            FMMode.FM_NARROW2: "FM narrowband 2 (10 kHz - 100 kHz)",
        }[self]


class TriggerMode(IntEnum):
    """Sweep and list trigger selection [R1, Tables 2b/2c/5]."""

    SOFTWARE = 0
    FULL_TRIGGER = 1   # one trigger starts the whole sweep/list
    POINT_TRIGGER = 2  # one trigger advances one point (min. period 150 us)


class SweepDirection(IntEnum):
    """Sweep and list traversal direction [R1, Tables 2b/2c/5]."""

    UP = 0        # low to high
    DOWN = 1      # high to low
    UP_DOWN = 2   # both


class StatusBit(IntEnum):
    """Bit positions in the ``STAT?`` response low byte [R1, Tables 3/5].

    Beware the inverted senses: for LOCK bits, 0 means locked.
    """

    EXT_REF = 0          # 0 = no external reference, 1 = external reference
    RF_UNLOCKED = 1      # 0 = RF locked,  1 = RF unlocked
    REF_UNLOCKED = 2     # 0 = ref locked, 1 = ref unlocked
    RF_OUTPUT_ON = 3     # 0 = RF output off, 1 = on
    VOLTAGE_ERROR = 4    # 0 = voltage OK, 1 = voltage error
    REF_OUTPUT_ON = 5    # 0 = reference output off, 1 = on
    BLANKING_ON = 6      # 0 = blanking off, 1 = on
    LOCK_RECOVERY = 7    # 1 = lock recovery on, 0 = off


class ModBit(IntEnum):
    """Bit positions in the ``DIAG:MOD?`` response low byte [R1, Tables 3/5]."""

    PULSE = 0
    AM = 1
    FM_NB1 = 2
    FM_NB2 = 3
    FM_WIDE = 4
    PHASE = 5


