@dataclass(slots=True, frozen=True)
class ModelCapability:
    """Static per-model limits, transcribed from the datasheet [R4].

    Attributes
    ----------
    model:
        Model string as returned in field 2 of the ``*IDN?`` response.
    f_min_hz, f_max_hz:
        Standard frequency coverage.
    f_min_opt1_hz:
        Lower limit when frequency-extension option 1 is fitted, or ``None``
        when the model offers no such option.
    f_resolution_hz:
        Smallest commandable frequency step.
    p_default_dbm:
        Rated output power with no power-control option (the typical level
        for fixed-output models).
    p_min_dbm, p_max_dbm:
        Levelled power-control range with option 2 fitted; equal to
        ``p_default_dbm`` for fixed-output models.
    has_power_control:
        True when the model can be ordered with a power-control option (the
        FSW series, option 2 [R4]). Whether option 2 is actually fitted is
        not visible in ``*IDN?`` (the option field is undefined in [R1]), so
        the GUI reads the level back after every change.
    scpi_documented:
        True only for the models whose SCPI set is explicitly covered by
        [R1]. For the others the same commands are offered but flagged as
        unverified, because [R1] names only FSW-0010 and FSW-0020.
    has_modulation:
        True when the model exposes PULSE, AM and FM inputs. The FSL and
        mmW series list no such connectors in [R4], so the Modulation tab
        is hidden for them rather than offering commands with no hardware
        behind them.
    notes:
        Free text surfaced in the connection tab.
    """

    model: str
    f_min_hz: float
    f_max_hz: float
    f_min_opt1_hz: float | None
    f_resolution_hz: float
    p_default_dbm: float
    p_min_dbm: float
    p_max_dbm: float
    scpi_documented: bool
    notes: str = ""
    has_modulation: bool = True
    has_power_control: bool = False


