# %% ===========================================================================
#    DATA CONTAINERS
# =============================================================================
@dataclass(slots=True)
class Identity:
    """Decoded ``*IDN?`` response.

    Field order manufacturer, model, option word (hex), serial number,
    firmware version: undocumented in [R1], confirmed against NI's soft
    front panels on an FSL-0020 (ambiguity note 2 in the module header).
    ``fields`` preserves every raw field.

    Attributes
    ----------
    firmware_value, firmware_base:
        The firmware field parsed as an integer, and which base succeeded
        ("decimal", "hexadecimal" or "unparsed"). Both bases are attempted
        because the documentation does not say which applies.
    """

    raw: str = ""
    fields: list[str] = field(default_factory=list)
    manufacturer: str = ""
    model: str = ""
    options: str = ""
    firmware: str = ""
    firmware_value: int | None = None
    firmware_base: str = ""
    serial: str = ""

    #: Labels applied to the comma-separated fields, in order (confirmed on
    #: hardware in 0.0.8; see ambiguity note 2).
    FIELD_LABELS: ClassVar[tuple[str, ...]] = (
        "Manufacturer",
        "Model #",
        "Option word (hex)",
        "Serial #",
        "Firmware version",
    )

    @property
    def option_numbers(self) -> list[int]:
        """Option numbers set in the option word (bit n = option n+1).

        This is how NI's calibration soft front panel decodes it: option word
        017F is shown as options 1, 2, 3, 4, 5, 6, 7, 9. The word describes
        what the firmware believes is fitted; on the FSL-0020 it lists
        option 2 although the level does not change (README section 3.3).
        """
        try:
            word = int(self.options, 16)
        except ValueError:
            return []
        return [bit + 1 for bit in range(word.bit_length()) if (word >> bit) & 1]

    @property
    def scpi_supported(self) -> bool | None:
        """Whether the firmware field meets the documented SCPI gate.

        Returns ``True``, ``False`` or ``None`` when the field could not be
        parsed in either base. This is ADVISORY ONLY: a unit that answered
        ``*IDN?`` at all is demonstrably servicing SCPI, so a ``False`` here
        is reported to the operator but never used to block a command.
        """
        if self.firmware_value is None:
            return None
        return self.firmware_value >= MIN_SCPI_FIRMWARE


@dataclass(slots=True)
class StatusWord:
    """Decoded ``STAT?`` response. Lock flags are already de-inverted."""

    raw: int = 0
    ext_ref_present: bool = False
    rf_locked: bool = False
    ref_locked: bool = False
    rf_output_on: bool = False
    voltage_error: bool = False
    ref_output_on: bool = False
    blanking_on: bool = False
    lock_recovery_on: bool = False

    @classmethod
    def from_raw(cls, raw: int) -> "StatusWord":
        """Decode the low byte of a ``STAT?`` response.

        Parameters
        ----------
        raw:
            Integer value of the response. The upper byte is documented as
            "don't care" [R1, Table 3] and is masked off.
        """
        low = raw & 0xFF
        return cls(
            raw=low,
            ext_ref_present=bool(low & (1 << StatusBit.EXT_REF)),
            # Sense inversion: the bit is set when UNlocked.
            rf_locked=not bool(low & (1 << StatusBit.RF_UNLOCKED)),
            ref_locked=not bool(low & (1 << StatusBit.REF_UNLOCKED)),
            rf_output_on=bool(low & (1 << StatusBit.RF_OUTPUT_ON)),
            voltage_error=bool(low & (1 << StatusBit.VOLTAGE_ERROR)),
            ref_output_on=bool(low & (1 << StatusBit.REF_OUTPUT_ON)),
            blanking_on=bool(low & (1 << StatusBit.BLANKING_ON)),
            lock_recovery_on=bool(low & (1 << StatusBit.LOCK_RECOVERY)),
        )


@dataclass(slots=True)
class ModulationWord:
    """Decoded ``DIAG:MOD?`` response low byte [R1, Table 5]."""

    raw: int = 0
    pulse: bool = False
    am: bool = False
    fm_nb1: bool = False
    fm_nb2: bool = False
    fm_wide: bool = False
    phase: bool = False

    @classmethod
    def from_raw(cls, raw: int) -> "ModulationWord":
        """Decode the low byte of a ``DIAG:MOD?`` response."""
        low = raw & 0xFF
        return cls(
            raw=low,
            pulse=bool(low & (1 << ModBit.PULSE)),
            am=bool(low & (1 << ModBit.AM)),
            fm_nb1=bool(low & (1 << ModBit.FM_NB1)),
            fm_nb2=bool(low & (1 << ModBit.FM_NB2)),
            fm_wide=bool(low & (1 << ModBit.FM_WIDE)),
            phase=bool(low & (1 << ModBit.PHASE)),
        )


@dataclass(slots=True)
class Transaction:
    """One command/response exchange, as written to transactions.csv."""

    t_unix: float
    command: str
    response: str | None
    latency_s: float
    ok: bool
    error: str = ""
    is_query: bool = False


@dataclass(slots=True)
class ListPoint:
    """A single list-mode point [R1, Table 5 ``LIST:PVEC``]."""

    index: int
    freq_hz: float
    power_dbm: float
    dwell_us: int
    pulse_mod: bool = False
    rf_output: bool = True
    save_to_flash: bool = False


# %% ===========================================================================
#    EXCEPTIONS
# =============================================================================
class QuickSynError(Exception):
    """Base class for every error raised by this module."""


class TransportError(QuickSynError):
    """The serial link failed, timed out, or was not open."""


class CommandTooLongError(QuickSynError):
    """The encoded command exceeds the 64-byte device buffer [R1]."""


class ParameterError(QuickSynError):
    """A requested value lies outside the instrument's documented range."""


def _check_compound_length(command: str, hint: str) -> None:
    """Pre-flight a compound command against the 64-byte device buffer.

    The transport enforces the limit anyway, but a bare byte count is not
    actionable to an operator staring at a sweep dialog. This raises the
    same condition with advice on which parameter to shorten.

    Parameters
    ----------
    command:
        The fully formatted command, without its terminator.
    hint:
        What the operator can change to make it fit.

    Raises
    ------
    CommandTooLongError
        If the terminated command would exceed ``MAX_COMMAND_BYTES``.
    """
    encoded = len(command.encode("ascii", errors="replace")) + len(TERMINATOR)
    if encoded > MAX_COMMAND_BYTES:
        raise CommandTooLongError(
            f"This command needs {encoded} bytes but the QuickSyn serial "
            f"buffer holds only {MAX_COMMAND_BYTES} including the terminator "
            f"[R1]. {hint}\n\n{command}"
        )


# %% ===========================================================================
#    UNIT HELPERS
# =============================================================================
def hz_to_mlhz(freq_hz: float) -> int:
    """Convert hertz to integer millihertz, the native command unit.

    [R1] gives millihertz (``mlHz``) as the default unit for ``FREQ`` and as
    the unit of the ``FREQ?`` response. Sending an integer avoids any
    dependence on the firmware's float parser and is exactly representable
    for the whole 0.1 GHz to 82 GHz span.

    Parameters
    ----------
    freq_hz:
        Frequency in hertz.

    Returns
    -------
    int
        Frequency in millihertz, rounded to the nearest integer.
    """
    return int(round(freq_hz * 1_000.0))


def mlhz_to_hz(freq_mlhz: float) -> float:
    """Convert the instrument's millihertz response back to hertz."""
    return float(freq_mlhz) / 1_000.0


def quantise_power_dbm(power_dbm: float) -> float:
    """Quantise a level to the 0.1 dB command granularity.

    Every documented QuickSyn power argument is expressed in tenth-dBm
    [R1, Tables 2a/5], so values finer than 0.1 dB cannot be commanded even
    though [R4] quotes 0.01 dB nominal resolution for the FSW-0010 with
    option 2. See ambiguity note 5 in the module header.
    """
    return round(power_dbm * 10.0) / 10.0


#: Accepted frequency units and their size in millihertz [R1, Table 5].
#: Bare "Hz" is deliberately absent: it is not in the documented list.
FREQ_UNIT_MLHZ: dict[str, int] = {
    "GHz": 1_000_000_000_000,
    "MHz": 1_000_000_000,
    "KHz": 1_000_000,
}


def format_frequency(freq_hz: float) -> str:
    """Encode a frequency in the shortest EXACT accepted representation.

    Compound commands such as ``LIST:PVEC`` and ``SWE:*:SETUP`` carry two or
    three frequencies plus every other parameter inside the 64-byte device
    buffer [R1, "USB Interface"]. A 20 GHz carrier in millihertz is 14
    characters, and three of those overflow the buffer on their own, which
    is why the [R1] examples all write frequencies with a GHz suffix. This
    function therefore evaluates every documented unit plus the millihertz
    default and returns whichever spelling is shortest.

    No candidate ever loses precision: millihertz is the instrument's
    resolution, so dividing by a power of ten and trimming trailing zeros
    is exact by construction.

    Parameters
    ----------
    freq_hz:
        Frequency in hertz.

    Returns
    -------
    str
        For example ``"2GHz"``, ``"9.111222333GHz"`` or ``"9876543210000"``
        (millihertz, the documented default unit). Ties resolve in favour
        of the millihertz form because it is the documented default.

    Examples
    --------
    >>> format_frequency(2.0e9)
    '2GHz'
    >>> format_frequency(10.0e9)
    '10GHz'
    """
    mlhz = hz_to_mlhz(freq_hz)
    best = str(mlhz)                      # documented default unit
    for suffix, scale in FREQ_UNIT_MLHZ.items():
        whole, remainder = divmod(abs(mlhz), scale)
        digits = len(str(scale)) - 1      # fractional digits needed at most
        body = f"{'-' if mlhz < 0 else ''}{whole}"
        if remainder:
            body += f".{remainder:0{digits}d}".rstrip("0")
        candidate = f"{body}{suffix}"
        if len(candidate) < len(best):
            best = candidate
    return best


def quantise_dwell_us(dwell_us: int) -> int:
    """Quantise a dwell time to the instrument's 5 us granularity.

    [R1] Tables 2b and 2c specify the dwell field as "Dwell time in usec
    (5 to 4,294,967,295 (~1hr)) in 5us increments", so a value that is not
    a multiple of 5 us cannot be represented. Rounding here, rather than
    letting the firmware truncate silently, means the logged command is the
    command the instrument actually executes.

    Parameters
    ----------
    dwell_us:
        Requested dwell time in microseconds.

    Returns
    -------
    int
        The nearest multiple of 5 us, clamped to the documented range. Zero
        is passed through unchanged because ``LIST:SETUP`` treats a zero
        global dwell as "use each point's own dwell" [R1, Table 2b].
    """
    if dwell_us <= 0:
        return 0
    quantised = int(round(dwell_us / DWELL_INCREMENT_US)) * DWELL_INCREMENT_US
    return max(DWELL_MIN_US, min(quantised, DWELL_MAX_US))


def format_dwell(dwell_us: int) -> str:
    """Render a dwell time in the most compact accepted unit.

    ``LIST:PVEC`` and the sweep setup commands accept ``us``, ``ms`` or
    ``s``, defaulting to microseconds [R1, Table 5]. Choosing the compact
    form matters because the whole command must fit in 64 bytes. The value
    is quantised to 5 us first.

    Parameters
    ----------
    dwell_us:
        Dwell time in microseconds, 5 to 4 294 967 295.

    Returns
    -------
    str
        For example ``"2500us"``, ``"50ms"`` or ``"3s"``.
    """
    dwell_us = quantise_dwell_us(dwell_us)
    if dwell_us % 1_000_000 == 0 and dwell_us >= 1_000_000:
        return f"{dwell_us // 1_000_000}s"
    if dwell_us % 1_000 == 0 and dwell_us >= 1_000:
        return f"{dwell_us // 1_000}ms"
    return f"{dwell_us}us"


def utc_iso(t_unix: float) -> str:
    """Format an epoch time as an ISO-8601 UTC string with milliseconds."""
    return (
        datetime.fromtimestamp(t_unix, tz=timezone.utc)
        .isoformat(timespec="milliseconds")
        .replace("+00:00", "Z")
    )


def parse_int_response(text: str) -> int:
    """Parse a response that may be decimal or hexadecimal.

    ``STAT?`` and ``DIAG:MOD?`` return values such as ``00A8`` and ``10``
    [R1, Table 5]. ``00A8`` is unambiguously hexadecimal; ``10`` is not.
    Because every documented example of these two queries is a hex string,
    hexadecimal is tried first and decimal is used only as a fallback.

    Parameters
    ----------
    text:
        Raw response text.

    Returns
    -------
    int
        Decoded integer value.

    Raises
    ------
    ValueError
        If the text parses as neither hexadecimal nor decimal.
    """
    cleaned = text.strip().removeprefix("0x").removeprefix("0X")
    if not cleaned:
        raise ValueError("empty integer response")
    try:
        return int(cleaned, 16)
    except ValueError:
        return int(cleaned, 10)


def parse_float_response(text: str) -> float:
    """Extract the first signed decimal number from a response string."""
    match = re.search(r"[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?", text)
    if match is None:
        raise ValueError(f"no numeric field in response {text!r}")
    return float(match.group(0))


def parse_bool_response(text: str) -> bool:
    """Interpret a 1/0 or ON/OFF response as a boolean."""
    token = text.strip().upper()
    if token in {"1", "ON", "TRUE"}:
        return True
    if token in {"0", "OFF", "FALSE"}:
        return False
    # Some firmware revisions echo the numeric form with padding.
    try:
        return bool(int(token))
    except ValueError as exc:
        raise ValueError(f"cannot interpret {text!r} as boolean") from exc


# %% ===========================================================================
#    TRANSPORT LAYER
# =============================================================================
class SerialTransport:
    """Thread-safe byte transport to the QuickSyn USB virtual COM port.

    Every public method takes a reentrant lock, so the GUI thread and the
    telemetry sampler thread can both talk to the instrument without
    interleaving bytes. The lock is deliberately the only serialisation
    mechanism: the device is half-duplex and cannot service concurrent
    requests, so there is nothing here to parallelise.

    Parameters
    ----------
    on_transaction:
        Optional callback invoked with a :class:`Transaction` after every
        exchange, successful or not. Used to drive the transaction log.
    """

    def __init__(
        self,
        on_transaction: Callable[[Transaction], None] | None = None,
    ) -> None:
        self._port: Any = None
        self._lock = threading.RLock()
        self._on_transaction = on_transaction
        self._last_tx_time: float = 0.0
        self.port_name: str = ""
        self.baudrate: int = DEFAULT_BAUD
        self.intercommand_gap_s: float = DEFAULT_INTERCOMMAND_GAP_S
        self.read_timeout_s: float = DEFAULT_READ_TIMEOUT_S

    # --- Lifecycle ----------------------------------------------------------
    @property
    def is_open(self) -> bool:
        """True when the underlying serial port is open."""
        return self._port is not None and getattr(self._port, "is_open", False)

    def open(
        self,
        port_name: str,
        baudrate: int = DEFAULT_BAUD,
        read_timeout_s: float = DEFAULT_READ_TIMEOUT_S,
    ) -> None:
        """Open the serial port using the vendor-mandated link parameters.

        Parameters
        ----------
        port_name:
            Platform port identifier, for example ``COM3`` or
            ``/dev/ttyUSB0``.
        baudrate:
            Line rate. The QuickSyn ships at 115200 and can be retargeted
            with ``DIAG:BAUD``; change this only after doing so.
        read_timeout_s:
            Per-read timeout.

        Raises
        ------
        TransportError
            If pyserial is unavailable or the port cannot be opened.
        """
        if not HAVE_PYSERIAL:
            raise TransportError(
                "pyserial is not installed; install it or use Simulator mode."
            )
        with self._lock:
            self.close()
            try:
                self._port = serial.Serial(
                    port=port_name,
                    baudrate=baudrate,
                    bytesize=SERIAL_BYTESIZE,
                    parity=SERIAL_PARITY,
                    stopbits=SERIAL_STOPBITS,
                    timeout=read_timeout_s,
                    write_timeout=DEFAULT_WRITE_TIMEOUT_S,
                    xonxoff=SERIAL_XONXOFF,
                    rtscts=SERIAL_RTSCTS,
                    dsrdtr=SERIAL_DSRDTR,
                )
            except Exception as exc:  # pyserial raises several types
                raise TransportError(
                    f"Could not open {port_name}: {exc}"
                ) from exc
            self.port_name = port_name
            self.baudrate = baudrate
            self.read_timeout_s = read_timeout_s
            self._port.reset_input_buffer()
            self._port.reset_output_buffer()

    def close(self) -> None:
        """Close the port if it is open. Safe to call repeatedly."""
        with self._lock:
            if self._port is not None:
                try:
                    self._port.close()
                except Exception:  # pragma: no cover - best effort
                    pass
            self._port = None

    # --- Low-level exchange -------------------------------------------------
    # Timing uses time.perf_counter() throughout. On Windows before Python
    # 3.13, time.monotonic() ticks in 15.6 ms steps (GetTickCount64), which
    # made every latency read 0.0 ms on the first hardware session (0.0.8).
    def _enforce_gap(self) -> None:
        """Sleep so that consecutive transactions are not back-to-back."""
        if self.intercommand_gap_s <= 0.0:
            return
        elapsed = time.perf_counter() - self._last_tx_time
        if elapsed < self.intercommand_gap_s:
            time.sleep(self.intercommand_gap_s - elapsed)

    @staticmethod
    def encode(command: str) -> bytes:
        """Encode a command to bytes and enforce the 64-byte device buffer.

        Parameters
        ----------
        command:
            ASCII command text without a terminator.

        Returns
        -------
        bytes
            The command plus the CR terminator.

        Raises
        ------
        CommandTooLongError
            If the terminated command exceeds ``MAX_COMMAND_BYTES``.
        """
        payload = command.strip().encode("ascii", errors="strict") + TERMINATOR
        if len(payload) > MAX_COMMAND_BYTES:
            raise CommandTooLongError(
                f"{command!r} encodes to {len(payload)} bytes including the "
                f"terminator; the device buffer is {MAX_COMMAND_BYTES} bytes "
                f"[R1]."
            )
        return payload

    def _read_line(self, timeout_s: float) -> str:
        """Read until CR, LF or timeout and return the decoded text.

        [R1] does not state the terminator the instrument appends to its
        responses, so any of CR, LF or CRLF is accepted. See ambiguity
        note 3 in the module header.
        """
        deadline = time.perf_counter() + timeout_s
        chunks = bytearray()
        while time.perf_counter() < deadline:
            byte = self._port.read(1)
            if not byte:
                continue
            if byte in (b"\r", b"\n"):
                if chunks:
                    break
                continue  # tolerate a leading terminator from a prior reply
            chunks.extend(byte)
        return chunks.decode("ascii", errors="replace").strip()

    def _record(self, txn: Transaction) -> None:
        """Forward a completed transaction to the log callback, if any."""
        if self._on_transaction is not None:
            try:
                self._on_transaction(txn)
            except Exception:  # pragma: no cover - logging must never raise
                pass

    def write(self, command: str, settle_s: float = 0.0) -> None:
        """Send a command that produces no response.

        Parameters
        ----------
        command:
            SCPI command text without a terminator.
        settle_s:
            Mandatory post-command wait, from the delay table in [R1].

        Raises
        ------
        TransportError
            If the port is closed or the write fails.
        """
        payload = self.encode(command)
        with self._lock:
            if not self.is_open:
                raise TransportError("Serial port is not open.")
            self._enforce_gap()
            t0 = time.perf_counter()
            t_unix = time.time()
            try:
                self._port.reset_input_buffer()
                self._port.write(payload)
                self._port.flush()
            except Exception as exc:
                self._record(
                    Transaction(
                        t_unix=t_unix,
                        command=command,
                        response=None,
                        latency_s=time.perf_counter() - t0,
                        ok=False,
                        error=str(exc),
                        is_query=False,
                    )
                )
                raise TransportError(f"Write of {command!r} failed: {exc}") from exc
            if settle_s > 0.0:
                time.sleep(settle_s)
            self._last_tx_time = time.perf_counter()
            self._record(
                Transaction(
                    t_unix=t_unix,
                    command=command,
                    response=None,
                    latency_s=self._last_tx_time - t0,
                    ok=True,
                    is_query=False,
                )
            )

    def query(
        self,
        command: str,
        repeat: int = 1,
        timeout_s: float | None = None,
    ) -> str:
        """Send a query and return the response text.

        Parameters
        ----------
        command:
            SCPI query text, normally ending in ``?``.
        repeat:
            Number of times the query is issued before the response is
            taken. [R1] requires two issues for the temperature query on
            the native interfaces; set ``repeat=2`` for that case.
        timeout_s:
            Override for the per-read timeout.

        Returns
        -------
        str
            The stripped response text, which may be empty on timeout.

        Raises
        ------
        TransportError
            If the port is closed or the exchange fails.
        """
        payload = self.encode(command)
        effective_timeout = timeout_s if timeout_s is not None else self.read_timeout_s
        with self._lock:
            if not self.is_open:
                raise TransportError("Serial port is not open.")
            self._enforce_gap()
            t0 = time.perf_counter()
            t_unix = time.time()
            response = ""
            try:
                for issue in range(max(1, repeat)):
                    self._port.reset_input_buffer()
                    self._port.write(payload)
                    self._port.flush()
                    response = self._read_line(effective_timeout)
                    # Intermediate issues of a repeated query are discarded.
                    if issue < repeat - 1:
                        time.sleep(self.intercommand_gap_s)
            except Exception as exc:
                self._record(
                    Transaction(
                        t_unix=t_unix,
                        command=command,
                        response=None,
                        latency_s=time.perf_counter() - t0,
                        ok=False,
                        error=str(exc),
                        is_query=True,
                    )
                )
                raise TransportError(f"Query {command!r} failed: {exc}") from exc
            self._last_tx_time = time.perf_counter()
            self._record(
                Transaction(
                    t_unix=t_unix,
                    command=command,
                    response=response,
                    latency_s=self._last_tx_time - t0,
                    ok=bool(response),
                    error="" if response else "empty response (timeout)",
                    is_query=True,
                )
            )
            if not response:
                raise TransportError(
                    f"No response to {command!r} within {effective_timeout:.3f} s."
                )
            return response


# %% ===========================================================================
#    OFFLINE SIMULATOR
# =============================================================================
class SimulatedTransport(SerialTransport):
    """Drop-in transport that emulates a QuickSyn FSW-0020.

    Useful for exercising the GUI, the logger and the sampler with no
    hardware attached. The state model covers every query this application
    issues; it is not a complete firmware model and makes no attempt to
    reproduce switching-time behaviour beyond a nominal delay.
    """

    def __init__(
        self,
        on_transaction: Callable[[Transaction], None] | None = None,
        model: str = "FSW-0020",
        power_control: bool = True,
    ) -> None:
        super().__init__(on_transaction=on_transaction)
        self._open = False
        self._model = model
        #: False emulates a unit without power-control option 2: POW is
        #: accepted but the level stays at the rated output.
        self.power_control = power_control
        #: False emulates firmware that ignores SCPI POW but obeys the native
        #: 03xxxx command (exercises the "auto" fallback).
        self.scpi_power = True
        #: True when a 10 MHz signal is present at REF IN (STAT? bit 0 is
        #: presence, independent of the source selected).
        self.ext_ref_connected = False
        #: False emulates firmware that ignores SCPI OUTP:ROSC:STAT but obeys
        #: the native 08xx command; refout_control=False ignores both.
        self.scpi_refout = True
        self.refout_control = True
        #: False emulates firmware that does not answer OUTP:ROSC:STAT? (0.0.9).
        self.refout_query_supported = True
        #: False holds STAT? bit 5 set whatever REF OUT does, as on the
        #: FSL-0020 tested (0.0.10).
        self.refout_status_bit_follows = True
        self._state: dict[str, Any] = {
            "freq_mlhz": 10_000_000_000_000,   # 10 GHz default [R1/R2]
            "power_dbm": 13.0,
            "rf_out": False,
            "blanking": False,
            "ref_source": "INT",
            "ref_out": True,
            "pulse": False,
            "am": False,
            "am_dept": 0,
            "fm": False,
            "fm_mode": int(FMMode.FM_WIDE),
            "fm_sens": 0,
            "lock_recovery": True,
            "ref_dac": 30000,
        }
        self._t_start = time.perf_counter()

    @property
    def is_open(self) -> bool:
        """True once :meth:`open` has been called."""
        return self._open

    def open(
        self,
        port_name: str = "SIM",
        baudrate: int = DEFAULT_BAUD,
        read_timeout_s: float = DEFAULT_READ_TIMEOUT_S,
    ) -> None:
        """Mark the simulated link as open."""
        with self._lock:
            self._open = True
            self.port_name = port_name
            self.baudrate = baudrate
            self.read_timeout_s = read_timeout_s

    def close(self) -> None:
        """Mark the simulated link as closed."""
        with self._lock:
            self._open = False

    # --- Command interpretation --------------------------------------------
    def _apply(self, command: str) -> str | None:
        """Native commands the simulator knows (Set Output Power), else SCPI."""
        text = command.strip().upper()
        if re.fullmatch(r"03[0-9A-F]{4}", text):    # native Set Output Power
            if self.power_control:
                raw = int(text[2:], 16)
                tenths = raw - 0x10000 if raw & 0x8000 else raw
                self._state["power_dbm"] = tenths / 10.0
            return None
        if text == NATIVE_GET_POWER:                # native Get Power
            return f"{int(round(self._state['power_dbm'] * 10)) & 0xFFFF:04X}"
        if re.fullmatch(r"(06|08|0F)0[01]", text):  # native one-byte switches
            on = text.endswith("1")
            if text.startswith(NATIVE_REF_SOURCE):
                self._state["ref_source"] = "EXT" if on else "INT"
            elif text.startswith(NATIVE_REF_OUTPUT):
                if self.refout_control:
                    self._state["ref_out"] = on
            else:
                self._state["rf_out"] = on
            return None
        if text == "07":                            # native Ref Source query
            return "01" if self._state["ref_source"] == "EXT" else "00"
        return self._apply_scpi(command)

    def _apply_scpi(self, command: str) -> str | None:
        """Update simulated state and return a response for queries."""
        cmd = command.strip()
        upper = cmd.upper()
        head, _, arg = cmd.partition(" ")
        head_u = head.upper()
        arg = arg.strip()

        match head_u:
            case "*IDN?":
                # The order confirmed on hardware (0.0.8): manufacturer,
                # model, option word, serial, firmware. Option word 007F =
                # options 1-7; firmware 0008 as on the FSL-0020 tested.
                return f"Phase Matrix,{self._model},0000007f,1530200001,0008"
            case "*RST":
                # Factory defaults per [R1] Table 2a: RF output off, 10 GHz,
                # +15 dBm (FSW-0010) / +13 dBm (FSW-0020), internal
                # reference, reference output on, modulation off,
                # sensitivities 0. Blanking is left untouched because the
                # two manuals disagree (ambiguity note 1).
                self._state.update(
                    freq_mlhz=10_000_000_000_000,
                    power_dbm=13.0 if "0020" in self._model else 15.0,
                    rf_out=False,
                    pulse=False,
                    am=False,
                    fm=False,
                    am_dept=0,
                    fm_sens=0,
                )
                return None
            case "*SAV" | "*RCL":
                return None
            case "FREQ":
                self._state["freq_mlhz"] = self._parse_freq(arg)
                return None
            case "FREQ?":
                return str(int(self._state["freq_mlhz"]))
            case "POW":
                if self.power_control and self.scpi_power:
                    self._state["power_dbm"] = quantise_power_dbm(
                        parse_float_response(arg)
                    )
                return None
            case "POW?":
                return f"{self._state['power_dbm']:.1f}"
            case "OUTP:STAT":
                self._state["rf_out"] = arg.upper() == "ON"
                return None
            case "OUTP:STAT?":
                return "1" if self._state["rf_out"] else "0"
            case "OUTP:BLAN":
                self._state["blanking"] = arg.upper() == "ON"
                return None
            case "OUTP:BLAN?":
                return "1" if self._state["blanking"] else "0"
            case "OUTP:ROSC:STAT":
                if self.scpi_refout and self.refout_control:
                    self._state["ref_out"] = arg.upper() == "ON"
                return None
            case "OUTP:ROSC:STAT?":
                if not self.refout_query_supported:
                    return None                  # no reply: the query times out
                return "1" if self._state["ref_out"] else "0"
            case "ROSC:SOUR":
                self._state["ref_source"] = arg.upper()
                return None
            case "ROSC:SOUR?":
                return str(self._state["ref_source"])
            case "PULM:STAT":
                self._state["pulse"] = arg.upper() == "ON"
                return None
            case "PULM:STAT?":
                return "1" if self._state["pulse"] else "0"
            case "AM:STAT":
                self._state["am"] = arg.upper() == "ON"
                return None
            case "AM:STAT?":
                return "1" if self._state["am"] else "0"
            case "AM:DEPT":
                self._state["am_dept"] = int(parse_float_response(arg))
                return None
            case "AM:DEPT?":
                return str(self._state["am_dept"])
            case "FM:STAT":
                self._state["fm"] = arg.upper() == "ON"
                return None
            case "FM:STAT?":
                return "1" if self._state["fm"] else "0"
            case "FM:MODE":
                self._state["fm_mode"] = int(parse_float_response(arg))
                return None
            case "FM:MODE?":
                return str(self._state["fm_mode"])
            case "FM:SENS":
                self._state["fm_sens"] = int(parse_float_response(arg))
                return None
            case "FM:SENS?":
                return str(self._state["fm_sens"])
            case "FREQ:LRSTAT":
                self._state["lock_recovery"] = arg.upper() == "ON"
                return None
            case "FREQ:LRSTAT?":
                return "1" if self._state["lock_recovery"] else "0"
            case "DIAG:CAL:REF:DAC":
                self._state["ref_dac"] = int(parse_float_response(arg))
                return None
            case "DIAG:CAL:REF:DAC?":
                return str(self._state["ref_dac"])
            case "STAT?":
                # The hardware replies "0xA1" (first session, 0.0.8), not the
                # "00A8" form of the [R1] Table 5 example.
                return f"0x{self._status_byte():X}"
            case "DIAG:MOD?":
                return f"0x{self._mod_byte():X}"
            case "DIAG:BAUD?":
                return str(self.baudrate)

        if upper.startswith("DIAG:MEAS?"):
            # Lazy thermal ramp towards 40 C plus a little noise.
            age = time.perf_counter() - self._t_start
            temp = 29.0 + 11.0 * (1.0 - math.exp(-age / 900.0))
            temp += 0.05 * math.sin(age / 7.0)
            return f"{temp:.1f}"

        # Everything else (sweeps, lists, LIST:*, SWE:*) is accepted silently.
        return None

    @staticmethod
    def _parse_freq(arg: str) -> int:
        """Parse a ``FREQ`` argument into millihertz."""
        token = arg.strip().upper().replace(" ", "")
        multipliers = {"GHZ": 1e12, "MHZ": 1e9, "KHZ": 1e6, "MLHZ": 1.0,
                       "HZ": 1e3}
        for suffix, scale in multipliers.items():
            if token.endswith(suffix):
                return int(round(float(token[: -len(suffix)]) * scale))
        return int(round(float(token)))

    def _status_byte(self) -> int:
        """Assemble a plausible ``STAT?`` low byte from simulated state."""
        value = 0
        if self.ext_ref_connected:
            value |= 1 << StatusBit.EXT_REF
        if self._state["ref_source"] == "EXT" and not self.ext_ref_connected:
            value |= 1 << StatusBit.REF_UNLOCKED   # nothing to lock to
        # Locked: leave RF_UNLOCKED and REF_UNLOCKED clear.
        if self._state["rf_out"]:
            value |= 1 << StatusBit.RF_OUTPUT_ON
        if self._state["ref_out"] or not self.refout_status_bit_follows:
            value |= 1 << StatusBit.REF_OUTPUT_ON
        if self._state["blanking"]:
            value |= 1 << StatusBit.BLANKING_ON
        if self._state["lock_recovery"]:
            value |= 1 << StatusBit.LOCK_RECOVERY
        return value

    def _mod_byte(self) -> int:
        """Assemble a plausible ``DIAG:MOD?`` low byte."""
        value = 0
        if self._state["pulse"]:
            value |= 1 << ModBit.PULSE
        if self._state["am"]:
            value |= 1 << ModBit.AM
        if self._state["fm"]:
            mode = FMMode(self._state["fm_mode"])
            bit = {
                FMMode.PHASE: ModBit.PHASE,
                FMMode.FM_WIDE: ModBit.FM_WIDE,
                FMMode.FM_NARROW1: ModBit.FM_NB1,
                FMMode.FM_NARROW2: ModBit.FM_NB2,
            }[mode]
            value |= 1 << bit
        return value

    # --- Transport interface ------------------------------------------------
    def write(self, command: str, settle_s: float = 0.0) -> None:
        """Apply a simulated command and record the transaction."""
        self.encode(command)  # still enforce the 64-byte limit
        with self._lock:
            if not self._open:
                raise TransportError("Simulated port is not open.")
            t0 = time.perf_counter()
            t_unix = time.time()
            self._apply(command)
            time.sleep(max(settle_s, 0.0005))
            self._record(
                Transaction(
                    t_unix=t_unix,
                    command=command,
                    response=None,
                    latency_s=time.perf_counter() - t0,
                    ok=True,
                    is_query=False,
                )
            )

    def query(
        self,
        command: str,
        repeat: int = 1,
        timeout_s: float | None = None,
    ) -> str:
        """Return a simulated response and record the transaction."""
        self.encode(command)
        with self._lock:
            if not self._open:
                raise TransportError("Simulated port is not open.")
            t0 = time.perf_counter()
            t_unix = time.time()
            response = ""
            for _ in range(max(1, repeat)):
                response = self._apply(command) or ""
                time.sleep(0.0015)  # approximate a real round trip
            self._record(
                Transaction(
                    t_unix=t_unix,
                    command=command,
                    response=response,
                    latency_s=time.perf_counter() - t0,
                    ok=bool(response),
                    error="" if response else "empty response (timeout)",
                    is_query=True,
                )
            )
            if not response:
                raise TransportError(f"No simulated response to {command!r}.")
            return response


# %% ===========================================================================
#    SCPI DRIVER
# =============================================================================
class QuickSyn:
    """SCPI driver for the QuickSyn synthesiser family.

    Thin, explicit wrapper: one method per documented SCPI mnemonic, with
    range checking against the model capability table and the mandatory
    settling delays from [R1] applied automatically.

    Parameters
    ----------
    transport:
        An open or closeable :class:`SerialTransport` (or
        :class:`SimulatedTransport`).
    on_state_event:
        Optional callback ``(parameter, value, source)`` fired whenever a
        command changes the generated-signal state. Drives state_events.csv.
    """

    def __init__(
        self,
        transport: SerialTransport,
        on_state_event: Callable[[str, Any, str], None] | None = None,
    ) -> None:
        self.io = transport
        self.identity = Identity()
        self.capability: ModelCapability = FALLBACK_CAPABILITY
        self._on_state_event = on_state_event
        #: Mirrors whether FM is believed to be on, so that frequency
        #: changes can honour the 1 ms FM settling requirement [R1].
        self._fm_active: bool = False
        #: None until OUTP:ROSC:STAT? has been tried; False once it has failed
        #: (then STAT? bit 5 alone reports the 10 MHz output) (0.0.9).
        self.refout_query_supported: bool | None = None
        #: "auto" tries OUTP:ROSC:STAT first; "native" once the native 08xx
        #: command has worked where the SCPI form did not (0.0.9).
        self.reference_output_command: str = "auto"
        #: None until known; False once STAT? bit 5 has been seen not to
        #: follow the 10 MHz output (FSL-0020: REF OUT switches, bit 5 stays
        #: set) (0.0.10).
        self.refout_status_reliable: bool | None = None
        #: Last 10 MHz output state sent, for display when the unit does not
        #: report it.
        self.refout_commanded: bool | None = None

    # --- Event plumbing -----------------------------------------------------
    def _emit_state(self, parameter: str, value: Any, source: str = "gui") -> None:
        """Report a commanded state change to the session logger."""
        if self._on_state_event is not None:
            try:
                self._on_state_event(parameter, value, source)
            except Exception:  # pragma: no cover
                pass

    # --- Identity and capability -------------------------------------------
    def identify(self) -> Identity:
        """Issue ``*IDN?`` and populate :attr:`identity` and :attr:`capability`.

        Returns
        -------
        Identity
            The decoded identity record.

        Notes
        -----
        [R1] Table 5 shows the response as five comma-separated fields but
        does not define them. The order manufacturer, model, option word,
        serial, firmware was confirmed on hardware (ambiguity note 2); up to
        0.0.7 fields 4 and 5 were swapped. The firmware field is not
        documented as decimal or hexadecimal, so both are attempted. Every
        raw field is retained in ``Identity.fields`` regardless.
        """
        raw = self.io.query("*IDN?")
        parts = [f.strip() for f in raw.split(",")]
        ident = Identity(raw=raw, fields=list(parts))
        ident.manufacturer = parts[0] if len(parts) > 0 else ""
        ident.model = parts[1] if len(parts) > 1 else ""
        ident.options = parts[2] if len(parts) > 2 else ""
        ident.serial = parts[3] if len(parts) > 3 else ""
        ident.firmware = parts[4] if len(parts) > 4 else ""

        token = ident.firmware.strip()
        if token:
            try:
                ident.firmware_value = int(token, 10)
                ident.firmware_base = "decimal"
            except ValueError:
                try:
                    ident.firmware_value = int(token, 16)
                    ident.firmware_base = "hexadecimal"
                except ValueError:
                    ident.firmware_value = None
                    ident.firmware_base = "unparsed"

        self.identity = ident
        self.capability = MODEL_TABLE.get(
            ident.model.upper().strip(), FALLBACK_CAPABILITY
        )
        return ident

    # --- Frequency ----------------------------------------------------------
    def set_frequency(self, freq_hz: float, check_limits: bool = True) -> float:
        """Set the carrier frequency with ``FREQ``.

        Parameters
        ----------
        freq_hz:
            Requested carrier in hertz.
        check_limits:
            When True the value is validated against the model capability
            table, including the option-1 extended lower limit.

        Returns
        -------
        float
            The frequency actually commanded, after quantisation to the
            model's resolution.

        Raises
        ------
        ParameterError
            If ``check_limits`` is set and the value is out of range.
        """
        cap = self.capability
        if check_limits:
            lower = cap.f_min_opt1_hz if cap.f_min_opt1_hz is not None else cap.f_min_hz
            if not (lower <= freq_hz <= cap.f_max_hz):
                raise ParameterError(
                    f"{freq_hz / 1e9:.6f} GHz is outside the "
                    f"{lower / 1e9:.3f} - {cap.f_max_hz / 1e9:.3f} GHz range "
                    f"of the {cap.model}."
                )
        resolution = cap.f_resolution_hz
        quantised = round(freq_hz / resolution) * resolution
        mlhz = hz_to_mlhz(quantised)
        # Frequency changes with FM active require a 1 ms settle [R1].
        settle = WAIT_FM_FREQ_CHANGE_S if self._fm_active else 0.0
        self.io.write(f"FREQ {mlhz}", settle_s=settle)
        self._emit_state("frequency_hz", quantised)
        return quantised

    def get_frequency(self) -> float:
        """Read the carrier frequency with ``FREQ?``. Returns hertz."""
        return mlhz_to_hz(parse_float_response(self.io.query("FREQ?")))

    # --- Power --------------------------------------------------------------
    def set_power(self, power_dbm: float, check_limits: bool = True,
                  command_set: str = "scpi") -> float:
        """Set the output level with ``POW`` (or the native ``03`` command).

        Parameters
        ----------
        power_dbm:
            Requested level in dBm; quantised to 0.1 dB.
        check_limits:
            Validate against the model's levelled power-control range.
        command_set:
            "scpi" sends ``POW +12.0``; "native" sends ``030078``.

        Notes
        -----
        [R1, Table 5] gives the SCPI syntax as ``POW +/- XX.X [DBM]`` with
        only a negative example, so the sign is always written explicitly.

        Returns
        -------
        float
            The quantised level actually commanded.
        """
        value = quantise_power_dbm(power_dbm)
        cap = self.capability
        if check_limits:
            self.require_power_control()
        if check_limits and not (cap.p_min_dbm <= value <= cap.p_max_dbm):
            raise ParameterError(
                f"{value:+.1f} dBm is outside the {cap.p_min_dbm:+.1f} to "
                f"{cap.p_max_dbm:+.1f} dBm control range of the {cap.model} "
                f"(power control requires option 2)."
            )
        self._write_power(value, command_set)
        self._emit_state("power_dbm", value)
        return value

    def _write_power(self, value: float, command_set: str) -> None:
        """Send one already-quantised level with the chosen command set."""
        if command_set == "native":
            self.io.write(native_power_command(value))
        elif command_set == "scpi":
            self.io.write(f"POW {value:+.1f}")
        else:
            raise ValueError(f"command_set must be 'scpi' or 'native', not {command_set!r}")

    def get_power(self) -> float:
        """Read the output level with ``POW?``. Returns dBm."""
        return parse_float_response(self.io.query("POW?"))

    def get_power_native(self) -> float:
        """Read the output level with the native Get Power query (``0D``).

        An independent check on ``POW?`` during bring-up [R1, Table 4]: if
        the two disagree, one of them reports a stored setting rather than
        the level in force.
        """
        return decode_native_power(self.io.query(NATIVE_GET_POWER))

    def require_power_control(self) -> None:
        """Refuse level changes on models with a fixed output level.

        Raises
        ------
        ParameterError
            The detected model lists no power-control option [R4].
        """
        cap = self.capability
        if not cap.has_power_control:
            raise ParameterError(
                f"The {cap.model} has a fixed output level ({cap.p_default_dbm:+.1f} dBm "
                f"typical) and no power-control option [R4]; POW cannot change it."
            )

    def set_power_checked(self, power_dbm: float,
                          command_set: str = "auto") -> tuple[float, float, str]:
        """Set the level and read it back with ``POW?``.

        Parameters
        ----------
        command_set:
            "scpi", "native", or "auto": SCPI first and, if ``POW?`` shows
            the level did not change, the native command [R1, Table 2a].

        Returns
        -------
        tuple
            (level commanded, level reported by ``POW?``, command set that
            produced the reported level). A difference after both command
            sets means the unit did not apply the level; on an FSW the usual
            cause is that power-control option 2 is not fitted ([R1] marks
            Set Output Power "when option is present").
        """
        if command_set not in POWER_COMMAND_SETS:
            raise ValueError(f"command_set must be one of {POWER_COMMAND_SETS}")
        first = "native" if command_set == "native" else "scpi"
        commanded = self.set_power(power_dbm, command_set=first)
        reported = self.get_power()
        used = first
        if command_set == "auto" and abs(reported - commanded) > POWER_READBACK_TOL_DB:
            self._write_power(commanded, "native")
            reported = self.get_power()
            used = "native"
        return commanded, reported, used

    def set_frequency_checked(self, freq_hz: float) -> tuple[float, float]:
        """Set the carrier and read it back; returns (commanded, reported) in Hz."""
        commanded = self.set_frequency(freq_hz)
        return commanded, self.get_frequency()

    # --- Output and reference control --------------------------------------
    def set_rf_output(self, enabled: bool) -> None:
        """Enable or mute the RF output with ``OUTP:STAT``."""
        self.io.write(f"OUTP:STAT {'ON' if enabled else 'OFF'}")
        self._emit_state("rf_output", enabled)

    def get_rf_output(self) -> bool:
        """Read the RF output state with ``OUTP:STAT?``."""
        return parse_bool_response(self.io.query("OUTP:STAT?"))

    def set_blanking(self, enabled: bool) -> None:
        """Enable or disable blanking with ``OUTP:BLAN``.

        With blanking on, RF output is suppressed while the synthesiser
        settles on a new frequency [R2, Step 5-2].
        """
        self.io.write(f"OUTP:BLAN {'ON' if enabled else 'OFF'}")
        self._emit_state("blanking", enabled)

    def get_blanking(self) -> bool:
        """Read the blanking state with ``OUTP:BLAN?``."""
        return parse_bool_response(self.io.query("OUTP:BLAN?"))

    def set_reference_source(self, source: RefSource | str) -> None:
        """Select internal or external reference with ``ROSC:SOUR``.

        The external reference must be 10 MHz within +/-2 ppm, at
        +5 dBm +/-5 dBm into 50 ohm [R2, Step 5-2; R3]. ``source`` may be
        a :class:`RefSource` or its text ("INT"/"EXT"): PySide6 returns a
        StrEnum stored as combo-box data as a plain str (0.0.8 fix).
        """
        source = RefSource(str(source).strip().upper())
        self.io.write(f"ROSC:SOUR {source.value}")
        self._emit_state("reference_source", source.value)

    def get_reference_source(self) -> RefSource:
        """Read the reference selection with ``ROSC:SOUR?``."""
        token = self.io.query("ROSC:SOUR?").strip().upper()
        return RefSource.EXTERNAL if token.startswith("EXT") else RefSource.INTERNAL

    def set_reference_output(self, enabled: bool) -> None:
        """Enable or mute the 10 MHz reference output (``OUTP:ROSC:STAT``)."""
        self.io.write(f"OUTP:ROSC:STAT {'ON' if enabled else 'OFF'}")
        self._emit_state("reference_output", enabled)

    def get_reference_output(self) -> bool:
        """Read the reference output state with ``OUTP:ROSC:STAT?``."""
        return parse_bool_response(self.io.query("OUTP:ROSC:STAT?"))

    def get_reference_output_optional(self) -> bool | None:
        """``OUTP:ROSC:STAT?``, or None where the unit does not answer it.

        The query is in [R1, Table 5] but was never seen to answer on the
        FSL-0020 tested, so the first failure (time-out or unparsable reply)
        marks it unsupported for the session instead of failing every read.
        """
        if self.refout_query_supported is False:
            return None
        try:
            state = self.get_reference_output()
        except (TransportError, ValueError):
            self.refout_query_supported = False
            return None
        self.refout_query_supported = True
        return state

    def _reference_output_followed(self, enabled: bool) -> tuple[bool | None, StatusWord, bool]:
        """Read the 10 MHz output state back: (query state or None, STAT?, followed).

        OUTP:ROSC:STAT? decides when the unit answers it; a STAT? bit 5 that
        disagrees with it marks the bit unreliable (0.0.10). Without the
        query, bit 5 decides unless it is already known to be unreliable.
        """
        reported = self.get_reference_output_optional()
        status = self.get_status()
        if reported is not None:
            if status.ref_output_on != reported:
                self.refout_status_reliable = False
            return reported, status, reported == enabled
        return reported, status, status.ref_output_on == enabled

    def reference_output_state(self, reported: bool | None,
                               status: StatusWord) -> bool | None:
        """Best knowledge of the 10 MHz output: the query, else bit 5, else None.

        None means this unit does not report the state (no OUTP:ROSC:STAT?
        and a STAT? bit 5 that does not follow).
        """
        if reported is not None:
            return reported
        if self.refout_status_reliable is False:
            return None
        return status.ref_output_on

    def set_reference_output_checked(self, enabled: bool) -> tuple[bool | None, StatusWord, str]:
        """Switch the 10 MHz reference output and read it back.

        Sends ``OUTP:ROSC:STAT`` (unless the native command has already been
        found to be the one that works), then reads ``STAT?`` bit 5 and, where
        the unit answers it, ``OUTP:ROSC:STAT?``. If the output did not
        follow, sends the native Reference Output command (``0800``/``0801``
        [R1, Table 2a]) and reads again; if that worked, the native command
        is used directly from then on. On the FSL-0020 tested the SCPI form
        left STAT? bit 5 set, while NI's panel (native commands) and a power
        meter showed REF OUT switching off (0.0.8/0.0.9).

        Returns
        -------
        tuple
            (``OUTP:ROSC:STAT?`` state or None if unsupported, decoded
            ``STAT?``, command used last: "scpi" or "native").
        """
        native = native_switch_command(NATIVE_REF_OUTPUT, enabled)
        self.refout_commanded = enabled
        if self.reference_output_command == "native":
            self.io.write(native)
            self._emit_state("reference_output", enabled)
            reported, status, _ = self._reference_output_followed(enabled)
            return reported, status, "native"
        if self.refout_status_reliable is False and self.refout_query_supported is False:
            # Nothing on this unit reports the output (0.0.10): send the SCPI
            # form, which switches REF OUT on the FSL-0020 tested, and stop.
            self.set_reference_output(enabled)
            return None, self.get_status(), "scpi"
        self.set_reference_output(enabled)
        reported, status, followed = self._reference_output_followed(enabled)
        if followed:
            return reported, status, "scpi"
        self.io.write(native)
        reported, status, followed = self._reference_output_followed(enabled)
        if followed:
            self.reference_output_command = "native"
        elif reported is None:
            # Neither command moved bit 5 and there is no query: on the
            # FSL-0020 both switch REF OUT while bit 5 stays set (power meter,
            # 2026-10-14), so the bit is taken as not reporting the output.
            self.refout_status_reliable = False
        return reported, status, "native"

    def set_reference_source_checked(
        self, source: RefSource | str
    ) -> tuple[RefSource, StatusWord, str]:
        """Select the reference and read it back with ``ROSC:SOUR?``.

        Falls back to the native Select Ref. Source command (``0600`` /
        ``0601`` [R1, Table 2a]) if the SCPI form is not reflected.

        Returns
        -------
        tuple
            (source reported by ``ROSC:SOUR?``, decoded ``STAT?``, command
            set used last).
        """
        source = RefSource(str(source).strip().upper())
        self.set_reference_source(source)
        reported = self.get_reference_source()
        used = "scpi"
        if reported != source:
            self.io.write(native_switch_command(NATIVE_REF_SOURCE,
                                                source is RefSource.EXTERNAL))
            used = "native"
            reported = self.get_reference_source()
        return reported, self.get_status(), used

    def set_lock_recovery(self, enabled: bool) -> None:
        """Enable or disable automatic lock recovery (``FREQ:LRSTAT``).

        [R2] states three recovery attempts are made; [R1] Table 2a states
        only one retry per frequency is allowed. The behaviour is firmware
        dependent and is not relied upon here.
        """
        self.io.write(f"FREQ:LRSTAT {'ON' if enabled else 'OFF'}")
        self._emit_state("lock_recovery", enabled)

    def get_lock_recovery(self) -> bool:
        """Read the lock-recovery state with ``FREQ:LRSTAT?``."""
        return parse_bool_response(self.io.query("FREQ:LRSTAT?"))

    # --- Status, modulation readback and temperature ------------------------
    def get_status(self) -> StatusWord:
        """Read and decode ``STAT?``."""
        return StatusWord.from_raw(parse_int_response(self.io.query("STAT?")))

    def get_modulation_status(self) -> ModulationWord:
        """Read and decode ``DIAG:MOD?``."""
        return ModulationWord.from_raw(
            parse_int_response(self.io.query("DIAG:MOD?"))
        )

    def get_temperature(self, double_query: bool | None = None) -> float:
        """Read the internal temperature with ``DIAG:MEAS? 21``.

        Parameters
        ----------
        double_query:
            Issue the query twice before taking the response. [R1] requires
            this for the native-interface temperature query; whether it
            applies to the SCPI form is not stated, so the default comes
            from ``TEMPERATURE_DOUBLE_QUERY``.

        Returns
        -------
        float
            Internal temperature in degrees Celsius. [R2] warns that the
            internal temperature must be kept below +75 C.
        """
        repeat = 2 if (
            TEMPERATURE_DOUBLE_QUERY if double_query is None else double_query
        ) else 1
        return parse_float_response(self.io.query("DIAG:MEAS? 21", repeat=repeat))

    # --- Modulation ---------------------------------------------------------
    def set_pulse_modulation(self, enabled: bool) -> None:
        """Enable or disable pulse modulation with ``PULM:STAT``.

        The PULSE input is CMOS, +5 V for RF on and 0 V for RF off, with an
        internal pull-up so an unconnected input leaves RF on [R2, R3].
        """
        self.io.write(f"PULM:STAT {'ON' if enabled else 'OFF'}")
        self._emit_state("pulse_modulation", enabled)

    def set_am(self, enabled: bool) -> None:
        """Enable or disable amplitude modulation with ``AM:STAT``."""
        self.io.write(f"AM:STAT {'ON' if enabled else 'OFF'}")
        self._emit_state("am_modulation", enabled)

    def set_am_depth(self, dac_counts: int) -> None:
        """Set AM sensitivity with ``AM:DEPT``.

        Parameters
        ----------
        dac_counts:
            12-bit DAC code, 0 to 4095. [R4] notes AM sensitivity is
            frequency dependent and user defined, so the code does not map
            to a fixed modulation depth.
        """
        if not (MOD_DAC_MIN <= dac_counts <= MOD_DAC_MAX):
            raise ParameterError(
                f"AM sensitivity must be {MOD_DAC_MIN}-{MOD_DAC_MAX} counts."
            )
        self.io.write(f"AM:DEPT {dac_counts}")
        self._emit_state("am_sensitivity_counts", dac_counts)

    def get_am_depth(self) -> int:
        """Read AM sensitivity with ``AM:DEPT?``."""
        return int(parse_float_response(self.io.query("AM:DEPT?")))

    def set_fm(self, enabled: bool) -> None:
        """Enable or disable frequency/phase modulation with ``FM:STAT``."""
        self.io.write(f"FM:STAT {'ON' if enabled else 'OFF'}")
        self._fm_active = enabled
        self._emit_state("fm_modulation", enabled)

    def set_fm_mode(self, mode: FMMode) -> None:
        """Select the FM/phase mode with ``FM:MODE``."""
        mode = FMMode(int(mode))           # accept a plain int from a combo box
        self.io.write(f"FM:MODE {int(mode)}")
        self._emit_state("fm_mode", mode.name)

    def get_fm_mode(self) -> FMMode:
        """Read the FM/phase mode with ``FM:MODE?``."""
        return FMMode(int(parse_float_response(self.io.query("FM:MODE?"))))

    def set_fm_sensitivity(self, dac_counts: int) -> None:
        """Set FM sensitivity with ``FM:SENS`` (12-bit DAC code)."""
        if not (MOD_DAC_MIN <= dac_counts <= MOD_DAC_MAX):
            raise ParameterError(
                f"FM sensitivity must be {MOD_DAC_MIN}-{MOD_DAC_MAX} counts."
            )
        self.io.write(f"FM:SENS {dac_counts}")
        self._emit_state("fm_sensitivity_counts", dac_counts)

    def get_fm_sensitivity(self) -> int:
        """Read FM sensitivity with ``FM:SENS?``."""
        return int(parse_float_response(self.io.query("FM:SENS?")))

    # --- Reset, states and reference DAC ------------------------------------
    def reset(self) -> None:
        """Issue ``*RST`` and honour the 2 ms settling requirement [R1]."""
        self.io.write("*RST", settle_s=WAIT_RESET_S)
        self._fm_active = False
        self._emit_state("reset", True)

    def save_state(self, slot: int) -> None:
        """Store the current state in flash with ``*SAV`` (slot 1 or 2).

        A 100 ms wait is required before the next command [R1, Table 2a].
        """
        if slot not in (1, 2):
            raise ParameterError("*SAV accepts slot 1 or 2 only.")
        self.io.write(f"*SAV {slot}", settle_s=WAIT_SAVE_STATE_S)
        self._emit_state("save_state_slot", slot)

    def recall_state(self, slot: int) -> None:
        """Restore a state with ``*RCL`` (0 = factory, 1 or 2 = user).

        A 50 ms wait is required before the next command [R1, Table 2a].
        """
        if slot not in (0, 1, 2):
            raise ParameterError("*RCL accepts slot 0, 1 or 2 only.")
        self.io.write(f"*RCL {slot}", settle_s=WAIT_RESTORE_STATE_S)
        self._emit_state("recall_state_slot", slot)

    def set_reference_dac(self, counts: int) -> None:
        """Trim the internal OCXO with ``DIAG:CAL:REF:DAC``.

        Parameters
        ----------
        counts:
            16-bit DAC code, 0 to 65535.

        Warnings
        --------
        This writes the reference calibration tuning value. [R1] notes the
        hardware takes a few seconds to update, and [R3] Step 4-2 describes
        the OCXO calibration against a 10 MHz standard, which the
        Calibration tab follows (0.0.10). Changing it outside that procedure
        de-calibrates the unit; [R3] says the value is volatile until NI's
        panel stores it, so the tab can re-send a saved value on connect.
        """
        if not (REF_DAC_MIN <= counts <= REF_DAC_MAX):
            raise ParameterError(
                f"Reference DAC must be {REF_DAC_MIN}-{REF_DAC_MAX} counts."
            )
        self.io.write(f"DIAG:CAL:REF:DAC {counts}", settle_s=WAIT_REF_DAC_S)
        self._emit_state("reference_dac_counts", counts)

    def get_reference_dac(self) -> int:
        """Read the internal reference DAC with ``DIAG:CAL:REF:DAC?``."""
        return int(parse_float_response(self.io.query("DIAG:CAL:REF:DAC?")))

    # --- List mode ----------------------------------------------------------
    def erase_list(self) -> None:
        """Erase the list table with ``LIST:ERAS`` (200 ms wait) [R1]."""
        self.io.write("LIST:ERAS", settle_s=WAIT_ERASE_LIST_S)
        self._emit_state("list_erased", True)

    def write_list_point(self, point: ListPoint) -> None:
        """Define one list point with ``LIST:PVEC``.

        Parameters
        ----------
        point:
            The point definition. When ``save_to_flash`` is False the point
            is held in volatile memory only, which is the vendor's
            recommended practice because it avoids wearing and populating
            non-volatile user memory [R5].

        Notes
        -----
        The argument order is point number, frequency, power, dwell, pulse
        modulation, RF output, and an optional ``F`` flag that commits the
        point to flash [R1, Table 5]. A flash write needs 300 ms of settling
        and a RAM-only write needs 100 us [R1, Table 2b].
        """
        if not (LIST_POINT_MIN <= point.index <= LIST_POINT_MAX):
            raise ParameterError(
                f"List point index must be {LIST_POINT_MIN}-{LIST_POINT_MAX}."
            )
        if not (DWELL_MIN_US <= point.dwell_us <= DWELL_MAX_US):
            raise ParameterError(
                f"Dwell must be {DWELL_MIN_US}-{DWELL_MAX_US} us."
            )
        args = (
            f"{point.index},"
            f"{format_frequency(point.freq_hz)},"
            f"{quantise_power_dbm(point.power_dbm):.1f}dBm,"
            f"{format_dwell(point.dwell_us)},"
            f"{'ON' if point.pulse_mod else 'OFF'},"
            f"{'ON' if point.rf_output else 'OFF'}"
        )
        if point.save_to_flash:
            args += ",F"
        command = f"LIST:PVEC {args}"
        _check_compound_length(
            command,
            "Round the point frequency to fewer significant digits.",
        )
        settle = (
            WAIT_LIST_POINT_FLASH_S if point.save_to_flash
            else WAIT_LIST_POINT_RAM_S
        )
        self.io.write(command, settle_s=settle)

    def save_list(self, n_points: int) -> None:
        """Commit the list table to flash with ``LIST:SAV``.

        A wait of 50 ms plus 2.5 ms per point is required [R1, Table 2b].
        """
        settle = WAIT_LIST_SAVE_BASE_S + WAIT_LIST_SAVE_PER_POINT_S * max(n_points, 0)
        self.io.write("LIST:SAV", settle_s=settle)
        self._emit_state("list_saved_points", n_points)

    def run_list_point(self, index: int) -> None:
        """Jump to a single list point with ``LIST:PVEC:RUN``."""
        if not (LIST_POINT_MIN <= index <= LIST_POINT_MAX):
            raise ParameterError("List point index out of range.")
        self.io.write(f"LIST:PVEC:RUN {index}")
        self._emit_state("list_point_run", index)

    def setup_list(
        self,
        dwell_us: int,
        run_count: int,
        trigger: TriggerMode,
        direction: SweepDirection,
        run_now: bool = False,
    ) -> None:
        """Configure, and optionally start, list traversal with ``LIST:SETUP``.

        Parameters
        ----------
        dwell_us:
            Global dwell in microseconds; the per-point dwell is used when
            this is zero.
        run_count:
            Number of traversals, 1 to 32767, or 0 for infinite.
        trigger:
            Software, full-list or per-point triggering. In per-point
            trigger mode the minimum pulse period is 150 us [R1, Table 2b].
        direction:
            Up, down, or up-and-down.
        run_now:
            Append the optional ``RUN`` field so traversal starts at once.

        Warnings
        --------
        A list command cannot be executed with FM on [R1, Table 2b].
        """
        if self._fm_active:
            raise ParameterError(
                "List mode cannot run while FM is enabled [R1, Table 2b]. "
                "Turn FM off first."
            )
        if not (0 <= run_count <= RUN_COUNT_MAX):
            raise ParameterError(f"Run count must be 0-{RUN_COUNT_MAX}.")
        args = (
            f"{format_dwell(dwell_us)},{run_count},"
            f"{int(trigger)},{int(direction)}"
        )
        if run_now:
            args += ",RUN"
        self.io.write(f"LIST:SETUP {args}")
        self._emit_state(
            "list_setup",
            {
                "dwell_us": dwell_us,
                "run_count": run_count,
                "trigger": TriggerMode(int(trigger)).name,
                "direction": SweepDirection(int(direction)).name,
                "run_now": run_now,
            },
        )

    def start_list(self, run_count: int) -> None:
        """Start list execution with ``LIST:STAR`` (0 means infinite)."""
        self.io.write(f"LIST:STAR {run_count}")
        self._emit_state("list_started", run_count)

    def stop_list(self) -> None:
        """Halt list execution with ``LIST:STOP``."""
        self.io.write("LIST:STOP")
        self._emit_state("list_stopped", True)

    # --- Sweeps -------------------------------------------------------------
    def setup_fast_frequency_sweep(
        self,
        start_hz: float,
        stop_hz: float,
        n_points: int,
        power_dbm: float,
        dwell_us: int,
        run_count: int,
        trigger: TriggerMode,
        direction: SweepDirection,
        run_now: bool = False,
    ) -> None:
        """Configure a fast frequency sweep (``SWE:FAST:FREQ:SETUP``).

        In fast mode the step size is derived by the instrument from the
        point count; the point count is limited to 32 000 [R2, Step 5-3].
        A sweep cannot be executed with FM on [R1, Table 2c].
        """
        if self._fm_active:
            raise ParameterError(
                "Sweeps cannot run while FM is enabled [R1, Table 2c]."
            )
        if not (1 <= n_points <= SWEEP_POINTS_MAX):
            raise ParameterError(f"Point count must be 1-{SWEEP_POINTS_MAX}.")
        args = (
            f"{format_frequency(start_hz)},{format_frequency(stop_hz)},"
            f"{n_points},{quantise_power_dbm(power_dbm):.1f}dBm,"
            f"{format_dwell(dwell_us)},"
            f"{run_count},{int(trigger)},{int(direction)}"
        )
        if run_now:
            args += ",RUN"
        command = f"SWE:FAST:FREQ:SETUP {args}"
        _check_compound_length(
            command,
            "Round the start and stop frequencies to fewer significant "
            "digits, or drive the endpoints from list mode instead.",
        )
        self.io.write(command)
        self._emit_state("fast_freq_sweep_setup", args)

    def setup_normal_frequency_sweep(
        self,
        start_hz: float,
        stop_hz: float,
        step_hz: float,
        power_dbm: float,
        dwell_us: int,
        run_count: int,
        trigger: TriggerMode,
        direction: SweepDirection,
        run_now: bool = False,
    ) -> None:
        """Configure a normal frequency sweep (``SWE:NORM:FREQ:SETUP``).

        Normal mode takes an explicit step size and is the mode to use when
        more than 32 000 points are required [R2, Step 5-3].
        """
        if self._fm_active:
            raise ParameterError("Sweeps cannot run while FM is enabled.")
        if step_hz <= 0.0:
            raise ParameterError("Step frequency must be positive.")
        args = (
            f"{format_frequency(start_hz)},{format_frequency(stop_hz)},"
            f"{format_frequency(step_hz)},"
            f"{quantise_power_dbm(power_dbm):.1f}dBm,{format_dwell(dwell_us)},"
            f"{run_count},{int(trigger)},{int(direction)}"
        )
        if run_now:
            args += ",RUN"
        command = f"SWE:NORM:FREQ:SETUP {args}"
        _check_compound_length(
            command,
            "Three frequencies plus the remaining fields are a tight fit in "
            "64 bytes. Round the start, stop and step to fewer significant "
            "digits, or use fast mode, which carries a point count instead "
            "of a step frequency.",
        )
        self.io.write(command)
        self._emit_state("normal_freq_sweep_setup", args)

    def setup_fast_power_sweep(
        self,
        start_dbm: float,
        stop_dbm: float,
        n_points: int,
        freq_hz: float,
        dwell_us: int,
        run_count: int,
        trigger: TriggerMode,
        direction: SweepDirection,
        run_now: bool = False,
    ) -> None:
        """Configure a fast power sweep (``SWE:FAST:POW:SETUP``).

        The fast power sweep is limited to 500 points [R1, Table 2c].
        """
        self.require_power_control()
        if not (1 <= n_points <= POWER_SWEEP_POINTS_MAX):
            raise ParameterError(
                f"Fast power sweep is limited to {POWER_SWEEP_POINTS_MAX} points."
            )
        args = (
            f"{quantise_power_dbm(start_dbm):.1f},"
            f"{quantise_power_dbm(stop_dbm):.1f},{n_points},"
            f"{format_frequency(freq_hz)},{format_dwell(dwell_us)},"
            f"{run_count},{int(trigger)},{int(direction)}"
        )
        if run_now:
            args += ",RUN"
        command = f"SWE:FAST:POW:SETUP {args}"
        _check_compound_length(
            command, "Round the fixed carrier frequency."
        )
        self.io.write(command)
        self._emit_state("fast_power_sweep_setup", args)

    def setup_normal_power_sweep(
        self,
        start_dbm: float,
        stop_dbm: float,
        step_db: float,
        freq_hz: float,
        dwell_us: int,
        run_count: int,
        trigger: TriggerMode,
        direction: SweepDirection,
        run_now: bool = False,
    ) -> None:
        """Configure a normal power sweep (``SWE:NORM:POW:SETUP``)."""
        self.require_power_control()
        if step_db <= 0.0:
            raise ParameterError("Power step must be positive.")
        args = (
            f"{quantise_power_dbm(start_dbm):.1f},"
            f"{quantise_power_dbm(stop_dbm):.1f},"
            f"{quantise_power_dbm(step_db):.1f},"
            f"{format_frequency(freq_hz)},{format_dwell(dwell_us)},"
            f"{run_count},{int(trigger)},{int(direction)}"
        )
        if run_now:
            args += ",RUN"
        command = f"SWE:NORM:POW:SETUP {args}"
        _check_compound_length(
            command, "Round the fixed carrier frequency."
        )
        self.io.write(command)
        self._emit_state("normal_power_sweep_setup", args)

    def start_sweep(self, kind: str, run_count: int) -> None:
        """Start a previously configured sweep.

        Parameters
        ----------
        kind:
            One of ``fast_freq``, ``normal_freq``, ``fast_power``,
            ``normal_power``.
        run_count:
            Number of sweeps, 1 to 32767, or 0 for infinite.
        """
        mnemonic = {
            "fast_freq": "SWE:FAST:FREQ:STAR",
            "normal_freq": "SWE:NORM:FREQ:STAR",
            "fast_power": "SWE:FAST:POW:STAR",
            "normal_power": "SWE:NORM:POW:STAR",
        }[kind]
        self.io.write(f"{mnemonic} {run_count}")
        self._emit_state("sweep_started", {"kind": kind, "runs": run_count})

    def stop_sweep(self) -> None:
        """Halt any running sweep with ``SWE:STOP``."""
        self.io.write("SWE:STOP")
        self._emit_state("sweep_stopped", True)

    # --- Memory hygiene [R5] ------------------------------------------------
    def clear_instrument_states(self) -> None:
        """Clear both user instrument states.

        Implements the vendor procedure: recall the factory default state,
        then overwrite both user slots with it [R5]. There is no command
        that erases these areas directly, so overwriting is the only route.
        """
        self.recall_state(0)
        self.save_state(1)
        self.save_state(2)
        self._emit_state("instrument_states_cleared", True)

    def clear_list_memory(
        self,
        n_points: int,
        safe_freq_hz: float,
        safe_power_dbm: float,
        progress: Callable[[int, int], bool] | None = None,
    ) -> int:
        """Overwrite list-mode non-volatile memory with safe values.

        Parameters
        ----------
        n_points:
            How many of the 32767 possible point locations to overwrite.
        safe_freq_hz, safe_power_dbm:
            The benign values written into every location.
        progress:
            Optional callback ``(done, total) -> keep_going``. Returning
            False aborts the loop.

        Returns
        -------
        int
            Number of points actually written.

        Warnings
        --------
        This writes to flash, so each point costs 300 ms of settling [R1].
        Overwriting all 32767 locations therefore takes about 2.7 hours.
        [R5] is explicit that there is no direct erase for this area.
        """
        written = 0
        for index in range(1, min(n_points, LIST_POINT_MAX) + 1):
            self.write_list_point(
                ListPoint(
                    index=index,
                    freq_hz=safe_freq_hz,
                    power_dbm=safe_power_dbm,
                    dwell_us=1000,
                    pulse_mod=False,
                    rf_output=False,
                    save_to_flash=True,
                )
            )
            written += 1
            if progress is not None and not progress(written, n_points):
                break
        self._emit_state("list_memory_overwritten_points", written)
        return written


# %% ===========================================================================
#    SESSION LOGGER
# =============================================================================
class SessionLogger:
    """Owns the on-disk artefacts for one acquisition session.

    Transaction and state-event rows are appended from whichever thread
    produced them, under a lock. Telemetry rows take a different path: they
    are queued and written by :class:`TelemetryWriter` so that disk latency
    never blocks the sampler.

    Parameters
    ----------
    root:
        Parent directory under which the session folder is created.
    tag:
        Short identifier appended to the folder name, normally the model
        and serial number.
    """

    def __init__(self, root: Path, tag: str = "quicksyn") -> None:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        safe_tag = re.sub(r"[^A-Za-z0-9_.-]+", "_", tag).strip("_") or "quicksyn"
        self.directory = Path(root).expanduser() / f"{stamp}_{safe_tag}"
        self.directory.mkdir(parents=True, exist_ok=True)

        self.path_metadata = self.directory / "session_metadata.json"
        self.path_session_log = self.directory / "session.log"
        self.path_transactions = self.directory / "transactions.csv"
        self.path_state_events = self.directory / "state_events.csv"
        self.path_telemetry = self.directory / "telemetry.csv"

        self._lock = threading.Lock()
        self._txn_count = 0
        self._state_count = 0
        self.t_start_unix = time.time()

        # --- Text log -------------------------------------------------------
        self.logger = logging.getLogger(f"quicksyn.{stamp}")
        self.logger.setLevel(logging.DEBUG)
        self.logger.propagate = False
        handler = logging.FileHandler(self.path_session_log, encoding="utf-8")
        handler.setFormatter(
            logging.Formatter(
                "%(asctime)s.%(msecs)03d  %(levelname)-8s  %(message)s",
                datefmt="%Y-%m-%d %H:%M:%S",
            )
        )
        self.logger.addHandler(handler)

        # --- CSV headers ----------------------------------------------------
        self._txn_file = open(
            self.path_transactions, "w", newline="", encoding="utf-8"
        )
        self._txn_writer = csv.writer(self._txn_file)
        self._txn_writer.writerow(
            [
                "seq",
                "iso_utc",
                "t_unix",
                "direction",
                "command",
                "response",
                "latency_ms",
                "ok",
                "error",
            ]
        )

        self._state_file = open(
            self.path_state_events, "w", newline="", encoding="utf-8"
        )
        self._state_writer = csv.writer(self._state_file)
        self._state_writer.writerow(
            ["seq", "iso_utc", "t_unix", "parameter", "value", "source"]
        )

        self.logger.info(
            "Session opened by %s v%s (%s, binding %s, Python %s)",
            APP_NAME,
            __version__,
            QT_ABSTRACTION,
            QT_BINDING,
            sys.version.split()[0],
        )

    # --- Writers ------------------------------------------------------------
    def log_transaction(self, txn: Transaction) -> None:
        """Append one SCPI exchange to transactions.csv and the text log."""
        with self._lock:
            self._txn_count += 1
            self._txn_writer.writerow(
                [
                    self._txn_count,
                    utc_iso(txn.t_unix),
                    f"{txn.t_unix:.6f}",
                    "QUERY" if txn.is_query else "WRITE",
                    txn.command,
                    "" if txn.response is None else txn.response,
                    f"{txn.latency_s * 1e3:.3f}",
                    int(txn.ok),
                    txn.error,
                ]
            )
            if self._txn_count % 50 == 0:
                self._txn_file.flush()
        if not txn.ok:
            self.logger.warning("TX FAILED %r: %s", txn.command, txn.error)

    def log_state_event(self, parameter: str, value: Any, source: str = "gui") -> None:
        """Append one generated-signal state change to state_events.csv."""
        t_unix = time.time()
        rendered = json.dumps(value) if isinstance(value, (dict, list)) else str(value)
        with self._lock:
            self._state_count += 1
            self._state_writer.writerow(
                [
                    self._state_count,
                    utc_iso(t_unix),
                    f"{t_unix:.6f}",
                    parameter,
                    rendered,
                    source,
                ]
            )
            self._state_file.flush()
        self.logger.info("STATE %s = %s (%s)", parameter, rendered, source)

    def write_metadata(self, payload: dict[str, Any]) -> None:
        """Write or rewrite session_metadata.json."""
        payload = dict(payload)
        payload.setdefault("app_name", APP_NAME)
        payload.setdefault("app_version", __version__)
        payload.setdefault("python_version", sys.version.split()[0])
        payload.setdefault("qt_abstraction", QT_ABSTRACTION)
        payload.setdefault("qt_binding", QT_BINDING)
        payload.setdefault("numpy_version", np.__version__)
        payload.setdefault("session_directory", str(self.directory))
        payload.setdefault("t_start_iso_utc", utc_iso(self.t_start_unix))
        with self._lock:
            self.path_metadata.write_text(
                json.dumps(payload, indent=2, default=str), encoding="utf-8"
            )

    def close(self) -> None:
        """Flush and close every open file handle."""
        with self._lock:
            for handle in (self._txn_file, self._state_file):
                try:
                    handle.flush()
                    handle.close()
                except Exception:  # pragma: no cover
                    pass
        self.logger.info("Session closed.")
        for handler in list(self.logger.handlers):
            handler.close()
            self.logger.removeHandler(handler)


# %% ===========================================================================
#    RING BUFFER AND SPILL
# =============================================================================
class TelemetryRingBuffer:
    """Preallocated NumPy ring buffer with spill-to-disk on overflow.

    Memory is bounded by construction: ``capacity`` records of
    ``TELEMETRY_DTYPE`` (52 bytes each) are allocated once and reused. When
    the buffer fills, the whole block is handed to the spill callback and
    the write index resets, so steady-state RAM use is flat no matter how
    long the campaign runs.

    Parameters
    ----------
    capacity:
        Number of records held in RAM. Clamped up to ``MIN_RING_CAPACITY``
        so that a mistyped value cannot turn every sample into its own
        compressed chunk file; read :attr:`capacity` back for the value in
        force.
    on_spill:
        Callback receiving a copy of the filled block. Typically enqueues a
        gzip-pickle write on the writer thread.
    """

    def __init__(
        self,
        capacity: int = DEFAULT_RING_CAPACITY,
        on_spill: Callable[[np.ndarray], None] | None = None,
    ) -> None:
        self.capacity = int(max(capacity, MIN_RING_CAPACITY))
        self._data = np.zeros(self.capacity, dtype=TELEMETRY_DTYPE)
        self._write_index = 0
        self._total_written = 0
        self._lock = threading.Lock()
        self.on_spill = on_spill

    @property
    def nbytes(self) -> int:
        """Bytes of RAM held by the preallocated block."""
        return int(self._data.nbytes)

    @property
    def total_written(self) -> int:
        """Total records ever appended, including those already spilled."""
        return self._total_written

    @property
    def fill(self) -> int:
        """Records currently resident in RAM."""
        return self._write_index

    def append(self, record: tuple) -> None:
        """Append one record, spilling the block if it becomes full."""
        with self._lock:
            self._data[self._write_index] = record
            self._write_index += 1
            self._total_written += 1
            if self._write_index >= self.capacity:
                block = self._data.copy()
                self._write_index = 0
                if self.on_spill is not None:
                    self.on_spill(block)

    def tail(self, n: int) -> np.ndarray:
        """Return a copy of the most recent ``n`` resident records."""
        with self._lock:
            start = max(0, self._write_index - n)
            return self._data[start : self._write_index].copy()

    def flush(self) -> np.ndarray:
        """Spill and clear whatever is currently resident.

        Returns
        -------
        numpy.ndarray
            A copy of the records that were resident at the time of call.
        """
        with self._lock:
            block = self._data[: self._write_index].copy()
            self._write_index = 0
        if block.size and self.on_spill is not None:
            self.on_spill(block)
        return block


# %% ===========================================================================
#    WRITER THREAD
# =============================================================================
class TelemetryWriter(threading.Thread):
    """Daemon thread that owns all telemetry disk I/O.

    The sampler never touches the filesystem. It pushes work items onto a
    bounded queue and returns immediately; this thread drains the queue,
    appending CSV rows and writing gzip-pickle spill chunks. That keeps a
    stalled or slow disk from distorting the sample interval, which is the
    whole point of decoupling them.

    Work items are tuples ``("row", dict)`` or ``("spill", ndarray)``.
    """

    def __init__(self, session: SessionLogger, csv_flush_every: int = 25) -> None:
        super().__init__(name="telemetry-writer", daemon=True)
        self.session = session
        self.queue: queue.Queue = queue.Queue(maxsize=WRITER_QUEUE_MAXSIZE)
        self._stop_requested = threading.Event()
        self._csv_flush_every = max(1, csv_flush_every)
        self._rows_written = 0
        self._chunks_written = 0
        self.dropped_rows = 0

        self._csv_file = open(
            session.path_telemetry, "w", newline="", encoding="utf-8"
        )
        self._csv_writer = csv.DictWriter(
            self._csv_file, fieldnames=TELEMETRY_CSV_HEADER, extrasaction="ignore"
        )
        self._csv_writer.writeheader()

    # --- Producer-side API --------------------------------------------------
    def submit_row(self, row: dict[str, Any]) -> None:
        """Enqueue one telemetry CSV row; drop it rather than block."""
        try:
            self.queue.put_nowait(("row", row))
        except queue.Full:  # pragma: no cover - only under pathological load
            self.dropped_rows += 1

    def submit_spill(self, block: np.ndarray) -> None:
        """Enqueue a ring-buffer block for gzip-pickle serialisation."""
        try:
            self.queue.put(("spill", block), timeout=2.0)
        except queue.Full:  # pragma: no cover
            self.session.logger.error("Writer queue full; spill block dropped.")

    # --- Thread body --------------------------------------------------------
    def run(self) -> None:
        """Drain the queue until stopped and the queue is empty."""
        while not (self._stop_requested.is_set() and self.queue.empty()):
            try:
                kind, payload = self.queue.get(timeout=0.2)
            except queue.Empty:
                continue
            try:
                if kind == "row":
                    self._csv_writer.writerow(payload)
                    self._rows_written += 1
                    if self._rows_written % self._csv_flush_every == 0:
                        self._csv_file.flush()
                elif kind == "spill":
                    self._write_chunk(payload)
            except Exception as exc:  # pragma: no cover - keep the thread alive
                self.session.logger.exception("Writer error: %s", exc)
            finally:
                self.queue.task_done()
        self._close_csv()

    def _write_chunk(self, block: np.ndarray) -> None:
        """Serialise one ring-buffer block to a gzip-pickle chunk file."""
        path = (
            self.session.directory
            / f"telemetry_chunk_{self._chunks_written:04d}.pkl.gz"
        )
        # Written to .part and renamed, so the export script (which may run
        # while logging continues) never reads a half-written chunk.
        part = path.with_name(path.name + ".part")
        with gzip.open(part, "wb", compresslevel=5) as handle:
            pickle.dump(
                {
                    "dtype": TELEMETRY_DTYPE.descr,
                    "n_records": int(block.size),
                    "written_iso_utc": utc_iso(time.time()),
                    "records": block,
                },
                handle,
                protocol=pickle.HIGHEST_PROTOCOL,
            )
        os.replace(part, path)
        self._chunks_written += 1
        self.session.logger.info(
            "Spilled %d telemetry records to %s", block.size, path.name
        )

    def _close_csv(self) -> None:
        """Flush and close the telemetry CSV."""
        try:
            self._csv_file.flush()
            self._csv_file.close()
        except Exception:  # pragma: no cover
            pass

    def stop(self, timeout: float = 5.0) -> None:
        """Signal shutdown and wait for the queue to drain."""
        self._stop_requested.set()
        self.join(timeout=timeout)

    @property
    def rows_written(self) -> int:
        """Telemetry rows committed to CSV so far."""
        return self._rows_written

    @property
    def chunks_written(self) -> int:
        """Spill chunks written so far."""
        return self._chunks_written


# %% ===========================================================================
#    TELEMETRY SAMPLER THREAD
# =============================================================================
@dataclass(slots=True)
class SamplerConfig:
    """What the sampler polls and how often.

    Trimming the field set is the main lever on achievable rate: each
    enabled field costs one serial round trip, and the temperature query
    costs two when ``TEMPERATURE_DOUBLE_QUERY`` is set.
    """

    rate_hz: float = DEFAULT_SAMPLE_RATE_HZ
    poll_frequency: bool = True
    poll_power: bool = True
    poll_status: bool = True
    poll_modulation: bool = False
    poll_temperature: bool = True
    temperature_decimation: int = 5  # poll temperature every Nth sample

    @property
    def period_s(self) -> float:
        """Nominal sample period in seconds."""
        return 1.0 / max(self.rate_hz, MIN_SAMPLE_RATE_HZ)

    def queries_per_sample(self, include_temperature: bool = True) -> int:
        """Estimated serial round trips per sample, for rate budgeting."""
        count = 0
        count += int(self.poll_frequency)
        count += int(self.poll_power)
        count += int(self.poll_status)
        count += int(self.poll_modulation)
        if include_temperature and self.poll_temperature:
            count += 2 if TEMPERATURE_DOUBLE_QUERY else 1
        return count


class TelemetrySampler(QtCore.QThread):
    """Polls the instrument on a fixed schedule and emits telemetry records.

    Scheduling is absolute rather than incremental: the next deadline is
    computed from the acquisition start time and the sample index, so
    jitter in any one iteration does not accumulate into drift. If a sample
    overruns its slot, the overrun is reported rather than silently
    absorbed.

    Signals
    -------
    sampleReady(object)
        Emitted with the per-sample dictionary after each successful poll.
    samplerError(str)
        Emitted when a poll fails; acquisition continues.
    rateReport(float, float)
        Emitted with (achieved_rate_hz, duty_fraction) once per second.
    """

    sampleReady = QtCore.Signal(object)
    samplerError = QtCore.Signal(str)
    rateReport = QtCore.Signal(float, float)

    def __init__(
        self,
        driver: QuickSyn,
        config: SamplerConfig,
        ring: TelemetryRingBuffer,
        writer: TelemetryWriter,
        parent: QtCore.QObject | None = None,
    ) -> None:
        super().__init__(parent)
        self.driver = driver
        self.config = config
        self.ring = ring
        self.writer = writer
        self._running = False
        self._index = 0
        self._t0_mono = 0.0
        self._last_temp_c = float("nan")

    # --- Control ------------------------------------------------------------
    def stop(self) -> None:
        """Request an orderly stop; the run loop exits at the next check."""
        self._running = False

    # --- Thread body --------------------------------------------------------
    def run(self) -> None:
        """Acquire until stopped, honouring the configured sample period."""
        self._running = True
        self._index = 0
        self._t0_mono = time.perf_counter()
        period = self.config.period_s
        last_report = self._t0_mono
        samples_in_window = 0
        busy_in_window = 0.0

        while self._running:
            deadline = self._t0_mono + (self._index + 1) * period
            t_poll_start = time.perf_counter()
            try:
                record, row = self._poll_once(t_poll_start)
            except Exception as exc:
                self.samplerError.emit(str(exc))
                # Keep the cadence even when a poll fails, so the time base
                # of the log stays meaningful.
                self._index += 1
                self._sleep_until(deadline)
                continue

            busy = time.perf_counter() - t_poll_start
            busy_in_window += busy
            samples_in_window += 1

            self.ring.append(record)
            self.writer.submit_row(row)
            self.sampleReady.emit(row)

            self._index += 1

            now = time.perf_counter()
            if now - last_report >= 1.0:
                elapsed = now - last_report
                self.rateReport.emit(
                    samples_in_window / elapsed,
                    min(busy_in_window / elapsed, 1.0),
                )
                last_report = now
                samples_in_window = 0
                busy_in_window = 0.0

            self._sleep_until(deadline)

    def _sleep_until(self, deadline: float) -> None:
        """Sleep in short slices so a stop request is honoured promptly."""
        while self._running:
            remaining = deadline - time.perf_counter()
            if remaining <= 0.0:
                return
            time.sleep(min(remaining, 0.05))

    def _poll_once(self, t_poll_start: float) -> tuple[tuple, dict[str, Any]]:
        """Execute one poll cycle and build both output representations.

        Returns
        -------
        tuple
            ``(numpy_record_tuple, csv_row_dict)``.
        """
        cfg = self.config
        t_unix = time.time()

        freq_hz = float("nan")
        power_dbm = float("nan")
        status = StatusWord()
        modword = ModulationWord()

        if cfg.poll_frequency:
            freq_hz = self.driver.get_frequency()
        if cfg.poll_power:
            power_dbm = self.driver.get_power()
        if cfg.poll_status:
            status = self.driver.get_status()
        if cfg.poll_modulation:
            modword = self.driver.get_modulation_status()

        # Temperature changes slowly, so it is decimated by default to buy
        # back serial bandwidth for the fast-moving fields.
        if cfg.poll_temperature and (
            cfg.temperature_decimation <= 1
            or self._index % cfg.temperature_decimation == 0
        ):
            self._last_temp_c = self.driver.get_temperature()
        temp_c = self._last_temp_c

        latency = time.perf_counter() - t_poll_start
        t_mono = time.perf_counter() - self._t0_mono
        rate_hz = 1.0 / latency if latency > 0 else 0.0

        record = (
            self._index,
            t_unix,
            t_mono,
            freq_hz,
            power_dbm,
            temp_c,
            status.raw,
            modword.raw,
            latency,
            rate_hz,
        )

        row = {
            "idx": self._index,
            "iso_utc": utc_iso(t_unix),
            "t_unix": f"{t_unix:.6f}",
            "t_mono_s": f"{t_mono:.6f}",
            "freq_hz": "" if math.isnan(freq_hz) else f"{freq_hz:.3f}",
            "power_dbm": "" if math.isnan(power_dbm) else f"{power_dbm:.2f}",
            "temp_c": "" if math.isnan(temp_c) else f"{temp_c:.2f}",
            "status_hex": f"{status.raw:02X}",
            "ext_ref_present": int(status.ext_ref_present),
            "rf_locked": int(status.rf_locked),
            "ref_locked": int(status.ref_locked),
            "rf_output_on": int(status.rf_output_on),
            "voltage_error": int(status.voltage_error),
            "ref_output_on": int(status.ref_output_on),
            "blanking_on": int(status.blanking_on),
            "lock_recovery_on": int(status.lock_recovery_on),
            "mod_hex": f"{modword.raw:02X}",
            "pulse_on": int(modword.pulse),
            "am_on": int(modword.am),
            "fm_nb1_on": int(modword.fm_nb1),
            "fm_nb2_on": int(modword.fm_nb2),
            "fm_wb_on": int(modword.fm_wide),
            "phase_on": int(modword.phase),
            "latency_s": f"{latency:.6f}",
            "rate_hz": f"{rate_hz:.3f}",
        }
        return record, row


# %% ===========================================================================
#    CALIBRATION (PROGRAM-SIDE)
# =============================================================================
# What can and cannot be written to the synthesizer (0.0.10)
# ----------------------------------------------------------
# [R1] documents one calibration write: DIAG:CAL:REF:DAC, the 16-bit tuning
# word of the internal OCXO (Table 5). Neither [R1] nor the calibration
# manual [R3] documents how NI's calibration soft front panel writes power
# calibration tables ("Write Cal to UUT") or stores calibration in flash
# ("Store in Flash", "Write Ref Cal to UUT"). Guessing those commands could
# overwrite the factory calibration, so this program sends none of them.
#
# Instead:
# * Power calibration is a measured table of the level at RF OUT against
#   frequency (and against the commanded level on models with power
#   control), kept in this program per unit (model + serial). It is used to
#   show the level expected at RF OUT and, on power-control models, to
#   correct the commanded level. The synthesizer itself is not changed.
# * Reference calibration tunes the OCXO with the documented DIAG:CAL:REF:DAC
#   against a frequency counter and keeps the result per unit; it can be
#   re-applied on every connect. Whether a DIAG:CAL:REF:DAC value survives a
#   power cycle is not documented ([R3] Step 4-2 says the value written while
#   tuning is volatile until NI's panel stores it).
#
# Readings are typed in, or fetched from any SCPI power meter or counter
# through PyVISA (optional; GPIB, USB or LAN), with an optional path-loss
# correction from a constant, a CSV table or a Touchstone .s2p file.

#: Where calibration files live (override with the QUICKSYN_CAL_DIR variable).
CAL_DIR_DEFAULT: Path = Path.home() / "quicksyn_cal"
POWER_CAL_SCHEMA: int = 1
REF_CAL_SCHEMA: int = 1
#: [R3] Step 4-2: NI's panel tunes the OCXO until RF OUT is within +/-20 Hz
#: at 10 GHz; the same target and tolerance are the defaults here.
DEFAULT_REF_CAL_FREQ_HZ: float = 10e9
DEFAULT_REF_CAL_TOL_HZ: float = 20.0
#: First probe step for the DAC slope (counts). An assumption, not a vendor
#: figure: the slope is measured from the first two points, so this only
#: needs to move the frequency measurably.
DEFAULT_REF_TRIAL_STEP: int = 500
#: Largest DAC change one secant step may make (guards against a noisy slope).
REF_MAX_STEP_COUNTS: int = 8000
#: Datasheet minimum output for fixed-output models [R4] (plotted as the
#: specification line); power-control models are plotted against the level.
SPEC_MIN_POWER_DBM: dict[str, float] = {
    "FSL-0010": 15.0, "FSL-0020": 10.0, "FSL-E020": 10.0,
}
#: Unit prefixes accepted in path-loss and Touchstone files.
_FREQ_UNITS: dict[str, float] = {"HZ": 1.0, "KHZ": 1e3, "MHZ": 1e6, "GHZ": 1e9}


class CalibrationError(QuickSynError):
    """A calibration input, plan or file could not be used."""


def cal_dir() -> Path:
    """Calibration root: QUICKSYN_CAL_DIR if set, else ~/quicksyn_cal."""
    override = os.environ.get("QUICKSYN_CAL_DIR", "").strip()
    return Path(override).expanduser() if override else CAL_DIR_DEFAULT


def interp_or_none(x: float, xs: Sequence[float], ys: Sequence[float]) -> float | None:
    """Linear interpolation inside [xs[0], xs[-1]]; None outside (no extrapolation).

    ``xs`` must be increasing. A single point is returned only at its own x.
    """
    if len(xs) == 0:
        return None
    eps = 1e-9 * max(1.0, abs(xs[0]), abs(xs[-1]))
    if x < xs[0] - eps or x > xs[-1] + eps:
        return None
    if len(xs) == 1:
        return float(ys[0])
    return float(np.interp(x, xs, ys))


@dataclass
class PathLoss:
    """Loss between RF OUT and the meter, in dB (positive = loss).

    The level at RF OUT is the meter reading plus this loss. ``kind`` is
    "none", "constant" or "table" (from a CSV or Touchstone file).
    """

    kind: str = "none"
    constant_db: float = 0.0
    freqs_hz: list[float] = field(default_factory=list)
    loss_db: list[float] = field(default_factory=list)
    source: str = ""

    def loss_at(self, freq_hz: float) -> float:
        """Loss at ``freq_hz``; raises CalibrationError outside the table."""
        if self.kind == "none":
            return 0.0
        if self.kind == "constant":
            return float(self.constant_db)
        value = interp_or_none(freq_hz, self.freqs_hz, self.loss_db)
        if value is None:
            raise CalibrationError(
                f"{freq_hz / 1e9:.6g} GHz is outside the path-loss data "
                f"({self.freqs_hz[0] / 1e9:.6g} to {self.freqs_hz[-1] / 1e9:.6g} GHz, {self.source}).")
        return value

    def describe(self) -> str:
        """One line for the GUI and the saved table."""
        if self.kind == "none":
            return "no path correction"
        if self.kind == "constant":
            return f"constant {self.constant_db:.2f} dB"
        return (f"{self.source}: {len(self.freqs_hz)} points, {self.freqs_hz[0] / 1e9:.6g}-"
                f"{self.freqs_hz[-1] / 1e9:.6g} GHz, {min(self.loss_db):.2f} to "
                f"{max(self.loss_db):.2f} dB loss")

    def to_dict(self) -> dict[str, Any]:
        """JSON-ready form (stored with each power calibration)."""
        return asdict(self)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "PathLoss":
        """Inverse of :meth:`to_dict`."""
        return cls(**{k: data[k] for k in ("kind", "constant_db", "freqs_hz", "loss_db", "source")
                      if k in data})

    @classmethod
    def _table(cls, freqs: list[float], loss: list[float], source: str) -> "PathLoss":
        """Sorted, de-duplicated table (duplicate frequencies averaged)."""
        if len(freqs) < 1:
            raise CalibrationError(f"{source}: no data rows found.")
        merged: dict[float, list[float]] = {}
        for f, value in zip(freqs, loss):
            if not (math.isfinite(f) and math.isfinite(value)) or f <= 0:
                raise CalibrationError(f"{source}: invalid row ({f}, {value}).")
            merged.setdefault(f, []).append(value)
        keys = sorted(merged)
        return cls(kind="table", freqs_hz=keys,
                   loss_db=[float(np.mean(merged[k])) for k in keys], source=source)

    @classmethod
    def from_csv(cls, path: str | os.PathLike) -> "PathLoss":
        """Two columns: frequency and loss in dB.

        Separators: comma, semicolon, tab or spaces; "#" and "!" start comments.
        The frequency unit comes from the header (Hz, kHz, MHz or GHz); with no
        header unit, values below 1e3 are taken as GHz, below 1e6 as MHz,
        otherwise Hz. If every loss value is zero or negative, the column is
        taken as S21 in dB and negated; that choice is shown in the source text.
        """
        p = Path(path)
        scale: float | None = None
        freqs: list[float] = []
        values: list[float] = []
        for raw in p.read_text(encoding="utf-8", errors="replace").splitlines():
            line = raw.split("#")[0].split("!")[0].strip()
            if not line:
                continue
            cells = [c for c in re.split(r"[,;\t ]+", line) if c]
            if len(cells) < 2:
                continue
            try:
                f, v = float(cells[0]), float(cells[1])
            except ValueError:                      # a header row
                head = line.upper()
                for unit in ("GHZ", "MHZ", "KHZ", "HZ"):
                    # "freq_GHz", "f (MHz)", "Frequency [Hz]": the unit, not
                    # part of a longer word ("HZ" inside "GHZ" is not Hz).
                    if re.search(rf"(?<![A-Z]){unit}(?![A-Z])", head):
                        scale = _FREQ_UNITS[unit]
                        break
                continue
            freqs.append(f)
            values.append(v)
        if not freqs:
            raise CalibrationError(f"{p.name}: no numeric rows.")
        note = ""
        if scale is None:
            top = max(freqs)
            scale, note = ((1e9, "GHz assumed") if top < 1e3 else
                           (1e6, "MHz assumed") if top < 1e6 else (1.0, "Hz assumed"))
        if all(v <= 0 for v in values) and any(v < 0 for v in values):
            values = [-v for v in values]
            note = (note + ", " if note else "") + "S21 in dB, negated"
        table = cls._table([f * scale for f in freqs], values, p.name)
        if note:
            table.source = f"{p.name} ({note})"
        return table

    @classmethod
    def from_touchstone(cls, path: str | os.PathLike) -> "PathLoss":
        """|S21| of a 2-port Touchstone file (v1.x or v2.0) as loss in dB.

        Option line "# <unit> S <MA|DB|RI> R <z>" (defaults GHz, MA, as in the
        Touchstone specification); 2-port order N11 N21 N12 N22 (v1, and v2
        with [Two-Port Data Order] 21_12) or N11 N12 N21 N22 (v2 12_21).
        Noise parameters after the network data are ignored.
        """
        p = Path(path)
        scale, fmt, param, order_21_12, ports = 1e9, "MA", "S", True, 2
        tokens: list[float] = []
        for raw in p.read_text(encoding="utf-8", errors="replace").splitlines():
            line = raw.split("!")[0].strip()
            if not line:
                continue
            if line.startswith("#"):
                words = line[1:].upper().split()
                for i, word in enumerate(words):
                    if word in _FREQ_UNITS:
                        scale = _FREQ_UNITS[word]
                    elif word in ("MA", "DB", "RI"):
                        fmt = word
                    elif word in ("S", "Y", "Z", "H", "G") and (i == 0 or words[i - 1] != "R"):
                        param = word
                continue
            if line.startswith("["):
                keyword = line.upper()
                if keyword.startswith("[NUMBER OF PORTS]"):
                    ports = int(keyword.split("]")[1].split()[0])
                elif keyword.startswith("[TWO-PORT DATA ORDER]"):
                    order_21_12 = "21_12" in keyword
                elif keyword.startswith(("[NOISE DATA]", "[END]")):
                    break                               # v2: network data done
                continue
            try:
                tokens.extend(float(t) for t in line.split())
            except ValueError as exc:
                raise CalibrationError(f"{p.name}: unreadable data line {raw!r}") from exc
        if param != "S":
            raise CalibrationError(f"{p.name}: {param}-parameters; S-parameters are needed.")
        suffix = p.suffix.lower()
        if ports != 2 or (re.fullmatch(r"\.s\d+p", suffix) and suffix != ".s2p"):
            raise CalibrationError(f"{p.name}: a 2-port file (.s2p) is needed for S21.")
        freqs: list[float] = []
        loss: list[float] = []
        index = 0
        while index + 9 <= len(tokens):
            row = tokens[index:index + 9]
            if freqs and row[0] * scale <= freqs[-1]:
                break                                   # noise data begins
            a, b = (row[3], row[4]) if order_21_12 else (row[5], row[6])
            if fmt == "DB":
                mag_db = a
            else:
                mag = abs(a) if fmt == "MA" else math.hypot(a, b)
                if mag <= 0:
                    raise CalibrationError(f"{p.name}: |S21| = 0 at {row[0]} - no transmission.")
                mag_db = 20.0 * math.log10(mag)
            freqs.append(row[0] * scale)
            loss.append(-mag_db)
            index += 9
        return cls._table(freqs, loss, f"{p.name} (|S21|)")


@dataclass
class PowerCalPoint:
    """One measured point: what was commanded and what the meter showed."""

    freq_hz: float
    set_dbm: float | None          # None on fixed-output models
    reading_dbm: float
    path_loss_db: float = 0.0
    t_unix: float = 0.0
    source: str = "manual"         # "manual" or the meter that was read

    @property
    def output_dbm(self) -> float:
        """Level at RF OUT: meter reading plus path loss."""
        return self.reading_dbm + self.path_loss_db

    @property
    def error_db(self) -> float | None:
        """Level at RF OUT minus the commanded level (None if none commanded)."""
        return None if self.set_dbm is None else self.output_dbm - self.set_dbm


@dataclass
class PowerCalTable:
    """A unit's measured output level against frequency (and level).

    Interpolated linearly in frequency (dB) and, where several commanded
    levels were measured, linearly in level; never extrapolated in frequency.
    """

    model: str = ""
    serial: str = ""
    firmware: str = ""
    created_iso: str = ""
    operator: str = ""
    meter: str = ""
    sensor: str = ""
    path: dict[str, Any] = field(default_factory=dict)
    notes: str = ""
    points: list[PowerCalPoint] = field(default_factory=list)
    schema: int = POWER_CAL_SCHEMA

    def add(self, point: PowerCalPoint) -> None:
        """Append a point."""
        self.points.append(point)

    def levels(self) -> list[float | None]:
        """Commanded levels present (``[None]`` for a fixed-output table)."""
        found = {p.set_dbm for p in self.points}
        if found == {None}:
            return [None]
        return sorted(v for v in found if v is not None)

    def curve(self, level: float | None) -> tuple[list[float], list[float]]:
        """(frequencies, levels at RF OUT) for one commanded level, sorted;
        repeated frequencies are averaged in dB."""
        merged: dict[float, list[float]] = {}
        for p in self.points:
            same = (p.set_dbm is None and level is None) or (
                p.set_dbm is not None and level is not None and abs(p.set_dbm - level) < 1e-6)
            if same:
                merged.setdefault(p.freq_hz, []).append(p.output_dbm)
        keys = sorted(merged)
        return keys, [float(np.mean(merged[k])) for k in keys]

    def frequency_span(self) -> tuple[float, float] | None:
        """(lowest, highest) calibrated frequency, or None if empty."""
        if not self.points:
            return None
        freqs = [p.freq_hz for p in self.points]
        return min(freqs), max(freqs)

    def expected_output(self, freq_hz: float, set_dbm: float | None = None) -> float | None:
        """Level expected at RF OUT, or None outside the calibrated band."""
        levels = self.levels()
        if not self.points:
            return None
        if levels == [None]:
            f, out = self.curve(None)
            return interp_or_none(freq_hz, f, out)
        target = levels[0] if set_dbm is None else set_dbm
        error = self._error_at(freq_hz, target)
        return None if error is None else target + error

    def _error_at(self, freq_hz: float, set_dbm: float) -> float | None:
        """(RF OUT - commanded) at ``freq_hz``, interpolated across levels
        (held constant beyond the lowest and highest level measured)."""
        lv: list[float] = []
        err: list[float] = []
        for level in self.levels():
            if level is None:
                continue
            f, out = self.curve(level)
            value = interp_or_none(freq_hz, f, out)
            if value is not None:
                lv.append(level)
                err.append(value - level)
        if not lv:
            return None
        return float(np.interp(set_dbm, lv, err))

    def command_for_target(self, freq_hz: float, target_dbm: float,
                           p_min: float, p_max: float) -> float | None:
        """Level to command so that ``target_dbm`` appears at RF OUT.

        Solves set + error(f, set) = target by fixed-point iteration (the error
        varies slowly with level) and clamps to [p_min, p_max]. None when the
        table cannot answer (fixed-output table, or outside the band).
        """
        if self.levels() == [None]:
            return None
        command = target_dbm
        for _ in range(12):
            error = self._error_at(freq_hz, command)
            if error is None:
                return None
            new = min(max(target_dbm - error, p_min), p_max)
            if abs(new - command) < 0.005:
                command = new
                break
            command = new
        return quantise_power_dbm(command)

    # --- files ----------------------------------------------------------------
    def to_dict(self) -> dict[str, Any]:
        """JSON-ready form."""
        data = asdict(self)
        data["kind"] = "quicksyn_power_cal"
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "PowerCalTable":
        """Inverse of :meth:`to_dict`; refuses other file kinds and newer schemas."""
        if data.get("kind") != "quicksyn_power_cal":
            raise CalibrationError("Not a QuickSyn power calibration file.")
        if int(data.get("schema", 0)) > POWER_CAL_SCHEMA:
            raise CalibrationError(f"Power calibration schema {data.get('schema')} is newer than "
                                   f"this program ({POWER_CAL_SCHEMA}).")
        fields_ = {k: data[k] for k in ("model", "serial", "firmware", "created_iso", "operator",
                                        "meter", "sensor", "path", "notes", "schema") if k in data}
        table = cls(**fields_)
        table.points = [PowerCalPoint(**p) for p in data.get("points", [])]
        return table

    def save(self, path: str | os.PathLike) -> Path:
        """Write JSON atomically; returns the path."""
        target = Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        part = target.with_name(target.name + ".part")
        part.write_text(json.dumps(self.to_dict(), indent=2), encoding="utf-8")
        os.replace(part, target)
        return target

    @classmethod
    def load(cls, path: str | os.PathLike) -> "PowerCalTable":
        """Read a file written by :meth:`save`."""
        try:
            data = json.loads(Path(path).read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise CalibrationError(f"Cannot read {path}: {exc}") from exc
        return cls.from_dict(data)

    def to_csv(self, path: str | os.PathLike) -> Path:
        """One row per point, for spreadsheets."""
        target = Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open("w", newline="", encoding="utf-8") as fh:
            out = csv.writer(fh)
            out.writerow(["freq_hz", "freq_ghz", "set_dbm", "reading_dbm", "path_loss_db",
                          "rf_out_dbm", "error_db", "iso_utc", "source"])
            for p in sorted(self.points, key=lambda q: (q.set_dbm or 0.0, q.freq_hz)):
                out.writerow([f"{p.freq_hz:.3f}", f"{p.freq_hz / 1e9:.9f}",
                              "" if p.set_dbm is None else f"{p.set_dbm:.2f}",
                              f"{p.reading_dbm:.3f}", f"{p.path_loss_db:.3f}",
                              f"{p.output_dbm:.3f}",
                              "" if p.error_db is None else f"{p.error_db:.3f}",
                              utc_iso(p.t_unix) if p.t_unix else "", p.source])
        return target


@dataclass
class RefCalIteration:
    """One step of the OCXO tuning: DAC written, frequency measured."""

    dac: int
    measured_hz: float
    target_hz: float
    t_unix: float = 0.0
    source: str = "manual"

    @property
    def error_hz(self) -> float:
        """Measured minus target, in Hz."""
        return self.measured_hz - self.target_hz

    @property
    def error_ppb(self) -> float:
        """Fractional error in parts per 10^9."""
        return 1e9 * self.error_hz / self.target_hz


class RefCalTuner:
    """Secant search for the DAC word that puts RF OUT on frequency.

    f(DAC) is taken as locally linear: after the first measurement the DAC
    is moved by ``trial_step`` to measure the slope, then each step uses the
    two most recent distinct DAC values. Steps are limited to
    REF_MAX_STEP_COUNTS and the DAC range.
    """

    def __init__(self, target_hz: float, tolerance_hz: float, trial_step: int,
                 original_dac: int) -> None:
        if target_hz <= 0 or tolerance_hz <= 0 or trial_step == 0:
            raise CalibrationError("Target, tolerance and trial step must be non-zero and positive.")
        self.target_hz = float(target_hz)
        self.tolerance_hz = float(tolerance_hz)
        self.trial_step = int(trial_step)
        self.original_dac = int(original_dac)
        self.iterations: list[RefCalIteration] = []

    def record(self, dac: int, measured_hz: float, source: str = "manual") -> RefCalIteration:
        """Add a measurement taken with ``dac`` written."""
        if not (measured_hz > 0 and math.isfinite(measured_hz)):
            raise CalibrationError(f"Measured frequency {measured_hz!r} is not usable.")
        it = RefCalIteration(int(dac), float(measured_hz), self.target_hz, time.time(), source)
        self.iterations.append(it)
        return it

    def converged(self) -> bool:
        """True when the latest measurement is within tolerance."""
        return bool(self.iterations) and abs(self.iterations[-1].error_hz) <= self.tolerance_hz

    def slope_hz_per_count(self) -> float | None:
        """df/dDAC from the two most recent distinct DAC values."""
        latest = self.iterations[-1] if self.iterations else None
        if latest is None:
            return None
        for older in reversed(self.iterations[:-1]):
            if older.dac != latest.dac:
                slope = (latest.measured_hz - older.measured_hz) / (latest.dac - older.dac)
                return slope if slope != 0 and math.isfinite(slope) else None
        return None

    def next_dac(self) -> int:
        """DAC word to try next (the current one if already converged)."""
        if not self.iterations:
            return self.original_dac
        last = self.iterations[-1]
        if self.converged():
            return last.dac
        slope = self.slope_hz_per_count()
        if slope is None:
            step = self.trial_step
        else:
            step = -last.error_hz / slope
            step = max(-REF_MAX_STEP_COUNTS, min(REF_MAX_STEP_COUNTS, step))
            if abs(step) < 1.0:
                step = math.copysign(1.0, step)
        return int(min(REF_DAC_MAX, max(REF_DAC_MIN, round(last.dac + step))))

    def best(self) -> RefCalIteration | None:
        """The iteration with the smallest |error|."""
        return min(self.iterations, key=lambda it: abs(it.error_hz)) if self.iterations else None


@dataclass
class RefCalRecord:
    """A unit's saved reference calibration (re-applied on connect if asked)."""

    model: str = ""
    serial: str = ""
    dac: int = 0
    original_dac: int = 0
    target_hz: float = DEFAULT_REF_CAL_FREQ_HZ
    measured_hz: float = 0.0
    created_iso: str = ""
    apply_on_connect: bool = False
    notes: str = ""
    schema: int = REF_CAL_SCHEMA

    @property
    def error_hz(self) -> float:
        """Residual error when it was saved."""
        return self.measured_hz - self.target_hz


class CalStore:
    """Per-unit calibration files under cal_dir()/<model>_<serial>/.

    Nothing is created until something is saved.
    """

    def __init__(self, root: Path | None = None) -> None:
        self.root = Path(root) if root is not None else cal_dir()

    @staticmethod
    def _safe(text: str) -> str:
        return re.sub(r"[^A-Za-z0-9._-]+", "_", text.strip()) or "unknown"

    def unit_dir(self, model: str, serial: str) -> Path:
        """Folder for one unit."""
        return self.root / f"{self._safe(model)}_{self._safe(serial)}"

    def save_power(self, table: PowerCalTable) -> tuple[Path, Path]:
        """Save a dated copy (JSON + CSV) and make it the unit's active table."""
        folder = self.unit_dir(table.model, table.serial)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        dated = table.save(folder / f"power_cal_{stamp}.json")
        table.to_csv(folder / f"power_cal_{stamp}.csv")
        table.save(folder / "active_power_cal.json")
        return dated, folder / "active_power_cal.json"

    def load_active_power(self, model: str, serial: str) -> PowerCalTable | None:
        """The unit's active power table, or None."""
        path = self.unit_dir(model, serial) / "active_power_cal.json"
        return PowerCalTable.load(path) if path.exists() else None

    def save_ref(self, record: RefCalRecord) -> Path:
        """Write ref_cal.json and append to ref_cal_history.csv."""
        folder = self.unit_dir(record.model, record.serial)
        folder.mkdir(parents=True, exist_ok=True)
        path = folder / "ref_cal.json"
        part = path.with_name(path.name + ".part")
        part.write_text(json.dumps(asdict(record), indent=2), encoding="utf-8")
        os.replace(part, path)
        history = folder / "ref_cal_history.csv"
        new = not history.exists()
        with history.open("a", newline="", encoding="utf-8") as fh:
            out = csv.writer(fh)
            if new:
                out.writerow(["created_iso", "dac", "original_dac", "target_hz", "measured_hz",
                              "error_hz", "apply_on_connect", "notes"])
            out.writerow([record.created_iso, record.dac, record.original_dac,
                          f"{record.target_hz:.3f}", f"{record.measured_hz:.3f}",
                          f"{record.error_hz:.3f}", record.apply_on_connect, record.notes])
        return path

    def load_ref(self, model: str, serial: str) -> RefCalRecord | None:
        """The unit's saved reference calibration, or None."""
        path = self.unit_dir(model, serial) / "ref_cal.json"
        if not path.exists():
            return None
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise CalibrationError(f"Cannot read {path}: {exc}") from exc
        if int(data.get("schema", 0)) > REF_CAL_SCHEMA:
            raise CalibrationError(f"{path.name}: schema {data.get('schema')} is newer than this program.")
        return RefCalRecord(**{k: v for k, v in data.items() if k in RefCalRecord.__dataclass_fields__})


@dataclass
class MeterConfig:
    """How to read one external instrument through PyVISA.

    ``query`` must return one number (dBm for a power meter, Hz for a
    counter). ``pre_command`` is written before each read; "{freq_hz}" and
    "{freq_ghz}" are replaced, so a power meter can be told the frequency
    for its sensor's calibration factor. The defaults follow common SCPI
    usage and must be checked against the instrument's own manual.
    """

    resource: str = ""
    backend: str = ""              # "" = the default VISA library, "@py" = pyvisa-py
    query: str = "MEAS?"
    pre_command: str = ""
    timeout_ms: int = 10_000
    termination: str = "\n"


class InstrumentReader:
    """Optional PyVISA link to a power meter or frequency counter.

    PyVISA is imported only when a reader is opened, so the rest of the
    program never depends on it. ``rm_factory`` lets tests supply a fake
    resource manager.
    """

    def __init__(self, config: MeterConfig,
                 rm_factory: Callable[[str], Any] | None = None) -> None:
        self.config = config
        self._rm_factory = rm_factory
        self._rm: Any = None
        self._inst: Any = None
        self.idn: str = ""

    @staticmethod
    def available() -> bool:
        """True when PyVISA can be imported."""
        import importlib.util
        return importlib.util.find_spec("pyvisa") is not None

    def _manager(self) -> Any:
        if self._rm_factory is not None:
            return self._rm_factory(self.config.backend)
        try:
            import pyvisa  # noqa: PLC0415 (optional dependency, imported on use)
        except ImportError as exc:
            raise CalibrationError(
                "PyVISA is not installed: mamba install -c conda-forge pyvisa pyvisa-py") from exc
        return pyvisa.ResourceManager(self.config.backend) if self.config.backend else \
            pyvisa.ResourceManager()

    def list_resources(self) -> list[str]:
        """VISA resources visible to the chosen back end."""
        return list(self._manager().list_resources())

    def open(self) -> str:
        """Open the resource and return its *IDN? reply."""
        if not self.config.resource.strip():
            raise CalibrationError("No VISA resource given (for example GPIB0::13::INSTR).")
        self.close()
        try:
            self._rm = self._manager()
            inst = self._rm.open_resource(self.config.resource.strip())
            inst.timeout = int(self.config.timeout_ms)
            if self.config.termination:
                inst.read_termination = self.config.termination
                inst.write_termination = self.config.termination
            self._inst = inst
            self.idn = str(inst.query("*IDN?")).strip()
        except CalibrationError:
            raise
        except Exception as exc:                       # VISA errors vary by back end
            self.close()
            raise CalibrationError(f"{self.config.resource}: {exc}") from exc
        return self.idn

    def close(self) -> None:
        """Close the resource (safe to call twice)."""
        for obj in (self._inst, self._rm):
            try:
                if obj is not None:
                    obj.close()
            except Exception:  # pragma: no cover - best effort
                pass
        self._inst = None
        self._rm = None

    @property
    def is_open(self) -> bool:
        """True while a resource is open."""
        return self._inst is not None

    def read(self, freq_hz: float | None = None) -> float:
        """Send the pre-command (if any) and return the number the query gives."""
        if self._inst is None:
            self.open()
        try:
            if self.config.pre_command.strip():
                f = 0.0 if freq_hz is None else float(freq_hz)
                self._inst.write(self.config.pre_command.format(freq_hz=f, freq_ghz=f / 1e9))
            reply = str(self._inst.query(self.config.query)).strip()
        except Exception as exc:
            raise CalibrationError(f"{self.config.resource}: {exc}") from exc
        try:
            return parse_float_response(reply)
        except ValueError as exc:
            raise CalibrationError(f"{self.config.resource} replied {reply!r}, not a number.") from exc


# %% ===========================================================================
#    THEMING
# =============================================================================
class ThemeManager:
    """Applies light, dark or system palettes to the whole application.

    Qt 6 exposes a colour-scheme hint, but it is honoured inconsistently
    across platforms, so explicit palettes are supplied for the two forced
    modes and the platform default is restored for "system".
    """

    LIGHT = "light"
    DARK = "dark"
    SYSTEM = "system"

    def __init__(self, app: QtWidgets.QApplication) -> None:
        self.app = app
        self._default_palette = QtGui.QPalette(app.palette())
        self._default_style = app.style().objectName() if app.style() else "fusion"
        self.current = self.SYSTEM

    @staticmethod
    def _dark_palette() -> QtGui.QPalette:
        """Build a neutral dark palette suitable for long lab sessions."""
        role = QtGui.QPalette.ColorRole
        group = QtGui.QPalette.ColorGroup
        palette = QtGui.QPalette()
        base = QtGui.QColor(32, 33, 36)
        alt = QtGui.QColor(42, 43, 47)
        text = QtGui.QColor(226, 228, 231)
        accent = QtGui.QColor(72, 140, 214)

        palette.setColor(role.Window, base)
        palette.setColor(role.WindowText, text)
        palette.setColor(role.Base, QtGui.QColor(24, 25, 28))
        palette.setColor(role.AlternateBase, alt)
        palette.setColor(role.ToolTipBase, alt)
        palette.setColor(role.ToolTipText, text)
        palette.setColor(role.Text, text)
        palette.setColor(role.Button, alt)
        palette.setColor(role.ButtonText, text)
        palette.setColor(role.BrightText, QtGui.QColor(255, 96, 96))
        palette.setColor(role.Link, accent)
        palette.setColor(role.Highlight, accent)
        palette.setColor(role.HighlightedText, QtGui.QColor(18, 18, 20))
        palette.setColor(
            group.Disabled, role.Text, QtGui.QColor(128, 130, 134)
        )
        palette.setColor(
            group.Disabled, role.ButtonText, QtGui.QColor(128, 130, 134)
        )
        palette.setColor(
            group.Disabled, role.WindowText, QtGui.QColor(128, 130, 134)
        )
        return palette

    @staticmethod
    def _light_palette() -> QtGui.QPalette:
        """Build a neutral light palette."""
        role = QtGui.QPalette.ColorRole
        palette = QtGui.QPalette()
        palette.setColor(role.Window, QtGui.QColor(246, 246, 248))
        palette.setColor(role.WindowText, QtGui.QColor(24, 25, 28))
        palette.setColor(role.Base, QtGui.QColor(255, 255, 255))
        palette.setColor(role.AlternateBase, QtGui.QColor(238, 239, 242))
        palette.setColor(role.ToolTipBase, QtGui.QColor(255, 255, 220))
        palette.setColor(role.ToolTipText, QtGui.QColor(24, 25, 28))
        palette.setColor(role.Text, QtGui.QColor(24, 25, 28))
        palette.setColor(role.Button, QtGui.QColor(240, 241, 244))
        palette.setColor(role.ButtonText, QtGui.QColor(24, 25, 28))
        palette.setColor(role.BrightText, QtGui.QColor(190, 30, 30))
        palette.setColor(role.Highlight, QtGui.QColor(50, 118, 198))
        palette.setColor(role.HighlightedText, QtGui.QColor(255, 255, 255))
        return palette

    def apply(self, mode: str) -> None:
        """Apply one of ``light``, ``dark`` or ``system``."""
        self.current = mode
        if mode == self.DARK:
            self.app.setStyle("Fusion")
            self.app.setPalette(self._dark_palette())
            if HAVE_PYQTGRAPH:
                pg.setConfigOption("background", (24, 25, 28))
                pg.setConfigOption("foreground", (226, 228, 231))
        elif mode == self.LIGHT:
            self.app.setStyle("Fusion")
            self.app.setPalette(self._light_palette())
            if HAVE_PYQTGRAPH:
                pg.setConfigOption("background", "w")
                pg.setConfigOption("foreground", "k")
        else:
            self.app.setStyle(self._default_style)
            self.app.setPalette(self._default_palette)
            if HAVE_PYQTGRAPH:
                pg.setConfigOption("background", None)
                pg.setConfigOption("foreground", "d")


# %% ===========================================================================
#    SMALL REUSABLE WIDGETS
# =============================================================================
class LEDIndicator(QtWidgets.QLabel):
    """A compact coloured status dot with a text caption."""

    def __init__(self, caption: str, parent: QtWidgets.QWidget | None = None) -> None:
        super().__init__(parent)
        self._caption = caption
        self.setMinimumWidth(130)
        self.set_state(None)

    def set_state(self, good: bool | None, text: str | None = None) -> None:
        """Set the indicator.

        Parameters
        ----------
        good:
            True for green, False for red, None for grey/unknown.
        text:
            Optional caption override.
        """
        colour = {True: "#2faf4a", False: "#d14545", None: "#8a8d93"}[good]
        label = text if text is not None else self._caption
        self.setText(
            f'<span style="color:{colour}; font-size:15px;">&#9679;</span> {label}'
        )


class EnterApplies(QtCore.QObject):
    """Call ``action`` when Enter or Return is pressed in ``widget``.

    Installed as an event filter, so the spin box still handles the key
    itself (committing the typed text); the action runs after that.
    """

    def __init__(self, widget: QtWidgets.QAbstractSpinBox, action: Callable[[], Any]) -> None:
        super().__init__(widget)
        self._widget = widget
        self._action = action
        widget.installEventFilter(self)

    def eventFilter(self, obj: QtCore.QObject, event: QtCore.QEvent) -> bool:  # noqa: N802 (Qt API)
        if (obj is self._widget and event.type() == QtCore.QEvent.Type.KeyPress
                and event.key() in (QtCore.Qt.Key.Key_Return, QtCore.Qt.Key.Key_Enter)):
            self._widget.interpretText()      # commit what was typed
            QtCore.QTimer.singleShot(0, self._action)
        return False


def labelled_row(*widgets: QtWidgets.QWidget) -> QtWidgets.QWidget:
    """Pack widgets into a margin-free horizontal row."""
    container = QtWidgets.QWidget()
    layout = QtWidgets.QHBoxLayout(container)
    layout.setContentsMargins(0, 0, 0, 0)
    for widget in widgets:
        layout.addWidget(widget)
    layout.addStretch(1)
    return container


class EntrySpinBox(QtWidgets.QDoubleSpinBox):
    """A QDoubleSpinBox that lets any number be typed, then range-checks it.

    The stock box refuses a keystroke that would exceed its decimals. With
    nine decimals shown ("1.000000000 GHz") every digit typed after the point
    is refused, so 0.8 GHz could not be typed by editing the text, and text
    the box judged incomplete was reverted when focus moved, after which the
    Set button sent the OLD value (first hardware session, 0.0.8).

    Here any partial or complete number may be typed (extra decimals are
    rounded on commit), a unit suffix that is whole, partly deleted or absent
    is tolerated, and a typed value that cannot be accepted (not a number, or
    outside the range) is announced with :attr:`entryRejected` and kept for
    :meth:`take_rejected_text`, so the caller can refuse to act instead of
    sending the old value.
    """

    #: Text the user typed that could not be accepted (emitted on commit).
    entryRejected = QtCore.Signal(str)

    _NUMBER_RE = re.compile(r"[+-]?(?:\d+\.?\d*|\.\d*)?")
    #: A rejection older than this is stale and no longer blocks an action.
    REJECTION_TTL_S = 1.0

    def __init__(self, parent: QtWidgets.QWidget | None = None) -> None:
        super().__init__(parent)
        self._typed: str | None = None
        self._rejected: tuple[str, float] | None = None
        self.lineEdit().textEdited.connect(self._remember_typed)
        self.valueChanged.connect(self._forget_typed)

    def _remember_typed(self, text: str) -> None:
        """Keep the latest text typed by the user (not set by the program)."""
        self._typed = text
        self._rejected = None

    def _forget_typed(self, *_args: Any) -> None:
        """A new value is in force; nothing typed is pending."""
        self._typed = None

    def _number_part(self, text: str) -> str | None:
        """The numeric part of ``text``, or None if it cannot become a number."""
        core = text.strip()
        prefix = self.prefix().strip()
        if prefix and core.startswith(prefix):
            core = core[len(prefix):].strip()
        unit = self.suffix().strip()
        for cut in range(len(unit), 0, -1):     # whole unit, or partly deleted
            if core.endswith(unit[:cut]):
                core = core[:-cut].strip()
                break
        core = core.replace(self.locale().decimalPoint(), ".")
        return core if self._NUMBER_RE.fullmatch(core) else None

    def _parse(self, text: str) -> float | None:
        """The value ``text`` stands for, rounded to the box's decimals."""
        core = self._number_part(text)
        if core is None:
            return None
        try:
            return round(float(core), self.decimals())
        except ValueError:                       # "", "+", "-", "."
            return None

    def _in_range(self, value: float | None) -> bool:
        """True when ``value`` is a number inside the box's range."""
        return value is not None and self.minimum() <= value <= self.maximum()

    def validate(self, text: str, pos: int) -> tuple:  # noqa: D102 (Qt API)
        state = QtGui.QValidator.State
        if self._number_part(text) is None:
            return state.Invalid, text, pos
        if self._in_range(self._parse(text)):
            return state.Acceptable, text, pos
        return state.Intermediate, text, pos

    def valueFromText(self, text: str) -> float:  # noqa: N802 (Qt API)
        value = self._parse(text)
        return self.value() if value is None else value

    def _check_typed_on_commit(self) -> None:
        """On Enter or focus-out: report typed text that cannot be accepted."""
        typed = self._typed
        if typed is None or self._in_range(self._parse(typed)):
            return
        self._typed = None
        self._rejected = (typed, time.perf_counter())
        self.lineEdit().setText(self.prefix() + self.textFromValue(self.value()) + self.suffix())
        self.entryRejected.emit(typed)

    def _editable_span(self) -> tuple[int, int]:
        """Cursor limits of the number: after the prefix, before the suffix."""
        text = self.lineEdit().text()
        low = len(self.prefix()) if text.startswith(self.prefix()) else 0
        high = len(text) - len(self.suffix()) if text.endswith(self.suffix()) else len(text)
        return low, max(low, high)

    def keyPressEvent(self, event: QtGui.QKeyEvent) -> None:  # noqa: N802 (Qt API)
        key = event.key()
        keys = QtCore.Qt.Key
        edit = self.lineEdit()
        low, high = self._editable_span()
        if key in (keys.Key_Return, keys.Key_Enter):
            self._check_typed_on_commit()
        elif key == keys.Key_End and not event.modifiers() & QtCore.Qt.KeyboardModifier.ShiftModifier:
            edit.setCursorPosition(high)        # End = end of the number, not of the unit
            event.accept()
            return
        elif not edit.hasSelectedText() and (key == keys.Key_Backspace or event.text().isprintable()):
            # Typing or Backspace with the cursor inside the unit acts at the
            # end of the number instead of being refused.
            edit.setCursorPosition(min(max(edit.cursorPosition(), low), high))
            point = self.locale().decimalPoint()
            pos = edit.cursorPosition()
            if event.text() in (".", point) and edit.text()[pos:pos + 1] == point:
                # Typing the decimal point just before the existing one steps
                # over it, so "0", ".", "8" after deleting the "1" of
                # "1.000000000" gives 0.8, not 08 or a refused keystroke.
                edit.setCursorPosition(pos + 1)
                event.accept()
                return
        super().keyPressEvent(event)

    def focusOutEvent(self, event: QtGui.QFocusEvent) -> None:  # noqa: N802 (Qt API)
        self._check_typed_on_commit()
        super().focusOutEvent(event)

    def take_rejected_text(self) -> str | None:
        """The text just refused (within REJECTION_TTL_S), then forget it."""
        rejected, self._rejected = self._rejected, None
        if rejected is None or time.perf_counter() - rejected[1] > self.REJECTION_TTL_S:
            return None
        return rejected[0]


def make_double_spin(
    minimum: float,
    maximum: float,
    decimals: int,
    step: float,
    suffix: str = "",
    value: float = 0.0,
) -> QtWidgets.QDoubleSpinBox:
    """Construct a configured :class:`EntrySpinBox` (free typing, range-checked)."""
    spin = EntrySpinBox()
    spin.setRange(minimum, maximum)
    spin.setDecimals(decimals)
    spin.setSingleStep(step)
    spin.setSuffix(suffix)
    spin.setValue(value)
    spin.setKeyboardTracking(False)
    spin.setAccelerated(True)
    return spin


def make_int_spin(
    minimum: int, maximum: int, value: int = 0, suffix: str = ""
) -> QtWidgets.QSpinBox:
    """Construct a configured :class:`QSpinBox`."""
    spin = QtWidgets.QSpinBox()
    spin.setRange(minimum, maximum)
    spin.setValue(value)
    spin.setSuffix(suffix)
    spin.setKeyboardTracking(False)
    spin.setAccelerated(True)
    return spin


def fill_trigger_combo(combo: QtWidgets.QComboBox) -> None:
    """Populate a combo box with the documented trigger modes."""
    combo.addItem("Software trigger (start immediately)", TriggerMode.SOFTWARE)
    combo.addItem("Hardware trigger starts whole run", TriggerMode.FULL_TRIGGER)
    combo.addItem("Hardware trigger per point (min 150 us)", TriggerMode.POINT_TRIGGER)


def fill_direction_combo(combo: QtWidgets.QComboBox) -> None:
    """Populate a combo box with the documented sweep directions."""
    combo.addItem("Up (low to high)", SweepDirection.UP)
    combo.addItem("Down (high to low)", SweepDirection.DOWN)
    combo.addItem("Up and down", SweepDirection.UP_DOWN)


# %% ===========================================================================
#    TAB: CONNECTION
# =============================================================================
class ConnectionTab(QtWidgets.QWidget):
    """Port discovery, link setup, identity and firmware gate."""

    connectRequested = QtCore.Signal(str, int, bool)  # port, baud, simulate
    disconnectRequested = QtCore.Signal()

    def __init__(self, parent: QtWidgets.QWidget | None = None) -> None:
        super().__init__(parent)
        layout = QtWidgets.QVBoxLayout(self)

        # --- Link group -----------------------------------------------------
        link_box = QtWidgets.QGroupBox("Serial link (USB virtual COM port)")
        form = QtWidgets.QFormLayout(link_box)

        self.port_combo = QtWidgets.QComboBox()
        self.port_combo.setEditable(True)
        self.port_combo.setMinimumWidth(320)
        self.refresh_button = QtWidgets.QPushButton("Rescan ports")
        form.addRow("Port", labelled_row(self.port_combo, self.refresh_button))

        self.baud_combo = QtWidgets.QComboBox()
        for rate in (9600, 19200, 38400, 57600, 115200, 230400, 460800):
            self.baud_combo.addItem(str(rate), rate)
        self.baud_combo.setCurrentText(str(DEFAULT_BAUD))
        form.addRow("Baud rate", self.baud_combo)

        self.timeout_spin = make_double_spin(
            0.05, 10.0, 2, 0.05, " s", DEFAULT_READ_TIMEOUT_S
        )
        form.addRow("Read timeout", self.timeout_spin)

        self.gap_spin = make_double_spin(
            0.0, 0.2, 4, 0.001, " s", DEFAULT_INTERCOMMAND_GAP_S
        )
        form.addRow("Inter-command gap", self.gap_spin)

        self.simulate_check = QtWidgets.QCheckBox(
            "Simulator mode (no hardware; emulates an FSW-0020)"
        )
        form.addRow("", self.simulate_check)

        self.connect_button = QtWidgets.QPushButton("Connect")
        self.disconnect_button = QtWidgets.QPushButton("Disconnect")
        self.disconnect_button.setEnabled(False)
        form.addRow(
            "", labelled_row(self.connect_button, self.disconnect_button)
        )

        layout.addWidget(link_box)

        # --- Identity group -------------------------------------------------
        id_box = QtWidgets.QGroupBox("Instrument identity")
        id_form = QtWidgets.QFormLayout(id_box)
        self.idn_label = QtWidgets.QLabel("-")
        self.idn_label.setTextInteractionFlags(
            QtCore.Qt.TextInteractionFlag.TextSelectableByMouse
        )
        self.model_label = QtWidgets.QLabel("-")
        self.firmware_label = QtWidgets.QLabel("-")
        self.firmware_label.setWordWrap(True)     # long since 0.0.8 (option list)
        self.caps_label = QtWidgets.QLabel("-")
        self.caps_label.setWordWrap(True)
        # The SCPI *IDN? field order is undocumented, so every field is
        # shown verbatim next to its inferred label rather than hidden
        # behind this application's interpretation of it.
        self.fields_table = QtWidgets.QTableWidget(0, 2)
        self.fields_table.setHorizontalHeaderLabels(
            ["Field", "Raw value"]
        )
        self.fields_table.horizontalHeader().setStretchLastSection(True)
        self.fields_table.verticalHeader().setVisible(False)
        self.fields_table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers
        )
        self.fields_table.setMaximumHeight(170)
        id_form.addRow("*IDN? response", self.idn_label)
        id_form.addRow("Model", self.model_label)
        id_form.addRow("Firmware", self.firmware_label)
        id_form.addRow("Raw fields", self.fields_table)
        id_form.addRow("Capabilities", self.caps_label)
        layout.addWidget(id_box)

        # --- Notice ---------------------------------------------------------
        notice = QtWidgets.QLabel(
            "Link parameters are fixed by the vendor at 115200 baud, 8 data "
            "bits, no parity, 1 stop bit, no flow control, CR terminator, "
            "64-byte command buffer including the terminator. [R1] says SCPI "
            "needs firmware 100 or higher, but an FSL-0020 with firmware 0008 "
            "answers SCPI; the SPI port accepts native commands "
            "only and is not supported here. Leave the baud rate at 115200 "
            "for a USB connection: DIAG:BAUD retargets the debug port used "
            "by RS232, GPIB and Ethernet, not the USB virtual COM port."
        )
        notice.setWordWrap(True)
        notice.setStyleSheet("color: palette(mid);")
        layout.addWidget(notice)
        layout.addStretch(1)

        self.refresh_button.clicked.connect(self.refresh_ports)
        self.connect_button.clicked.connect(self._emit_connect)
        self.disconnect_button.clicked.connect(self.disconnectRequested.emit)
        self.refresh_ports()

    def refresh_ports(self) -> None:
        """Repopulate the port list from pyserial's enumeration."""
        self.port_combo.clear()
        if not HAVE_PYSERIAL:
            self.port_combo.addItem("pyserial not installed", "")
            return
        found = list(list_ports.comports())
        if not found:
            self.port_combo.addItem("No serial ports found", "")
            return
        for info in found:
            # The QuickSyn enumerates through an FTDI-class bridge and
            # typically shows as "QuickSyn USB Interface" or FSW_USBSerial.
            label = f"{info.device} - {info.description}"
            self.port_combo.addItem(label, info.device)

    def selected_port(self) -> str:
        """Return the chosen device path, falling back to typed text."""
        data = self.port_combo.currentData()
        if data:
            return str(data)
        text = self.port_combo.currentText().strip()
        return text.split(" - ")[0] if text else ""

    def _emit_connect(self) -> None:
        """Validate the selection and emit :attr:`connectRequested`."""
        simulate = self.simulate_check.isChecked()
        port = self.selected_port()
        if not simulate and not port:
            QtWidgets.QMessageBox.warning(
                self, "No port", "Select a serial port or enable Simulator mode."
            )
            return
        self.connectRequested.emit(
            port or "SIM", int(self.baud_combo.currentData() or DEFAULT_BAUD), simulate
        )

    def set_connected(self, connected: bool) -> None:
        """Enable or disable the connection controls."""
        self.connect_button.setEnabled(not connected)
        self.disconnect_button.setEnabled(connected)
        self.port_combo.setEnabled(not connected)
        self.baud_combo.setEnabled(not connected)
        self.simulate_check.setEnabled(not connected)

    def show_identity(self, ident: Identity, cap: ModelCapability) -> None:
        """Display the decoded identity and the matched capability row."""
        self.idn_label.setText(ident.raw or "-")
        self.model_label.setText(ident.model or "unknown")

        # Raw fields, verbatim, with the inferred label alongside.
        self.fields_table.setRowCount(len(ident.fields))
        for row, value in enumerate(ident.fields):
            label = (
                Identity.FIELD_LABELS[row]
                if row < len(Identity.FIELD_LABELS)
                else f"Field {row} (undocumented)"
            )
            self.fields_table.setItem(row, 0, QtWidgets.QTableWidgetItem(label))
            self.fields_table.setItem(row, 1, QtWidgets.QTableWidgetItem(value))
        self.fields_table.resizeColumnsToContents()

        supported = ident.scpi_supported
        if supported is None:
            fw_text = (
                f"{ident.firmware or '?'} - parses as neither decimal nor "
                f"hexadecimal, so the firmware gate could not be evaluated. "
                f"The unit answered *IDN?, so SCPI is being serviced."
            )
            colour = "#c58a00"
        elif supported:
            fw_text = (
                f"{ident.firmware} = {ident.firmware_value} "
                f"({ident.firmware_base}); at or above the documented "
                f"firmware {MIN_SCPI_FIRMWARE} minimum for SCPI."
            )
            colour = "#2faf4a"
        else:
            fw_text = (
                f"{ident.firmware} = {ident.firmware_value} "
                f"({ident.firmware_base}). [R1] says SCPI needs firmware "
                f"{MIN_SCPI_FIRMWARE} or higher, but this unit answers SCPI, so that "
                f"rule evidently uses another numbering (an FSL-0020 with "
                f"firmware 0008 answers SCPI). Informational only."
            )
            colour = "#8a8d93"
        options = ident.option_numbers
        if options:
            fw_text += (f"<br>Option word {ident.options}: options "
                        f"{', '.join(str(n) for n in options)} (bit n = option n+1, "
                        f"as NI's calibration panel decodes it).")
        self.firmware_label.setText(f'<span style="color:{colour};">{fw_text}</span>')

        lower = cap.f_min_opt1_hz if cap.f_min_opt1_hz is not None else cap.f_min_hz
        self.caps_label.setText(
            f"{cap.model}: {lower / 1e9:.3f} - {cap.f_max_hz / 1e9:.3f} GHz, "
            f"resolution {cap.f_resolution_hz:g} Hz, "
            + (f"power control {cap.p_min_dbm:+.1f} to {cap.p_max_dbm:+.1f} dBm with "
               f"option 2 (checked by read-back after each change). "
               if cap.has_power_control else
               f"fixed output level {cap.p_default_dbm:+.1f} dBm typical (no power control). ")
            + ("SCPI set documented for this model. " if cap.scpi_documented
               else "SCPI set NOT explicitly documented for this model; "
                    "commands are offered but unverified. ")
            + cap.notes
        )


# %% ===========================================================================
