# =============================================================================
class MainControlTab(QtWidgets.QWidget):
    """Carrier, level, output routing, reference and instrument states."""

    def __init__(
        self, controller: "AppController", parent: QtWidgets.QWidget | None = None
    ) -> None:
        super().__init__(parent)
        self.ctl = controller
        #: Last reference source read (ROSC:SOUR?) and last decoded STAT?.
        self._ref_source: RefSource | None = None
        self._last_status: StatusWord | None = None
        #: True while OUTP:ROSC:STAT? and STAT? bit 5 disagree (warned once).
        self._refout_mismatch = False
        #: (perf_counter time, value) of the previous temperature reading.
        self._last_temp: tuple[float, float] | None = None
        root = QtWidgets.QHBoxLayout(self)

        # --- Left column: carrier and level ---------------------------------
        left = QtWidgets.QVBoxLayout()

        freq_box = QtWidgets.QGroupBox("Carrier frequency")
        freq_form = QtWidgets.QFormLayout(freq_box)
        self.freq_spin = make_double_spin(0.0001, 82.0, 9, 0.001, " GHz", 10.0)
        self.freq_spin.setToolTip(
            "FREQ. Sent as integer millihertz, the documented default unit."
        )
        self.set_freq_button = QtWidgets.QPushButton("Set frequency")
        self.read_freq_button = QtWidgets.QPushButton("Read (FREQ?)")
        freq_form.addRow("Frequency", self.freq_spin)
        freq_form.addRow(
            "", labelled_row(self.set_freq_button, self.read_freq_button)
        )
        self.freq_readback = QtWidgets.QLabel("-")
        self.freq_readback.setWordWrap(True)
        freq_form.addRow("Readback", self.freq_readback)
        left.addWidget(freq_box)

        pow_box = QtWidgets.QGroupBox("Output level")
        pow_form = QtWidgets.QFormLayout(pow_box)
        self.power_spin = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", 0.0)
        self.power_spin.setToolTip(
            "POW. Quantised to 0.1 dB, the granularity of the command set."
        )
        self.set_power_button = QtWidgets.QPushButton("Set power")
        self.read_power_button = QtWidgets.QPushButton("Read (POW?)")
        #: Cross-check with the native Get Power query (bring-up aid).
        self.read_power_native_button = QtWidgets.QPushButton("Read (0D)")
        self.read_power_native_button.setToolTip(
            "Native Get Power query 0D [R1, Table 4], an independent check on POW?.")
        pow_form.addRow("Power", self.power_spin)
        pow_form.addRow(
            "", labelled_row(self.set_power_button, self.read_power_button,
                             self.read_power_native_button)
        )
        self.power_range_label = QtWidgets.QLabel("-")
        self.power_range_label.setWordWrap(True)
        pow_form.addRow("Range", self.power_range_label)
        self.power_cmd_combo = QtWidgets.QComboBox()
        self.power_cmd_combo.addItem("Auto: SCPI POW, then native 03 if not applied", "auto")
        self.power_cmd_combo.addItem("SCPI only (POW +12.0)", "scpi")
        self.power_cmd_combo.addItem("Native only (030078)", "native")
        self.power_cmd_combo.setToolTip(
            "Both command sets are accepted on USB, Ethernet, GPIB and RS232 [R1]. Auto "
            "tries SCPI and falls back to the native command if POW? shows no change.")
        pow_form.addRow("Command", self.power_cmd_combo)
        self.power_readback = QtWidgets.QLabel("-")
        self.power_readback.setWordWrap(True)
        pow_form.addRow("Readback", self.power_readback)
        #: Level expected at RF OUT from the active power calibration (0.0.10).
        self.cal_output_label = QtWidgets.QLabel("no power calibration for this unit")
        self.cal_output_label.setWordWrap(True)
        self.cal_output_label.setToolTip(
            "From the active table on the Calibration tab: the measured level at RF OUT, "
            "interpolated in frequency. Not a live measurement.")
        pow_form.addRow("At RF OUT (power cal)", self.cal_output_label)
        self._cal_command: tuple[float, float] | None = None   # (target, commanded)
        #: Shown instead of the controls on fixed-output models.
        self.power_note = QtWidgets.QLabel("")
        self.power_note.setWordWrap(True)
        self.power_note.setVisible(False)
        pow_form.addRow(self.power_note)
        left.addWidget(pow_box)

        out_box = QtWidgets.QGroupBox("Output and reference")
        out_form = QtWidgets.QFormLayout(out_box)
        self.rf_check = QtWidgets.QCheckBox("RF output on (OUTP:STAT)")
        #: Always-available mute, also on the toolbar and Ctrl+Shift+O.
        self.rf_off_button = QtWidgets.QPushButton("RF OUTPUT OFF")
        self.rf_off_button.setToolTip("OUTP:STAT OFF, confirmed with STAT? (Ctrl+Shift+O)")
        self.rf_off_button.setStyleSheet(
            # A border makes Qt draw the button from the style sheet alone; with
            # only a background colour the platform bevel tints it pale red.
            "QPushButton { background-color: #c62828; color: white; font-weight: bold; "
            "border: 1px solid #8e1b1b; border-radius: 3px; padding: 6px 14px; } "
            "QPushButton:hover { background-color: #d32f2f; } "
            "QPushButton:pressed { background-color: #8e1b1b; } "
            "QPushButton:disabled { background-color: #8c8c8c; border-color: #6e6e6e; }")
        self.blank_check = QtWidgets.QCheckBox(
            "Blanking on (OUTP:BLAN) - mute while retuning"
        )
        self.refout_check = QtWidgets.QCheckBox(
            "10 MHz reference output on (OUTP:ROSC:STAT)"
        )
        self.lockrec_check = QtWidgets.QCheckBox(
            "Lock recovery on (FREQ:LRSTAT)"
        )
        self.refsrc_combo = QtWidgets.QComboBox()
        self.refsrc_combo.addItem("Internal OCXO", RefSource.INTERNAL)
        self.refsrc_combo.addItem("External 10 MHz (+/-2 ppm)", RefSource.EXTERNAL)
        out_form.addRow("", self.rf_check)
        out_form.addRow("", self.rf_off_button)
        out_form.addRow("", self.blank_check)
        out_form.addRow("", self.refout_check)
        out_form.addRow("", self.lockrec_check)
        out_form.addRow("Reference source", self.refsrc_combo)
        left.addWidget(out_box)
        left.addStretch(1)

        # --- Right column: status and states --------------------------------
        right = QtWidgets.QVBoxLayout()

        status_box = QtWidgets.QGroupBox("Status (STAT?)")
        status_layout = QtWidgets.QVBoxLayout(status_box)
        self.led_rf_lock = LEDIndicator("RF lock")
        self.led_ref_lock = LEDIndicator("Reference lock")
        self.led_ext_ref = LEDIndicator("External reference")
        self.led_rf_out = LEDIndicator("RF output")
        self.led_voltage = LEDIndicator("Supply voltage")
        self.led_ref_out = LEDIndicator("Reference output")
        self.led_blanking = LEDIndicator("Blanking")
        self.led_lockrec = LEDIndicator("Lock recovery")
        #: Which 10 MHz reference is in use (ROSC:SOUR?, with presence and lock).
        self.led_ref_int = LEDIndicator("Internal 10 MHz reference")
        self.led_ref_ext = LEDIndicator("External 10 MHz reference")
        for led in (
            self.led_rf_lock,
            self.led_ref_lock,
            self.led_ref_int,
            self.led_ref_ext,
            self.led_ext_ref,
            self.led_rf_out,
            self.led_voltage,
            self.led_ref_out,
            self.led_blanking,
            self.led_lockrec,
        ):
            status_layout.addWidget(led)
        self.status_raw_label = QtWidgets.QLabel("raw: -")
        status_layout.addWidget(self.status_raw_label)
        self.refresh_status_button = QtWidgets.QPushButton("Refresh status")
        status_layout.addWidget(self.refresh_status_button)
        right.addWidget(status_box)

        temp_box = QtWidgets.QGroupBox("Internal temperature (DIAG:MEAS? 21)")
        temp_layout = QtWidgets.QVBoxLayout(temp_box)
        self.temp_label = QtWidgets.QLabel("-")
        font = self.temp_label.font()
        font.setPointSize(font.pointSize() + 6)
        font.setBold(True)
        self.temp_label.setFont(font)
        temp_layout.addWidget(self.temp_label)
        self.temp_warning = QtWidgets.QLabel(
            "Keep the internal temperature below +75 C; use a heatsink or "
            "forced air."
        )
        self.temp_warning.setWordWrap(True)
        self.temp_warning.setStyleSheet("color: palette(mid);")
        temp_layout.addWidget(self.temp_warning)
        self.read_temp_button = QtWidgets.QPushButton("Read temperature")
        temp_layout.addWidget(self.read_temp_button)
        right.addWidget(temp_box)

        state_box = QtWidgets.QGroupBox("Instrument states")
        state_layout = QtWidgets.QGridLayout(state_box)
        self.reset_button = QtWidgets.QPushButton("*RST (reset)")
        self.save1_button = QtWidgets.QPushButton("*SAV 1")
        self.save2_button = QtWidgets.QPushButton("*SAV 2")
        self.rcl0_button = QtWidgets.QPushButton("*RCL 0 (factory)")
        self.rcl1_button = QtWidgets.QPushButton("*RCL 1")
        self.rcl2_button = QtWidgets.QPushButton("*RCL 2")
        state_layout.addWidget(self.reset_button, 0, 0, 1, 2)
        state_layout.addWidget(self.save1_button, 1, 0)
        state_layout.addWidget(self.save2_button, 1, 1)
        state_layout.addWidget(self.rcl0_button, 2, 0, 1, 2)
        state_layout.addWidget(self.rcl1_button, 3, 0)
        state_layout.addWidget(self.rcl2_button, 3, 1)
        right.addWidget(state_box)

        self.sync_button = QtWidgets.QPushButton("Read all settings from instrument")
        right.addWidget(self.sync_button)
        auto_row = QtWidgets.QHBoxLayout()
        self.auto_sync_check = QtWidgets.QCheckBox("Auto-read all settings every")
        self.auto_sync_check.setToolTip(
            "Repeats 'Read all settings' on this interval while connected. A box you "
            "are typing in is not overwritten; stops after three failed reads.")
        self.auto_sync_spin = make_double_spin(1.0, 3600.0, 1, 1.0, " s", DEFAULT_AUTO_SYNC_S)
        auto_row.addWidget(self.auto_sync_check)
        auto_row.addWidget(self.auto_sync_spin)
        auto_row.addStretch(1)
        right.addLayout(auto_row)
        right.addStretch(1)

        root.addLayout(left, 3)
        root.addLayout(right, 2)

        self._wire()

    def _wire(self) -> None:
        """Connect widget signals to controller actions."""
        c = self.ctl
        # Enter in either box applies it, as the Set button does (0.0.6 only
        # applied on the button, so a typed level and Enter changed nothing).
        self._enter_filters = [
            EnterApplies(self.freq_spin, lambda: c.guard(lambda: self._apply_frequency())),
            EnterApplies(self.power_spin, lambda: c.guard(lambda: self._apply_power())),
        ]
        self.set_freq_button.clicked.connect(
            lambda: c.guard(lambda: self._apply_frequency())
        )
        self.read_freq_button.clicked.connect(
            lambda: c.guard(lambda: self.freq_readback.setText(
                f"{c.driver.get_frequency() / 1e9:.9f} GHz"
            ))
        )
        self.set_power_button.clicked.connect(
            lambda: c.guard(lambda: self._apply_power())
        )
        self.read_power_button.clicked.connect(
            lambda: c.guard(lambda: self.power_readback.setText(
                f"POW? reports {c.driver.get_power():+.1f} dBm" + self._rf_note()
            ))
        )
        self.read_power_native_button.clicked.connect(
            lambda: c.guard(lambda: self.power_readback.setText(
                f"native Get Power (0D) reports {c.driver.get_power_native():+.1f} dBm"
                + self._rf_note()
            ))
        )
        self.rf_check.clicked.connect(
            lambda v: c.guard(lambda: c.driver.set_rf_output(v))
        )
        self.rf_off_button.clicked.connect(c.rf_off)
        self.blank_check.clicked.connect(
            lambda v: c.guard(lambda: c.driver.set_blanking(v))
        )
        self.refout_check.clicked.connect(
            lambda v: c.guard(lambda: self._apply_reference_output(v))
        )
        self.lockrec_check.clicked.connect(
            lambda v: c.guard(lambda: c.driver.set_lock_recovery(v))
        )
        self.refsrc_combo.activated.connect(
            lambda _: c.guard(self._apply_reference_source)
        )
        self.refresh_status_button.clicked.connect(
            lambda: c.guard(lambda: self.update_status(c.driver.get_status()))
        )
        self.read_temp_button.clicked.connect(
            lambda: c.guard(lambda: self.update_temperature(
                c.driver.get_temperature()
            ))
        )
        self.reset_button.clicked.connect(lambda: c.guard(self._do_reset))
        self.save1_button.clicked.connect(
            lambda: c.guard(lambda: c.driver.save_state(1))
        )
        self.save2_button.clicked.connect(
            lambda: c.guard(lambda: c.driver.save_state(2))
        )
        self.rcl0_button.clicked.connect(
            lambda: c.guard(lambda: c.driver.recall_state(0))
        )
        self.rcl1_button.clicked.connect(
            lambda: c.guard(lambda: c.driver.recall_state(1))
        )
        self.rcl2_button.clicked.connect(
            lambda: c.guard(lambda: c.driver.recall_state(2))
        )
        self.sync_button.clicked.connect(lambda: c.guard(c.sync_from_instrument))
        self.auto_sync_check.toggled.connect(
            lambda on: c.set_auto_sync(on, self.auto_sync_spin.value()))
        self.auto_sync_spin.valueChanged.connect(
            lambda v: c.set_auto_sync(self.auto_sync_check.isChecked(), v))

    def _show_readback(self, label: QtWidgets.QLabel, ok: bool, text: str) -> None:
        """Readback line: plain when the instrument followed, red otherwise."""
        label.setText(text if ok else f'<span style="color:#d9483b;">{html.escape(text)}</span>')

    def _rf_note(self) -> str:
        """Reminder for read-backs: POW? is the level setting, not a measurement."""
        status = self._last_status
        if status is not None and not status.rf_output_on:
            return " (the level setting; the RF output is OFF)"
        return ""

    def _apply_frequency(self) -> None:
        """Command the frequency, read it back with FREQ? and compare."""
        if self.freq_spin.take_rejected_text() is not None:
            return                      # refused typed value, already reported
        commanded, reported = self.ctl.driver.set_frequency_checked(self.freq_spin.value() * 1e9)
        ok = hz_to_mlhz(reported) == hz_to_mlhz(commanded)
        text = (f"set {commanded / 1e9:.9f} GHz; instrument reports {reported / 1e9:.9f} GHz"
                + ("" if ok else " - the instrument did not follow"))
        self._show_readback(self.freq_readback, ok, text)
        if not ok:
            self.ctl.warn(f"FREQ {commanded / 1e9:.9f} GHz sent, but FREQ? reports "
                          f"{reported / 1e9:.9f} GHz.")
        cal = getattr(self.ctl.window, "tab_cal", None)
        if cal is not None and cal.correction_enabled():
            self._apply_power()             # the correction depends on frequency
        self.update_cal_output(reported)

    def update_cal_output(self, freq_hz: float | None = None) -> None:
        """Show the level the active power calibration expects at RF OUT."""
        cal = getattr(self.ctl.window, "tab_cal", None)
        table = cal.active_table if cal is not None else None
        if table is None or not table.points:
            self.cal_output_label.setText("no power calibration for this unit (Calibration tab)")
            return
        if not cal.show_expected_check.isChecked():
            self.cal_output_label.setText("hidden (Calibration tab)")
            return
        f = self.freq_spin.value() * 1e9 if freq_hz is None else freq_hz
        fixed = table.levels() == [None]
        command = None if fixed else self.power_spin.value()
        prefix = ""
        if not fixed and self._cal_command is not None and cal.correction_enabled():
            target, command = self._cal_command
            prefix = f"target {target:+.1f} dBm, commanded {command:+.1f} dBm; "
        expected = table.expected_output(f, command)
        if expected is None:
            lo, hi = table.frequency_span()
            text = (f"{f / 1e9:.6f} GHz is outside the calibrated band "
                    f"{lo / 1e9:.3f}-{hi / 1e9:.3f} GHz")
        else:
            text = f"{prefix}{expected:+.2f} dBm expected at {f / 1e9:.6f} GHz"
        self.cal_output_label.setText(text + self._rf_note().replace("the level setting; ", ""))

    def _apply_power(self) -> None:
        """Command the level, read it back with POW? and compare.

        A unit without power-control option 2 accepts POW but keeps its
        rated level, and *IDN? does not say whether option 2 is fitted, so
        the read-back is the only way to tell.
        """
        if self.power_spin.take_rejected_text() is not None:
            return                      # refused typed value, already reported
        mode = self.power_cmd_combo.currentData()
        target = self.power_spin.value()
        command = target
        self._cal_command = None
        cal = getattr(self.ctl.window, "tab_cal", None)
        if cal is not None and cal.correction_enabled():
            # Level correction (0.0.10): command what the table says puts
            # the typed level at RF OUT at the instrument's frequency.
            cap = self.ctl.driver.capability
            freq = self.ctl.driver.get_frequency()
            corrected = cal.active_table.command_for_target(freq, target, cap.p_min_dbm,
                                                            cap.p_max_dbm)
            if corrected is None:
                self.ctl.warn(f"Level correction: {freq / 1e9:.6f} GHz is outside the active "
                              f"power calibration; {target:+.1f} dBm is sent uncorrected.")
            else:
                command = corrected
                self._cal_command = (target, corrected)
        commanded, reported, used = self.ctl.driver.set_power_checked(
            command, command_set=mode)
        ok = abs(reported - commanded) <= POWER_READBACK_TOL_DB
        how = "SCPI POW" if used == "scpi" else f"native {native_power_command(commanded)}"
        corrected_text = (f" for {target:+.1f} dBm at RF OUT (power calibration)"
                          if self._cal_command is not None else "")
        text = (f"set {commanded:+.1f} dBm{corrected_text} ({how}); instrument reports "
                f"{reported:+.1f} dBm" + ("" if ok else " - the level did not change")
                + self._rf_note())
        self._show_readback(self.power_readback, ok, text)
        self.update_cal_output()
        if ok and mode == "auto" and used == "native":
            # SCPI POW was ignored but the native command worked: use it
            # directly from now on, and say so.
            self.power_cmd_combo.setCurrentIndex(self.power_cmd_combo.findData("native"))
            self.ctl.warn("SCPI POW did not change the level, the native power command "
                          "did; switched the power command to Native for this session.")
        if not ok:
            tried = "SCPI POW and the native 03 command" if mode == "auto" else how
            self.ctl.warn(
                f"{tried} sent for {commanded:+.1f} dBm, but POW? still reports "
                f"{reported:+.1f} dBm. This unit may not have power-control option 2, or "
                f"the level is outside what it can produce at this frequency."
            )

    def _apply_reference_output(self, enabled: bool) -> None:
        """Switch the 10 MHz output, read it back, fall back to native 08xx.

        On the FSL-0020 tested, OUTP:ROSC:STAT OFF left STAT? bit 5 set, while
        NI's panel (native commands) switched REF OUT off on a power meter.
        STAT? bit 5 is checked (and OUTP:ROSC:STAT? where the unit answers it);
        if the output did not follow, the native command is tried, and once it
        works it is used for the rest of the session (0.0.9).
        """
        driver = self.ctl.driver
        state = "ON" if enabled else "OFF"
        native = native_switch_command(NATIVE_REF_OUTPUT, enabled)
        was_native = driver.reference_output_command == "native"
        was_unreliable = driver.refout_status_reliable is False
        reported, status, used = driver.set_reference_output_checked(enabled)
        self.update_status(status)
        if reported is not None:
            self.show_reference_output(reported, "OUTP:ROSC:STAT?")
        if reported is None and driver.refout_status_reliable is False:
            # The unit does not report the 10 MHz output (FSL-0020: bit 5
            # stays set while REF OUT switches) (0.0.10).
            self.refout_check.setChecked(enabled)
            self.show_reference_output(None)
            if was_unreliable:
                self.ctl.status_message(
                    f"10 MHz reference output {state} sent (OUTP:ROSC:STAT). This unit does not "
                    f"report the state; check REF OUT on a meter if in doubt.")
            else:
                self.ctl.warn(
                    f"OUTP:ROSC:STAT {state} and the native {native} sent; STAT? bit 5 did not "
                    f"change and OUTP:ROSC:STAT? does not answer. On the FSL-0020 tested REF OUT "
                    f"does switch while bit 5 stays set, so the state is shown as 'not reported' "
                    f"and OUTP:ROSC:STAT alone is sent from now on. Check REF OUT on a power "
                    f"meter or counter.")
            return
        if was_native:
            how = f"native {native}"
        elif used == "scpi":
            how = "OUTP:ROSC:STAT"
        else:
            how = f"OUTP:ROSC:STAT, then the native {native}"
        checks = "OUTP:ROSC:STAT?" if reported is not None else "STAT?"
        followed = reported == enabled if reported is not None else status.ref_output_on == enabled
        if followed:
            self.ctl.status_message(f"10 MHz reference output {state} ({how}; confirmed by {checks}).")
            if used == "native" and not was_native:
                self.ctl.warn("OUTP:ROSC:STAT did not change the 10 MHz output, the native "
                              f"{native} did; the native command is used for the rest of this "
                              "session.")
            return
        if reported is not None:
            self.ctl.warn(f"{how} {state} sent, but OUTP:ROSC:STAT? reports "
                          f"{'ON' if reported else 'OFF'}. Check REF OUT on a power meter or "
                          f"counter.")
        else:
            self.ctl.warn(f"{how} {state} sent, but STAT? bit 5 reports "
                          f"{'ON' if status.ref_output_on else 'OFF'}. Check REF OUT on a power "
                          f"meter or counter.")

    def _apply_reference_source(self) -> None:
        """Select the reference, read it back with ROSC:SOUR?, then re-check the lock."""
        wanted = RefSource(str(self.refsrc_combo.currentData()))
        reported, status, used = self.ctl.driver.set_reference_source_checked(wanted)
        self.update_status(status)
        self.update_reference(reported, status)
        if reported != wanted:
            self.ctl.warn(f"ROSC:SOUR {wanted.value} (and the native 06 command) sent, but "
                          f"ROSC:SOUR? reports {reported.value}.")
            return
        self.ctl.status_message(
            f"Reference source {wanted.value} (confirmed by ROSC:SOUR?"
            + (", native 06 command" if used == "native" else "") + ").")
        # The reference loop needs a moment to lock; look again shortly.
        QtCore.QTimer.singleShot(1500, lambda: self.ctl.guard(self._recheck_reference))

    def _recheck_reference(self) -> None:
        """After a source change: refresh the LEDs and warn if not locked."""
        status = self.ctl.driver.get_status()
        source = self.ctl.driver.get_reference_source()
        self.update_status(status)
        self.update_reference(source, status)
        if source is RefSource.EXTERNAL and not status.ext_ref_present:
            self.ctl.warn("External reference selected, but no 10 MHz signal is detected at "
                          "REF IN (STAT? bit 0). The unit cannot lock to it.")
        elif not status.ref_locked:
            self.ctl.warn(f"Reference source {source.value}: the reference is NOT LOCKED.")

    def note_reference_output(self, query_on: bool, status: StatusWord) -> None:
        """Show OUTP:ROSC:STAT? (trusted when it answers) and note a stale bit 5 once."""
        self.show_reference_output(query_on, "OUTP:ROSC:STAT?")
        mismatch = query_on != status.ref_output_on
        if mismatch and not self._refout_mismatch:
            self.ctl.status_message(
                f"OUTP:ROSC:STAT? reports {'ON' if query_on else 'OFF'} while STAT? bit 5 reports "
                f"{'ON' if status.ref_output_on else 'OFF'}; the query is used for the 10 MHz "
                f"output (bit 5 does not follow it on the FSL-0020 tested).")
        self._refout_mismatch = mismatch

    def show_reference_output(self, state: bool | None, source: str = "") -> None:
        """Set the reference-output LED and checkbox from a trusted source.

        ``state`` None means the unit does not report it: grey LED naming
        the state last sent, and the checkbox is left as the user set it.
        """
        if state is None:
            sent = self.ctl.driver.refout_commanded if self.ctl.driver is not None else None
            last = "" if sent is None else f" (last sent {'ON' if sent else 'OFF'})"
            self.led_ref_out.set_state(None, f"Ref output: not reported{last}")
            return
        self.led_ref_out.set_state(
            True if state else None,
            ("Ref output on" if state else "Ref output off") + (f" ({source})" if source else ""))
        self.refout_check.blockSignals(True)
        self.refout_check.setChecked(state)
        self.refout_check.blockSignals(False)

    def _do_reset(self) -> None:
        """Reset and immediately read back, rather than assume defaults.

        [R1] Table 2a factory-default item (d) lists "Blanking: ON" while
        [R2] Table 1 lists "Blanking: off", so the post-reset state is
        observed rather than assumed. The agreed defaults are RF output off,
        10 GHz, +15 dBm (FSW-0010) or +13 dBm (FSW-0020), internal
        reference, reference output on, all modulation off, sensitivities 0.
        """
        self.ctl.driver.reset()
        self.ctl.sync_from_instrument()
        self.ctl.status_message(
            "Reset issued; state read back from the instrument rather than "
            "assumed, because [R1] Table 2a and [R2] Table 1 disagree on "
            "the post-reset blanking default."
        )

    # --- Display updates ----------------------------------------------------
    def update_status(self, status: StatusWord) -> None:
        """Refresh the status LEDs from a decoded status word."""
        self.led_rf_lock.set_state(
            status.rf_locked, "RF locked" if status.rf_locked else "RF UNLOCKED"
        )
        self.led_ref_lock.set_state(
            status.ref_locked,
            "Reference locked" if status.ref_locked else "Reference UNLOCKED",
        )
        self.led_ext_ref.set_state(
            True if status.ext_ref_present else None,
            "External reference detected"
            if status.ext_ref_present
            else "No external reference",
        )
        self.led_rf_out.set_state(
            True if status.rf_output_on else None,
            "RF output ON" if status.rf_output_on else "RF output off",
        )
        self.led_voltage.set_state(
            not status.voltage_error,
            "Supply voltage OK" if not status.voltage_error else "VOLTAGE ERROR",
        )
        driver = self.ctl.driver
        refout_known = driver is None or driver.refout_status_reliable is not False
        if refout_known:
            self.led_ref_out.set_state(
                True if status.ref_output_on else None,
                "Ref output on" if status.ref_output_on else "Ref output off",
            )
        else:
            self.show_reference_output(None)
        self.led_blanking.set_state(
            True if status.blanking_on else None,
            "Blanking on" if status.blanking_on else "Blanking off",
        )
        self.led_lockrec.set_state(
            True if status.lock_recovery_on else None,
            "Lock recovery on" if status.lock_recovery_on else "Lock recovery off",
        )
        self.status_raw_label.setText(f"raw: 0x{status.raw:02X}")
        self._last_status = status
        self.update_reference(None, status)

        # Reflect state in the checkboxes without re-emitting commands. The
        # reference-output box is not taken from a bit 5 known to be stale.
        boxes = [(self.rf_check, status.rf_output_on),
                 (self.blank_check, status.blanking_on),
                 (self.lockrec_check, status.lock_recovery_on)]
        if refout_known:
            boxes.append((self.refout_check, status.ref_output_on))
        for widget, value in boxes:
            widget.blockSignals(True)
            widget.setChecked(value)
            widget.blockSignals(False)

    def update_reference(self, source: RefSource | str | None,
                         status: StatusWord | None = None) -> None:
        """Set the Internal / External 10 MHz reference LEDs.

        ``source`` comes from ROSC:SOUR? (None keeps the last one known);
        ``status`` supplies presence at REF IN (bit 0) and the reference lock.
        """
        if source is not None:
            self._ref_source = RefSource(str(source).strip().upper())
        if status is not None:
            self._last_status = status
        src, st = self._ref_source, self._last_status
        if src is None:
            self.led_ref_int.set_state(None, "Internal 10 MHz reference")
            self.led_ref_ext.set_state(None, "External 10 MHz reference")
            return
        present = st.ext_ref_present if st is not None else None
        locked = st.ref_locked if st is not None else None
        if src is RefSource.INTERNAL:
            self.led_ref_int.set_state(
                locked is not False,
                "Internal 10 MHz reference IN USE" + ("" if locked is not False else " - NOT LOCKED"))
            self.led_ref_ext.set_state(
                None, "External 10 MHz reference not selected"
                + (" (signal present at REF IN)" if present else ""))
        else:
            ok = bool(present) and locked is not False
            self.led_ref_ext.set_state(
                ok, "External 10 MHz reference IN USE" if ok else
                ("External 10 MHz selected - NO SIGNAL at REF IN" if not present
                 else "External 10 MHz selected - NOT LOCKED"))
            self.led_ref_int.set_state(None, "Internal 10 MHz reference not selected")

    def update_temperature(self, celsius: float) -> None:
        """Refresh the temperature display and colour-code the margin.

        A change of TEMP_STEP_SUSPECT_C or more since a reading less than
        TEMP_STEP_WINDOW_S ago is flagged: the case cannot change that fast.
        On the FSL-0020 tested, DIAG:MEAS? 21 read twice its value after a POW
        command until the next OUTP:STAT (0.0.8).
        """
        now = time.perf_counter()
        suspect = False
        previous = self._last_temp
        if previous is not None and now - previous[0] <= TEMP_STEP_WINDOW_S \
                and abs(celsius - previous[1]) >= TEMP_STEP_SUSPECT_C:
            suspect = True
            self.ctl.warn(
                f"Temperature reading changed from {previous[1]:.1f} to {celsius:.1f} C within "
                f"{now - previous[0]:.0f} s; a real case temperature cannot step like that, so "
                f"treat the reading as suspect.")
        self._last_temp = (now, celsius)
        self.temp_label.setText(f"{celsius:.1f} \u00b0C" + ("  (suspect step)" if suspect else ""))
        if celsius >= 75.0:
            colour = "#d14545"
        elif celsius >= 65.0:
            colour = "#c58a00"
        else:
            colour = "#2faf4a"
        self.temp_label.setStyleSheet(f"color: {colour};")


# %% ===========================================================================
#    TAB: MODULATION
# =============================================================================
class ModulationTab(QtWidgets.QWidget):
    """Pulse, AM and FM/phase modulation controls."""

    def __init__(
        self, controller: "AppController", parent: QtWidgets.QWidget | None = None
    ) -> None:
        super().__init__(parent)
        self.ctl = controller
        layout = QtWidgets.QVBoxLayout(self)

        # --- Pulse ----------------------------------------------------------
        pulse_box = QtWidgets.QGroupBox("Pulse modulation (PULM:STAT)")
        pulse_layout = QtWidgets.QVBoxLayout(pulse_box)
        self.pulse_check = QtWidgets.QCheckBox("Pulse modulation on")
        pulse_layout.addWidget(self.pulse_check)
        pulse_layout.addWidget(
            self._note(
                "CMOS input: +5 V = RF on, 0 V = RF off, internally pulled "
                "up so an open input leaves RF on. 80 dB on-off ratio, 50 ns "
                "minimum width, DC to 10 MHz PRF, +6 V absolute maximum. "
                "Set the carrier to maximum power for the best on-off ratio."
            )
        )
        layout.addWidget(pulse_box)

        # --- AM -------------------------------------------------------------
        am_box = QtWidgets.QGroupBox("Amplitude modulation (AM:STAT, AM:DEPT)")
        am_form = QtWidgets.QFormLayout(am_box)
        self.am_check = QtWidgets.QCheckBox("AM on")
        self.am_dac = make_int_spin(MOD_DAC_MIN, MOD_DAC_MAX, 0, " counts")
        self.am_slider = QtWidgets.QSlider(QtCore.Qt.Orientation.Horizontal)
        self.am_slider.setRange(MOD_DAC_MIN, MOD_DAC_MAX)
        self.am_apply = QtWidgets.QPushButton("Apply sensitivity")
        self.am_read = QtWidgets.QPushButton("Read")
        am_form.addRow("", self.am_check)
        am_form.addRow("Sensitivity DAC", self.am_dac)
        am_form.addRow("", self.am_slider)
        am_form.addRow("", labelled_row(self.am_apply, self.am_read))
        am_form.addRow(
            "",
            self._note(
                "12-bit code, 0 to 4095. Sensitivity is frequency dependent "
                "and user defined, so the code does not map to a fixed depth. "
                "Input is DC to 100 kHz, +/-1 V (2 V p-p) into 50 ohm, "
                "+/-2 V absolute maximum. Set the carrier mid-range for best "
                "linearity. AM requires option 2."
            ),
        )
        layout.addWidget(am_box)

        # --- FM / phase -----------------------------------------------------
        fm_box = QtWidgets.QGroupBox(
            "Frequency and phase modulation (FM:STAT, FM:MODE, FM:SENS)"
        )
        fm_form = QtWidgets.QFormLayout(fm_box)
        self.fm_check = QtWidgets.QCheckBox("FM / phase modulation on")
        self.fm_mode_combo = QtWidgets.QComboBox()
        for mode in FMMode:
            self.fm_mode_combo.addItem(mode.label, mode)
        self.fm_mode_combo.setCurrentIndex(1)  # FM wide is the documented default
        self.fm_dac = make_int_spin(MOD_DAC_MIN, MOD_DAC_MAX, 0, " counts")
        self.fm_slider = QtWidgets.QSlider(QtCore.Qt.Orientation.Horizontal)
        self.fm_slider.setRange(MOD_DAC_MIN, MOD_DAC_MAX)
        self.fm_apply = QtWidgets.QPushButton("Apply sensitivity")
        self.fm_read = QtWidgets.QPushButton("Read")
        fm_form.addRow("", self.fm_check)
        fm_form.addRow("Mode", self.fm_mode_combo)
        fm_form.addRow("Sensitivity DAC", self.fm_dac)
        fm_form.addRow("", self.fm_slider)
        fm_form.addRow("", labelled_row(self.fm_apply, self.fm_read))
        fm_form.addRow(
            "",
            self._note(
                "With FM on, a frequency change needs 1 ms of settling, and "
                "list and sweep commands cannot be executed at all. This "
                "application enforces both. Input is +/-1 V (2 V p-p) into "
                "50 ohm; adjust the drive amplitude to obtain the deviation "
                "you want at the carrier in use. FM requires option 2."
            ),
        )
        layout.addWidget(fm_box)

        # --- Readback -------------------------------------------------------
        read_box = QtWidgets.QGroupBox("Modulation readback (DIAG:MOD?)")
        read_layout = QtWidgets.QVBoxLayout(read_box)
        self.mod_leds = {
            "pulse": LEDIndicator("Pulse"),
            "am": LEDIndicator("AM"),
            "fm_nb1": LEDIndicator("FM NB1"),
            "fm_nb2": LEDIndicator("FM NB2"),
            "fm_wide": LEDIndicator("FM wide"),
            "phase": LEDIndicator("Phase"),
        }
        led_row = QtWidgets.QHBoxLayout()
        for led in self.mod_leds.values():
            led_row.addWidget(led)
        led_row.addStretch(1)
        read_layout.addLayout(led_row)
        self.mod_refresh = QtWidgets.QPushButton("Refresh modulation status")
        read_layout.addWidget(self.mod_refresh)
        layout.addWidget(read_box)
        layout.addStretch(1)

        self._wire()

    @staticmethod
    def _note(text: str) -> QtWidgets.QLabel:
        """Build a dimmed, wrapped explanatory label."""
        label = QtWidgets.QLabel(text)
        label.setWordWrap(True)
        label.setStyleSheet("color: palette(mid);")
        return label

    def _wire(self) -> None:
        """Connect widget signals to controller actions."""
        c = self.ctl
        self.pulse_check.clicked.connect(
            lambda v: c.guard(lambda: c.driver.set_pulse_modulation(v))
        )
        self.am_check.clicked.connect(
            lambda v: c.guard(lambda: c.driver.set_am(v))
        )
        self.am_slider.valueChanged.connect(self.am_dac.setValue)
        self.am_dac.valueChanged.connect(self.am_slider.setValue)
        self.am_apply.clicked.connect(
            lambda: c.guard(lambda: c.driver.set_am_depth(self.am_dac.value()))
        )
        self.am_read.clicked.connect(
            lambda: c.guard(lambda: self.am_dac.setValue(c.driver.get_am_depth()))
        )
        self.fm_check.clicked.connect(
            lambda v: c.guard(lambda: c.driver.set_fm(v))
        )
        self.fm_mode_combo.activated.connect(
            lambda _: c.guard(
                lambda: c.driver.set_fm_mode(self.fm_mode_combo.currentData())
            )
        )
        self.fm_slider.valueChanged.connect(self.fm_dac.setValue)
        self.fm_dac.valueChanged.connect(self.fm_slider.setValue)
        self.fm_apply.clicked.connect(
            lambda: c.guard(
                lambda: c.driver.set_fm_sensitivity(self.fm_dac.value())
            )
        )
        self.fm_read.clicked.connect(
            lambda: c.guard(
                lambda: self.fm_dac.setValue(c.driver.get_fm_sensitivity())
            )
        )
        self.mod_refresh.clicked.connect(
            lambda: c.guard(
                lambda: self.update_modulation(c.driver.get_modulation_status())
            )
        )

    def update_modulation(self, word: ModulationWord) -> None:
        """Refresh the modulation readback LEDs."""
        mapping = {
            "pulse": (word.pulse, "Pulse"),
            "am": (word.am, "AM"),
            "fm_nb1": (word.fm_nb1, "FM NB1"),
            "fm_nb2": (word.fm_nb2, "FM NB2"),
            "fm_wide": (word.fm_wide, "FM wide"),
            "phase": (word.phase, "Phase"),
        }
        for key, (state, caption) in mapping.items():
            self.mod_leds[key].set_state(True if state else None, caption)


# %% ===========================================================================
#    TAB: SWEEP
# =============================================================================
class SweepTab(QtWidgets.QWidget):
    """Fast and normal frequency and power sweeps."""

    def __init__(
        self, controller: "AppController", parent: QtWidgets.QWidget | None = None
    ) -> None:
        super().__init__(parent)
        self.ctl = controller
        layout = QtWidgets.QVBoxLayout(self)

        self.mode_combo = QtWidgets.QComboBox()
        self.mode_combo.addItem("Frequency sweep - fast mode", "fast_freq")
        self.mode_combo.addItem("Frequency sweep - normal mode", "normal_freq")
        self.mode_combo.addItem("Power sweep - fast mode", "fast_power")
        self.mode_combo.addItem("Power sweep - normal mode", "normal_power")
        layout.addWidget(labelled_row(QtWidgets.QLabel("Sweep type"), self.mode_combo))

        param_box = QtWidgets.QGroupBox("Sweep parameters")
        form = QtWidgets.QFormLayout(param_box)

        self.start_freq = make_double_spin(0.0001, 82.0, 9, 0.001, " GHz", 2.0)
        self.stop_freq = make_double_spin(0.0001, 82.0, 9, 0.001, " GHz", 8.0)
        self.step_freq = make_double_spin(0.000001, 82.0, 9, 0.001, " GHz", 0.1)
        self.start_power = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", -5.0)
        self.stop_power = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", 5.0)
        self.step_power = make_double_spin(0.1, 30.0, 1, 0.1, " dB", 1.0)
        self.fixed_power = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", 0.0)
        self.fixed_freq = make_double_spin(0.0001, 82.0, 9, 0.001, " GHz", 5.0)
        self.points_spin = make_int_spin(1, SWEEP_POINTS_MAX, 101, " points")
        self.dwell_spin = make_int_spin(DWELL_MIN_US, 4_294_967, 50_000, " us")
        self.dwell_spin.setSingleStep(DWELL_INCREMENT_US)
        self.dwell_spin.setToolTip(
            "Quantised to 5 us increments before transmission "
            "[R1, Tables 2b/2c]."
        )
        self.runs_spin = make_int_spin(0, RUN_COUNT_MAX, 1, " runs")
        self.trigger_combo = QtWidgets.QComboBox()
        fill_trigger_combo(self.trigger_combo)
        self.direction_combo = QtWidgets.QComboBox()
        fill_direction_combo(self.direction_combo)
        self.run_now_check = QtWidgets.QCheckBox(
            "Append RUN so the sweep starts on setup"
        )

        self.row_start_freq = form.addRow("Start frequency", self.start_freq)
        form.addRow("Stop frequency", self.stop_freq)
        form.addRow("Step frequency (normal mode)", self.step_freq)
        form.addRow("Start power", self.start_power)
        form.addRow("Stop power", self.stop_power)
        form.addRow("Step power (normal mode)", self.step_power)
        form.addRow("Fixed power (frequency sweep)", self.fixed_power)
        form.addRow("Fixed frequency (power sweep)", self.fixed_freq)
        form.addRow("Points (fast mode)", self.points_spin)
        form.addRow("Dwell per point", self.dwell_spin)
        form.addRow("Number of runs (0 = infinite)", self.runs_spin)
        form.addRow("Trigger", self.trigger_combo)
        form.addRow("Direction", self.direction_combo)
        form.addRow("", self.run_now_check)
        layout.addWidget(param_box)

        button_row = QtWidgets.QHBoxLayout()
        self.setup_button = QtWidgets.QPushButton("Configure sweep")
        self.start_button = QtWidgets.QPushButton("Start sweep")
        self.stop_button = QtWidgets.QPushButton("Stop sweep (SWE:STOP)")
        button_row.addWidget(self.setup_button)
        button_row.addWidget(self.start_button)
        button_row.addWidget(self.stop_button)
        button_row.addStretch(1)
        layout.addLayout(button_row)

        note = QtWidgets.QLabel(
            "Fast mode derives the step from the point count and is capped at "
            "32 000 points; use normal mode beyond that. Fast power sweeps are "
            "capped at 500 points. Sweeps cannot run with FM enabled. Switching "
            "is 1 ms unless option 3 is fitted, which gives 200 us for "
            "individual commands and 100 us in triggered list mode. Multiple "
            "power levels are not allowed in a frequency sweep and multiple "
            "frequencies are not allowed in a power sweep; use list mode to "
            "vary both together."
        )
        note.setWordWrap(True)
        note.setStyleSheet("color: palette(mid);")
        layout.addWidget(note)
        layout.addStretch(1)

        self.mode_combo.currentIndexChanged.connect(self._update_enabled)
        self._power_sweeps_allowed = True
        self.setup_button.clicked.connect(lambda: self.ctl.guard(self._configure))
        self.start_button.clicked.connect(lambda: self.ctl.guard(self._start))
        self.stop_button.clicked.connect(
            lambda: self.ctl.guard(self.ctl.driver.stop_sweep)
        )
        self._update_enabled()

    def set_power_sweeps_allowed(self, allowed: bool, model: str = "") -> None:
        """Enable or disable the two power-sweep types (fixed-output models)."""
        self._power_sweeps_allowed = allowed
        model_items = self.mode_combo.model()
        for index in range(self.mode_combo.count()):
            if self.mode_combo.itemData(index) in ("fast_power", "normal_power"):
                item = model_items.item(index)
                if item is not None:
                    item.setEnabled(allowed)
                    item.setToolTip("" if allowed else f"{model}: fixed output level, no power sweeps")
        if not allowed and self.mode_combo.currentData() in ("fast_power", "normal_power"):
            self.mode_combo.setCurrentIndex(self.mode_combo.findData("fast_freq"))

    def _update_enabled(self) -> None:
        """Grey out parameters that do not apply to the selected sweep."""
        kind = self.mode_combo.currentData()
        is_freq = kind in ("fast_freq", "normal_freq")
        is_fast = kind in ("fast_freq", "fast_power")
        self.start_freq.setEnabled(is_freq)
        self.stop_freq.setEnabled(is_freq)
        self.step_freq.setEnabled(kind == "normal_freq")
        self.fixed_power.setEnabled(is_freq)
        self.start_power.setEnabled(not is_freq)
        self.stop_power.setEnabled(not is_freq)
        self.step_power.setEnabled(kind == "normal_power")
        self.fixed_freq.setEnabled(not is_freq)
        self.points_spin.setEnabled(is_fast)
        self.points_spin.setMaximum(
            SWEEP_POINTS_MAX if kind == "fast_freq" else POWER_SWEEP_POINTS_MAX
        )

    def _configure(self) -> None:
        """Issue the appropriate ``*:SETUP`` command for the selected mode."""
        kind = self.mode_combo.currentData()
        trigger = self.trigger_combo.currentData()
        direction = self.direction_combo.currentData()
        dwell = self.dwell_spin.value()
        runs = self.runs_spin.value()
        run_now = self.run_now_check.isChecked()
        d = self.ctl.driver

        match kind:
            case "fast_freq":
                d.setup_fast_frequency_sweep(
                    self.start_freq.value() * 1e9,
                    self.stop_freq.value() * 1e9,
                    self.points_spin.value(),
                    self.fixed_power.value(),
                    dwell,
                    runs,
                    trigger,
                    direction,
                    run_now,
                )
            case "normal_freq":
                d.setup_normal_frequency_sweep(
                    self.start_freq.value() * 1e9,
                    self.stop_freq.value() * 1e9,
                    self.step_freq.value() * 1e9,
                    self.fixed_power.value(),
                    dwell,
                    runs,
                    trigger,
                    direction,
                    run_now,
                )
            case "fast_power":
                d.setup_fast_power_sweep(
                    self.start_power.value(),
                    self.stop_power.value(),
                    self.points_spin.value(),
                    self.fixed_freq.value() * 1e9,
                    dwell,
                    runs,
                    trigger,
                    direction,
                    run_now,
                )
            case "normal_power":
                d.setup_normal_power_sweep(
                    self.start_power.value(),
                    self.stop_power.value(),
                    self.step_power.value(),
                    self.fixed_freq.value() * 1e9,
                    dwell,
                    runs,
                    trigger,
                    direction,
                    run_now,
                )
        self.ctl.status_message(f"{kind} sweep configured.")

    def _start(self) -> None:
        """Issue the matching ``*:STAR`` command."""
        self.ctl.driver.start_sweep(
            self.mode_combo.currentData(), self.runs_spin.value()
        )


# %% ===========================================================================
#    TAB: LIST MODE
# =============================================================================
class ListModeTab(QtWidgets.QWidget):
    """Editable list-point table with RAM-only or flash storage."""

    COLUMNS = ["Point", "Frequency (GHz)", "Power (dBm)", "Dwell (us)",
               "Pulse mod", "RF output"]

    def __init__(
        self, controller: "AppController", parent: QtWidgets.QWidget | None = None
    ) -> None:
        super().__init__(parent)
        self.ctl = controller
        layout = QtWidgets.QVBoxLayout(self)

        # --- Generator ------------------------------------------------------
        gen_box = QtWidgets.QGroupBox("Generate a point table")
        gen_form = QtWidgets.QFormLayout(gen_box)
        self.gen_start_f = make_double_spin(0.0001, 82.0, 6, 0.001, " GHz", 2.0)
        self.gen_stop_f = make_double_spin(0.0001, 82.0, 6, 0.001, " GHz", 8.0)
        self.gen_start_p = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", 0.0)
        self.gen_stop_p = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", 0.0)
        self.gen_points = make_int_spin(1, 2000, 11, " points")
        self.gen_dwell = make_int_spin(DWELL_MIN_US, 4_294_967, 50_000, " us")
        self.gen_dwell.setSingleStep(DWELL_INCREMENT_US)
        self.gen_button = QtWidgets.QPushButton("Generate")
        gen_form.addRow("Start frequency", self.gen_start_f)
        gen_form.addRow("Stop frequency", self.gen_stop_f)
        gen_form.addRow("Start power", self.gen_start_p)
        gen_form.addRow("Stop power", self.gen_stop_p)
        gen_form.addRow("Points", self.gen_points)
        gen_form.addRow("Dwell", self.gen_dwell)
        gen_form.addRow("", self.gen_button)
        layout.addWidget(gen_box)

        # --- Table ----------------------------------------------------------
        self.table = QtWidgets.QTableWidget(0, len(self.COLUMNS))
        self.table.setHorizontalHeaderLabels(self.COLUMNS)
        self.table.horizontalHeader().setStretchLastSection(True)
        layout.addWidget(self.table, 1)

        table_buttons = QtWidgets.QHBoxLayout()
        self.add_row_button = QtWidgets.QPushButton("Add row")
        self.del_row_button = QtWidgets.QPushButton("Delete selected")
        self.clear_button = QtWidgets.QPushButton("Clear table")
        self.import_button = QtWidgets.QPushButton("Import CSV")
        self.export_button = QtWidgets.QPushButton("Export CSV")
        for button in (
            self.add_row_button,
            self.del_row_button,
            self.clear_button,
            self.import_button,
            self.export_button,
        ):
            table_buttons.addWidget(button)
        table_buttons.addStretch(1)
        layout.addLayout(table_buttons)

        # --- Download and run -----------------------------------------------
        run_box = QtWidgets.QGroupBox("Download and run")
        run_form = QtWidgets.QFormLayout(run_box)
        self.flash_check = QtWidgets.QCheckBox(
            "Write points to flash (slow, consumes non-volatile user memory)"
        )
        self.global_dwell = make_int_spin(0, 4_294_967, 0, " us")
        self.global_dwell.setSingleStep(DWELL_INCREMENT_US)
        self.global_dwell.setToolTip(
            "0 means use each point's own dwell time [R1, Table 2b]. "
            "Non-zero values are quantised to 5 us."
        )
        self.run_count = make_int_spin(0, RUN_COUNT_MAX, 1, " runs")
        self.list_trigger = QtWidgets.QComboBox()
        fill_trigger_combo(self.list_trigger)
        self.list_direction = QtWidgets.QComboBox()
        fill_direction_combo(self.list_direction)
        self.download_button = QtWidgets.QPushButton("Erase and download list")
        self.setup_run_button = QtWidgets.QPushButton("Set up and run list")
        self.stop_list_button = QtWidgets.QPushButton("Stop list")
        self.goto_point = make_int_spin(1, LIST_POINT_MAX, 1, "")
        self.goto_button = QtWidgets.QPushButton("Go to point")
        run_form.addRow("", self.flash_check)
        run_form.addRow("Global dwell (0 = per point)", self.global_dwell)
        run_form.addRow("Number of runs (0 = infinite)", self.run_count)
        run_form.addRow("Trigger", self.list_trigger)
        run_form.addRow("Direction", self.list_direction)
        run_form.addRow(
            "",
            labelled_row(
                self.download_button, self.setup_run_button, self.stop_list_button
            ),
        )
        run_form.addRow("Single point", labelled_row(self.goto_point, self.goto_button))
        layout.addWidget(run_box)

        self.progress = QtWidgets.QProgressBar()
        self.progress.setVisible(False)
        layout.addWidget(self.progress)

        note = QtWidgets.QLabel(
            "The command set addresses up to 32 767 list points while the "
            "datasheet specifies 32 000; either way each point carries "
            "independent frequency, power, dwell, RF mute and pulse "
            "modulation. RAM-only "
            "download is the recommended default: it is roughly 3000 times "
            "faster per point than a flash write and the points vanish on power "
            "cycle, so no non-volatile user memory is consumed. Lists cannot be "
            "run with FM enabled. After leaving list mode, reset and re-enable "
            "the RF output to return to normal operation."
        )
        note.setWordWrap(True)
        note.setStyleSheet("color: palette(mid);")
        layout.addWidget(note)

        self._wire()
        self._generate()

    def _wire(self) -> None:
        """Connect widget signals."""
        c = self.ctl
        self.gen_button.clicked.connect(self._generate)
        self.add_row_button.clicked.connect(lambda: self._append_row(
            self.table.rowCount() + 1, 5.0, 0.0, 50_000, False, True
        ))
        self.del_row_button.clicked.connect(self._delete_selected)
        self.clear_button.clicked.connect(lambda: self.table.setRowCount(0))
        self.import_button.clicked.connect(self._import_csv)
        self.export_button.clicked.connect(self._export_csv)
        self.download_button.clicked.connect(lambda: c.guard(self._download))
        self.setup_run_button.clicked.connect(lambda: c.guard(self._setup_and_run))
        self.stop_list_button.clicked.connect(
            lambda: c.guard(c.driver.stop_list)
        )
        self.goto_button.clicked.connect(
            lambda: c.guard(
                lambda: c.driver.run_list_point(self.goto_point.value())
            )
        )

    # --- Table helpers ------------------------------------------------------
    def _append_row(
        self,
        index: int,
        freq_ghz: float,
        power_dbm: float,
        dwell_us: int,
        pulse: bool,
        rf_on: bool,
    ) -> None:
        """Append one editable row to the point table."""
        row = self.table.rowCount()
        self.table.insertRow(row)
        values = [
            str(index),
            f"{freq_ghz:.6f}",
            f"{power_dbm:.1f}",
            str(dwell_us),
        ]
        for column, text in enumerate(values):
            self.table.setItem(row, column, QtWidgets.QTableWidgetItem(text))
        for column, state in ((4, pulse), (5, rf_on)):
            item = QtWidgets.QTableWidgetItem()
            item.setFlags(
                QtCore.Qt.ItemFlag.ItemIsUserCheckable
                | QtCore.Qt.ItemFlag.ItemIsEnabled
            )
            item.setCheckState(
                QtCore.Qt.CheckState.Checked if state
                else QtCore.Qt.CheckState.Unchecked
            )
            self.table.setItem(row, column, item)

    def _generate(self) -> None:
        """Fill the table with a linear frequency and power ramp."""
        self.table.setRowCount(0)
        n = self.gen_points.value()
        f0, f1 = self.gen_start_f.value(), self.gen_stop_f.value()
        p0, p1 = self.gen_start_p.value(), self.gen_stop_p.value()
        dwell = self.gen_dwell.value()
        freqs = np.linspace(f0, f1, n) if n > 1 else np.array([f0])
        powers = np.linspace(p0, p1, n) if n > 1 else np.array([p0])
        for i in range(n):
            self._append_row(i + 1, float(freqs[i]), float(powers[i]), dwell,
                             False, True)

    def _delete_selected(self) -> None:
        """Remove the selected rows and renumber the remainder."""
        rows = sorted({idx.row() for idx in self.table.selectedIndexes()},
                      reverse=True)
        for row in rows:
            self.table.removeRow(row)
        for row in range(self.table.rowCount()):
            self.table.item(row, 0).setText(str(row + 1))

    def collect_points(self) -> list[ListPoint]:
        """Read the table into a list of :class:`ListPoint` records."""
        points: list[ListPoint] = []
        flash = self.flash_check.isChecked()
        for row in range(self.table.rowCount()):
            try:
                index = int(self.table.item(row, 0).text())
                freq_ghz = float(self.table.item(row, 1).text())
                power = float(self.table.item(row, 2).text())
                dwell = int(float(self.table.item(row, 3).text()))
            except (AttributeError, ValueError) as exc:
                raise ParameterError(f"Row {row + 1} is not valid: {exc}") from exc
            pulse = (
                self.table.item(row, 4).checkState()
                == QtCore.Qt.CheckState.Checked
            )
            rf_on = (
                self.table.item(row, 5).checkState()
                == QtCore.Qt.CheckState.Checked
            )
            points.append(
                ListPoint(
                    index=index,
                    freq_hz=freq_ghz * 1e9,
                    power_dbm=power,
                    dwell_us=dwell,
                    pulse_mod=pulse,
                    rf_output=rf_on,
                    save_to_flash=flash,
                )
            )
        return points

    def _import_csv(self) -> None:
        """Load a point table from CSV."""
        path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, "Import list points", "", "CSV files (*.csv);;All files (*)"
        )
        if not path:
            return
        self.table.setRowCount(0)
        with open(path, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                self._append_row(
                    int(row.get("point", self.table.rowCount() + 1)),
                    float(row.get("freq_ghz", 0.0)),
                    float(row.get("power_dbm", 0.0)),
                    int(float(row.get("dwell_us", 50_000))),
                    str(row.get("pulse_mod", "0")).strip() in {"1", "True", "true"},
                    str(row.get("rf_output", "1")).strip() in {"1", "True", "true"},
                )

    def _export_csv(self) -> None:
        """Save the point table to CSV."""
        path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, "Export list points", "list_points.csv",
            "CSV files (*.csv);;All files (*)"
        )
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerow(
                ["point", "freq_ghz", "power_dbm", "dwell_us",
                 "pulse_mod", "rf_output"]
            )
            for point in self.collect_points():
                writer.writerow(
                    [
                        point.index,
                        f"{point.freq_hz / 1e9:.9f}",
                        f"{point.power_dbm:.1f}",
                        point.dwell_us,
                        int(point.pulse_mod),
                        int(point.rf_output),
                    ]
                )

    # --- Device operations --------------------------------------------------
    def _download(self) -> None:
        """Erase the list and download every point in the table."""
        points = self.collect_points()
        if not points:
            raise ParameterError("The point table is empty.")
        flash = self.flash_check.isChecked()
        if flash:
            answer = QtWidgets.QMessageBox.question(
                self,
                "Write to flash?",
                f"Writing {len(points)} points to flash takes about "
                f"{len(points) * WAIT_LIST_POINT_FLASH_S:.0f} s and consumes "
                f"non-volatile user memory. RAM-only download is the "
                f"recommended default. Continue?",
            )
            if answer != QtWidgets.QMessageBox.StandardButton.Yes:
                return

        self.progress.setVisible(True)
        self.progress.setRange(0, len(points))
        self.ctl.driver.erase_list()
        for n, point in enumerate(points, start=1):
            self.ctl.driver.write_list_point(point)
            self.progress.setValue(n)
            QtWidgets.QApplication.processEvents()
        if flash:
            self.ctl.driver.save_list(len(points))
        self.progress.setVisible(False)
        self.ctl.status_message(
            f"Downloaded {len(points)} list points "
            f"({'flash' if flash else 'RAM only'})."
        )

    def _setup_and_run(self) -> None:
        """Configure traversal and start it."""
        self.ctl.driver.setup_list(
            dwell_us=self.global_dwell.value(),
            run_count=self.run_count.value(),
            trigger=self.list_trigger.currentData(),
            direction=self.list_direction.currentData(),
            run_now=True,
        )
        self.ctl.status_message("List running.")


# %% ===========================================================================
#    TAB: MONITOR AND LOGGING
# =============================================================================
class MonitorTab(QtWidgets.QWidget):
    """Sample-rate control, live strip chart, buffer accounting and files."""

    def __init__(
        self, controller: "AppController", parent: QtWidgets.QWidget | None = None
    ) -> None:
        super().__init__(parent)
        self.ctl = controller
        layout = QtWidgets.QVBoxLayout(self)

        # --- Acquisition controls -------------------------------------------
        acq_box = QtWidgets.QGroupBox("Acquisition")
        acq_form = QtWidgets.QFormLayout(acq_box)

        self.rate_spin = make_double_spin(
            MIN_SAMPLE_RATE_HZ, MAX_SAMPLE_RATE_HZ, 3, 0.1, " Hz",
            DEFAULT_SAMPLE_RATE_HZ
        )
        self.rate_spin.setToolTip(
            "Requested telemetry sample rate. Each enabled field costs one "
            "serial round trip, so the achievable rate falls as you enable "
            "more fields."
        )
        acq_form.addRow("Sample rate", self.rate_spin)

        self.chk_freq = QtWidgets.QCheckBox("Frequency (FREQ?)")
        self.chk_power = QtWidgets.QCheckBox("Power (POW?)")
        self.chk_status = QtWidgets.QCheckBox("Status (STAT?)")
        self.chk_mod = QtWidgets.QCheckBox("Modulation (DIAG:MOD?)")
        self.chk_temp = QtWidgets.QCheckBox("Temperature (DIAG:MEAS? 21)")
        for box, default in (
            (self.chk_freq, True),
            (self.chk_power, True),
            (self.chk_status, True),
            (self.chk_mod, False),
            (self.chk_temp, True),
        ):
            box.setChecked(default)
        fields = QtWidgets.QWidget()
        fields_layout = QtWidgets.QGridLayout(fields)
        fields_layout.setContentsMargins(0, 0, 0, 0)
        for i, box in enumerate(
            (self.chk_freq, self.chk_power, self.chk_status,
             self.chk_mod, self.chk_temp)
        ):
            fields_layout.addWidget(box, i // 3, i % 3)
        acq_form.addRow("Polled fields", fields)

        self.temp_decim = make_int_spin(1, 1000, 5, "")
        self.temp_decim.setToolTip(
            "Poll temperature on every Nth sample. Temperature moves slowly, "
            "so decimating it buys back serial bandwidth."
        )
        acq_form.addRow("Temperature decimation (every Nth)", self.temp_decim)

        self.budget_label = QtWidgets.QLabel("-")
        self.budget_label.setWordWrap(True)
        acq_form.addRow("Rate budget", self.budget_label)

        self.ring_spin = make_int_spin(1000, 5_000_000, DEFAULT_RING_CAPACITY,
                                       " records")
        acq_form.addRow("Ring buffer capacity", self.ring_spin)

        self.logdir_edit = QtWidgets.QLineEdit(str(Path.home() / "quicksyn_logs"))
        self.logdir_button = QtWidgets.QPushButton("Browse")
        acq_form.addRow(
            "Log root", labelled_row(self.logdir_edit, self.logdir_button)
        )

        self.start_button = QtWidgets.QPushButton("Start logging")
        self.stop_button = QtWidgets.QPushButton("Stop logging")
        self.stop_button.setEnabled(False)
        self.flush_button = QtWidgets.QPushButton("Flush RAM to disk now")
        self.open_dir_button = QtWidgets.QPushButton("Open session folder")
        acq_form.addRow(
            "",
            labelled_row(
                self.start_button, self.stop_button,
                self.flush_button, self.open_dir_button
            ),
        )
        layout.addWidget(acq_box)

        # --- Veusz document (.vszh5) ----------------------------------------
        vz_box = QtWidgets.QGroupBox("Veusz document (.vszh5)")
        vz_form = QtWidgets.QFormLayout(vz_box)
        self.chk_vszh5_stop = QtWidgets.QCheckBox("Write when logging stops")
        self.chk_vszh5_stop.setChecked(True)
        self.chk_vszh5_render = QtWidgets.QCheckBox("Also render PDF/PNG with Veusz")
        self.chk_vszh5_render.setToolTip(
            "Renders every page to one PDF and the overview to PNG by driving "
            "the installed Veusz program. The .vszh5 itself never needs Veusz."
        )
        self.vszh5_refresh = make_int_spin(0, 1440, 0, " min")
        self.vszh5_refresh.setSpecialValueText("off")
        self.vszh5_refresh.setToolTip(
            "Rewrite the .vszh5 every N minutes while logging (0 = off). The "
            "file is replaced atomically, so Veusz never sees half of one."
        )
        self.vszh5_axis = QtWidgets.QComboBox()
        self.vszh5_axis.addItem("Local time", "local")
        self.vszh5_axis.addItem("UTC", "utc")
        self.vszh5_axis.addItem("Elapsed seconds", "elapsed")
        exe = vszh5_writer.find_veusz_exe() if HAVE_VSZH5_WRITER else ""
        self.veusz_label = QtWidgets.QLabel(
            f"Veusz program: {exe}" if exe else
            "Veusz program not found (set QUICKSYN_VEUSZ to veusz.exe). The "
            ".vszh5 is still written; Veusz is only needed to view or render it."
        )
        self.veusz_label.setWordWrap(True)
        self.vszh5_write_button = QtWidgets.QPushButton("Write .vszh5 now")
        self.vszh5_open_button = QtWidgets.QPushButton("Open in Veusz")
        vz_form.addRow("", labelled_row(self.chk_vszh5_stop, self.chk_vszh5_render))
        vz_form.addRow("Refresh while logging", self.vszh5_refresh)
        vz_form.addRow("Time axis", self.vszh5_axis)
        vz_form.addRow("", labelled_row(self.vszh5_write_button, self.vszh5_open_button))
        vz_form.addRow("", self.veusz_label)
        layout.addWidget(vz_box)

        # --- Live statistics ------------------------------------------------
        stats_box = QtWidgets.QGroupBox("Live statistics")
        stats_grid = QtWidgets.QGridLayout(stats_box)
        self.stat_labels: dict[str, QtWidgets.QLabel] = {}
        entries = [
            ("samples", "Samples acquired"),
            ("achieved", "Achieved rate"),
            ("duty", "Serial duty cycle"),
            ("latency", "Last poll latency"),
            ("ring", "Ring buffer fill"),
            ("ram", "Buffer RAM"),
            ("rss", "Process RSS"),
            ("chunks", "Spill chunks"),
            ("rows", "CSV rows written"),
            ("queue", "Writer queue depth"),
            ("freq", "Last frequency"),
            ("power", "Last power"),
            ("temp", "Last temperature"),
            ("errors", "Sampler errors"),
        ]
        for i, (key, caption) in enumerate(entries):
            stats_grid.addWidget(QtWidgets.QLabel(f"{caption}:"), i // 2, (i % 2) * 2)
            value = QtWidgets.QLabel("-")
            value.setStyleSheet("font-family: monospace;")
            self.stat_labels[key] = value
            stats_grid.addWidget(value, i // 2, (i % 2) * 2 + 1)
        layout.addWidget(stats_box)

        # --- Live plot ------------------------------------------------------
        plot_box = QtWidgets.QGroupBox("Live strip chart")
        plot_layout = QtWidgets.QVBoxLayout(plot_box)
        if HAVE_PYQTGRAPH:
            self.plot_widget = pg.GraphicsLayoutWidget()
            self.plot_freq = self.plot_widget.addPlot(row=0, col=0)
            self.plot_freq.setLabel("left", "Frequency", units="Hz")
            self.plot_freq.showGrid(x=True, y=True, alpha=0.3)
            self.curve_freq = self.plot_freq.plot(pen=pg.mkPen(width=1.5))

            self.plot_power = self.plot_widget.addPlot(row=1, col=0)
            self.plot_power.setLabel("left", "Power", units="dBm")
            self.plot_power.setXLink(self.plot_freq)
            self.plot_power.showGrid(x=True, y=True, alpha=0.3)
            self.curve_power = self.plot_power.plot(pen=pg.mkPen(width=1.5))

            self.plot_temp = self.plot_widget.addPlot(row=2, col=0)
            self.plot_temp.setLabel("left", "Temperature", units="degC")
            self.plot_temp.setLabel("bottom", "Elapsed time", units="s")
            self.plot_temp.setXLink(self.plot_freq)
            self.plot_temp.showGrid(x=True, y=True, alpha=0.3)
            self.curve_temp = self.plot_temp.plot(pen=pg.mkPen(width=1.5))
            plot_layout.addWidget(self.plot_widget)
        else:
            placeholder = QtWidgets.QLabel(
                "pyqtgraph is not installed, so the live chart is disabled. "
                "Logging and control are unaffected. Install it with "
                "'mamba install -c conda-forge pyqtgraph'."
            )
            placeholder.setWordWrap(True)
            plot_layout.addWidget(placeholder)
        layout.addWidget(plot_box, 1)

        self._wire()
        self._update_budget()

    def _wire(self) -> None:
        """Connect widget signals."""
        self.logdir_button.clicked.connect(self._pick_logdir)
        self.start_button.clicked.connect(self.ctl.start_logging)
        self.stop_button.clicked.connect(self.ctl.stop_logging)
        self.flush_button.clicked.connect(self.ctl.flush_ram)
        self.open_dir_button.clicked.connect(self._open_session_dir)
        self.vszh5_write_button.clicked.connect(
            lambda: self.ctl.export_vszh5(render=self.chk_vszh5_render.isChecked())
        )
        self.vszh5_open_button.clicked.connect(self.ctl.open_in_veusz)
        for widget in (
            self.chk_freq, self.chk_power, self.chk_status,
            self.chk_mod, self.chk_temp,
        ):
            widget.toggled.connect(self._update_budget)
        self.rate_spin.valueChanged.connect(self._update_budget)
        self.temp_decim.valueChanged.connect(self._update_budget)
        self.ring_spin.valueChanged.connect(self._update_budget)

    def _pick_logdir(self) -> None:
        """Choose the log root directory."""
        path = QtWidgets.QFileDialog.getExistingDirectory(
            self, "Choose a log root directory", self.logdir_edit.text()
        )
        if path:
            self.logdir_edit.setText(path)

    def _open_session_dir(self) -> None:
        """Reveal the current session folder in the desktop file manager."""
        session = self.ctl.session
        if session is None:
            self.ctl.status_message("No session is open.")
            return
        QtGui.QDesktopServices.openUrl(
            QtCore.QUrl.fromLocalFile(str(session.directory))
        )

    def config(self) -> SamplerConfig:
        """Build a :class:`SamplerConfig` from the current widget state."""
        return SamplerConfig(
            rate_hz=self.rate_spin.value(),
            poll_frequency=self.chk_freq.isChecked(),
            poll_power=self.chk_power.isChecked(),
            poll_status=self.chk_status.isChecked(),
            poll_modulation=self.chk_mod.isChecked(),
            poll_temperature=self.chk_temp.isChecked(),
            temperature_decimation=self.temp_decim.value(),
        )

    def _update_budget(self) -> None:
        """Estimate whether the requested rate is achievable and show RAM use.

        The estimate assumes a round trip of roughly 8 ms per query, which is
        a conservative figure for a 115.2 kbaud USB-CDC bridge once host
        scheduling and firmware turnaround are included. It is an estimate
        only; the achieved rate reported during acquisition is measured.
        """
        cfg = self.config()
        queries = cfg.queries_per_sample(include_temperature=True)
        queries_decimated = cfg.queries_per_sample(include_temperature=False) + (
            (2 if TEMPERATURE_DOUBLE_QUERY else 1) / max(cfg.temperature_decimation, 1)
            if cfg.poll_temperature else 0.0
        )
        per_query_s = 0.008
        worst_s = queries * per_query_s
        mean_s = queries_decimated * per_query_s
        ceiling_hz = 1.0 / mean_s if mean_s > 0 else float("inf")

        ram_bytes = self.ring_spin.value() * TELEMETRY_DTYPE.itemsize
        span_s = self.ring_spin.value() / max(cfg.rate_hz, MIN_SAMPLE_RATE_HZ)

        verdict = (
            "requested rate looks achievable"
            if cfg.rate_hz <= ceiling_hz
            else "REQUESTED RATE EXCEEDS THE ESTIMATED CEILING; samples will "
                 "overrun their slots"
        )
        self.budget_label.setText(
            f"{queries} queries on a full sample, "
            f"{queries_decimated:.2f} on average with decimation. "
            f"Estimated ceiling about {ceiling_hz:.1f} Hz "
            f"(worst-case sample {worst_s * 1e3:.0f} ms); {verdict}. "
            f"Ring buffer holds {ram_bytes / 1e6:.1f} MB "
            f"= {span_s / 60.0:.1f} minutes at this rate before spilling."
        )

    def set_running(self, running: bool) -> None:
        """Enable or disable controls according to acquisition state."""
        self.start_button.setEnabled(not running)
        self.stop_button.setEnabled(running)
        for widget in (
            self.rate_spin, self.chk_freq, self.chk_power, self.chk_status,
            self.chk_mod, self.chk_temp, self.temp_decim, self.ring_spin,
            self.logdir_edit, self.logdir_button,
        ):
            widget.setEnabled(not running)

    def set_stat(self, key: str, text: str) -> None:
        """Update one live-statistics field."""
        if key in self.stat_labels:
            self.stat_labels[key].setText(text)

    def update_plot(self, block: np.ndarray) -> None:
        """Redraw the strip chart from a block of resident records."""
        if not HAVE_PYQTGRAPH or block.size == 0:
            return
        t = block["t_mono"]
        self.curve_freq.setData(t, block["freq_hz"])
        self.curve_power.setData(t, block["power_dbm"].astype(np.float64))
        self.curve_temp.setData(t, block["temp_c"].astype(np.float64))


# %% ===========================================================================
#    TAB: MEMORY HYGIENE
# =============================================================================
class MemoryTab(QtWidgets.QWidget):
    """Implements the vendor's recommended memory-clearing procedure [R5]."""

    def __init__(
        self, controller: "AppController", parent: QtWidgets.QWidget | None = None
    ) -> None:
        super().__init__(parent)
        self.ctl = controller
        layout = QtWidgets.QVBoxLayout(self)

        intro = QtWidgets.QLabel(
            "The module holds 2112 bytes and 16 MB of volatile SRAM plus 8 MB "
            "of non-volatile flash. The SRAM clears on a power cycle. The two "
            "user-writable flash areas - the instrument states and the list "
            "point table - have no direct erase command, so the only way to "
            "clear them is to overwrite them with benign values using the same "
            "commands that wrote them."
        )
        intro.setWordWrap(True)
        layout.addWidget(intro)

        state_box = QtWidgets.QGroupBox("Instrument state memory")
        state_layout = QtWidgets.QVBoxLayout(state_box)
        state_layout.addWidget(
            QtWidgets.QLabel(
                "Recalls the factory default state, then overwrites user "
                "states 1 and 2 with it."
            )
        )
        self.clear_states_button = QtWidgets.QPushButton(
            "Clear both user instrument states"
        )
        state_layout.addWidget(self.clear_states_button)
        layout.addWidget(state_box)

        list_box = QtWidgets.QGroupBox("List mode memory")
        list_form = QtWidgets.QFormLayout(list_box)
        self.safe_freq = make_double_spin(0.0001, 82.0, 6, 0.001, " GHz", 10.0)
        self.safe_power = make_double_spin(-30.0, 30.0, 1, 0.1, " dBm", -25.0)
        self.points_to_clear = make_int_spin(1, LIST_POINT_MAX, 100, " points")
        self.clear_list_button = QtWidgets.QPushButton("Overwrite list points")
        self.abort_button = QtWidgets.QPushButton("Abort")
        self.abort_button.setEnabled(False)
        self.clear_progress = QtWidgets.QProgressBar()
        self.eta_label = QtWidgets.QLabel("-")
        list_form.addRow("Safe frequency", self.safe_freq)
        list_form.addRow("Safe power", self.safe_power)
        list_form.addRow("Points to overwrite", self.points_to_clear)
        list_form.addRow("Estimated duration", self.eta_label)
        list_form.addRow(
            "", labelled_row(self.clear_list_button, self.abort_button)
        )
        list_form.addRow("", self.clear_progress)
        layout.addWidget(list_box)

        advice = QtWidgets.QLabel(
            "Avoiding the problem is cheaper than solving it. Do not store "
            "instrument states you do not need, and download list points to "
            "RAM only rather than flash, which is this application's default. "
            "A list set up in volatile memory runs normally and clears itself "
            "on the next power cycle."
        )
        advice.setWordWrap(True)
        advice.setStyleSheet("color: palette(mid);")
        layout.addWidget(advice)
        layout.addStretch(1)

        self._abort = False
        self.clear_states_button.clicked.connect(
            lambda: self.ctl.guard(self._clear_states)
        )
        self.clear_list_button.clicked.connect(
            lambda: self.ctl.guard(self._clear_list)
        )
        self.abort_button.clicked.connect(self._request_abort)
        self.points_to_clear.valueChanged.connect(self._update_eta)
        self._update_eta()

    def _update_eta(self) -> None:
        """Show how long the overwrite will take at 300 ms per flash point."""
        seconds = self.points_to_clear.value() * WAIT_LIST_POINT_FLASH_S
        self.eta_label.setText(
            f"about {seconds / 60.0:.1f} minutes "
            f"({seconds:.0f} s at 300 ms per flash write). "
            f"All {LIST_POINT_MAX} locations would take "
            f"{LIST_POINT_MAX * WAIT_LIST_POINT_FLASH_S / 3600.0:.1f} hours."
        )

    def _request_abort(self) -> None:
        """Flag the running overwrite loop to stop at the next point."""
        self._abort = True

    def _clear_states(self) -> None:
        """Run the two-step instrument-state clearing procedure."""
        answer = QtWidgets.QMessageBox.question(
            self,
            "Clear instrument states?",
            "This overwrites user states 1 and 2 with the factory default "
            "state. Any saved setup in those slots is lost. Continue?",
        )
        if answer != QtWidgets.QMessageBox.StandardButton.Yes:
            return
        self.ctl.driver.clear_instrument_states()
        self.ctl.status_message("User instrument states cleared.")

    def _clear_list(self) -> None:
        """Overwrite list-point flash locations with safe values."""
        count = self.points_to_clear.value()
        answer = QtWidgets.QMessageBox.question(
            self,
            "Overwrite list memory?",
            f"This writes {count} list points to flash with "
            f"{self.safe_freq.value():.3f} GHz at "
            f"{self.safe_power.value():+.1f} dBm and RF output off. It takes "
            f"about {count * WAIT_LIST_POINT_FLASH_S / 60.0:.1f} minutes and "
            f"cannot be undone. Continue?",
        )
        if answer != QtWidgets.QMessageBox.StandardButton.Yes:
            return

        self._abort = False
        self.abort_button.setEnabled(True)
        self.clear_list_button.setEnabled(False)
        self.clear_progress.setRange(0, count)

        def progress(done: int, total: int) -> bool:
            """Update the bar and report whether to keep going."""
            self.clear_progress.setValue(done)
            QtWidgets.QApplication.processEvents()
            return not self._abort

        try:
            written = self.ctl.driver.clear_list_memory(
                n_points=count,
                safe_freq_hz=self.safe_freq.value() * 1e9,
                safe_power_dbm=self.safe_power.value(),
                progress=progress,
            )
        finally:
            self.abort_button.setEnabled(False)
            self.clear_list_button.setEnabled(True)
        self.ctl.status_message(
            f"Overwrote {written} list point locations"
            + (" (aborted early)." if self._abort else ".")
        )


# %% ===========================================================================
#    TAB: CALIBRATION (PROGRAM-SIDE)
# =============================================================================
class CalibrationTab(QtWidgets.QWidget):
    """Power and reference calibration without NI's GPIB-only panel (0.0.10).

    Readings are typed in or read from any SCPI meter through PyVISA. The
    results are kept in this program per unit (see the CALIBRATION cell):
    nothing undocumented is written to the synthesizer.
    """

    POWER_COLUMNS = ("#", "Frequency (GHz)", "Set (dBm)", "Meter (dBm)", "Path loss (dB)",
                     "At RF OUT (dBm)", "Error (dB)", "Source")
    REF_COLUMNS = ("#", "DAC", "Measured (Hz)", "Error (Hz)", "Error (ppb)", "Source")

    def __init__(self, controller: "AppController",
                 parent: QtWidgets.QWidget | None = None) -> None:
        super().__init__(parent)
        self.ctl = controller
        self.store = CalStore()
        self.table = PowerCalTable()                 # being measured or loaded
        self.active_table: PowerCalTable | None = None
        self.path = PathLoss()
        self.plan: list[tuple[float, float | None]] = []
        self.plan_index = 0
        self.tuner: RefCalTuner | None = None
        self.ref_record: RefCalRecord | None = None
        self.readers: dict[str, InstrumentReader] = {}
        self._auto_running = False
        self.power_meter_cfg = MeterConfig(query="MEAS?", pre_command="SENS:FREQ {freq_hz:.0f}")
        self.counter_cfg = MeterConfig(query="MEAS:FREQ?")

        outer = QtWidgets.QVBoxLayout(self)
        intro = QtWidgets.QLabel(
            "Calibration kept in this program, per unit (model and serial), under "
            f"{html.escape(str(self.store.root))}. Power: measured level at RF OUT against frequency, "
            "used for the expected-output readout and, on power-control models, to correct the "
            "commanded level. Reference: OCXO tuning with the documented DIAG:CAL:REF:DAC. "
            "Power tables are <b>not</b> written into the synthesizer: the commands NI's panel "
            "uses for that are not published [R1], [R3].")
        intro.setWordWrap(True)
        outer.addWidget(intro)
        self.subtabs = QtWidgets.QTabWidget()
        outer.addWidget(self.subtabs, 1)
        self.subtabs.addTab(self._build_power(), "Power vs frequency")
        self.subtabs.addTab(self._build_reference(), "Reference (10 MHz OCXO)")
        self.subtabs.addTab(self._build_meters(), "Meters (optional, PyVISA)")
        self._refresh_power_view()
        self._refresh_ref_view()

    # ------------------------------------------------------------------ power
    def _build_power(self) -> QtWidgets.QWidget:
        page = QtWidgets.QWidget()
        layout = QtWidgets.QHBoxLayout(page)
        left = QtWidgets.QVBoxLayout()

        plan_box = QtWidgets.QGroupBox("Points")
        plan_form = QtWidgets.QFormLayout(plan_box)
        self.start_f = make_double_spin(0.0, 100.0, 6, 0.1, " GHz", 1.0)
        self.stop_f = make_double_spin(0.0, 100.0, 6, 0.1, " GHz", 20.0)
        self.step_f = make_double_spin(0.000001, 100.0, 6, 0.1, " GHz", 1.0)
        self.levels_edit = QtWidgets.QLineEdit("")
        self.levels_edit.setPlaceholderText("power-control models: e.g. -10, 0, 13 (dBm)")
        self.settle_spin = make_double_spin(0.0, 60.0, 1, 0.5, " s", 1.0)
        self.generate_button = QtWidgets.QPushButton("Make point list")
        self.plan_label = QtWidgets.QLabel("No points yet.")
        self.plan_label.setWordWrap(True)
        plan_form.addRow("Start", self.start_f)
        plan_form.addRow("Stop", self.stop_f)
        plan_form.addRow("Step", self.step_f)
        plan_form.addRow("Levels", self.levels_edit)
        plan_form.addRow("Settle before reading", self.settle_spin)
        plan_form.addRow("", self.generate_button)
        plan_form.addRow(self.plan_label)
        left.addWidget(plan_box)

        path_box = QtWidgets.QGroupBox("Path loss (cable, adapters, pad) between RF OUT and meter")
        path_form = QtWidgets.QFormLayout(path_box)
        self.path_combo = QtWidgets.QComboBox()
        for label, key in (("None", "none"), ("Constant", "constant"),
                           ("CSV table (frequency, loss dB)", "csv"),
                           ("Touchstone .s2p (|S21|)", "s2p")):
            self.path_combo.addItem(label, key)
        self.path_const = make_double_spin(-10.0, 60.0, 3, 0.1, " dB", 0.0)
        self.path_file_button = QtWidgets.QPushButton("Load file...")
        self.path_label = QtWidgets.QLabel(self.path.describe())
        self.path_label.setWordWrap(True)
        path_form.addRow("Correction", self.path_combo)
        path_form.addRow("Constant loss", self.path_const)
        path_form.addRow("", self.path_file_button)
        path_form.addRow(self.path_label)
        left.addWidget(path_box)

        meas_box = QtWidgets.QGroupBox("Measure")
        meas_form = QtWidgets.QFormLayout(meas_box)
        self.point_label = QtWidgets.QLabel("-")
        self.point_label.setWordWrap(True)
        self.goto_button = QtWidgets.QPushButton("Set synthesizer to this point (RF on)")
        self.prev_button = QtWidgets.QPushButton("< Previous")
        self.next_button = QtWidgets.QPushButton("Next >")
        self.reading_spin = make_double_spin(-120.0, 40.0, 3, 0.1, " dBm", 0.0)
        self.reading_spin.setToolTip("Meter reading. Enter records it (and moves on if Auto-advance).")
        self.record_button = QtWidgets.QPushButton("Record reading")
        self.read_meter_button = QtWidgets.QPushButton("Read power meter")
        self.auto_advance = QtWidgets.QCheckBox("Auto-advance and set the next point")
        self.auto_advance.setChecked(True)
        self.auto_run_button = QtWidgets.QPushButton("Run all points with the power meter")
        self.abort_button = QtWidgets.QPushButton("Stop")
        self.abort_button.setEnabled(False)
        meas_form.addRow(self.point_label)
        meas_form.addRow("", self.goto_button)
        meas_form.addRow("", labelled_row(self.prev_button, self.next_button))
        meas_form.addRow("Reading", self.reading_spin)
        meas_form.addRow("", labelled_row(self.record_button, self.read_meter_button))
        meas_form.addRow("", self.auto_advance)
        meas_form.addRow("", labelled_row(self.auto_run_button, self.abort_button))
        left.addWidget(meas_box)

        use_box = QtWidgets.QGroupBox("Table")
        use_layout = QtWidgets.QVBoxLayout(use_box)
        self.save_button = QtWidgets.QPushButton("Save and make active for this unit")
        self.load_button = QtWidgets.QPushButton("Load...")
        self.export_csv_button = QtWidgets.QPushButton("Export CSV...")
        self.export_vsz_button = QtWidgets.QPushButton("Export .vszh5...")
        self.delete_button = QtWidgets.QPushButton("Delete selected rows")
        self.clear_button = QtWidgets.QPushButton("New table")
        self.show_expected_check = QtWidgets.QCheckBox("Show expected level at RF OUT on the Main tab")
        self.show_expected_check.setChecked(True)
        self.correct_check = QtWidgets.QCheckBox(
            "Correct the commanded level with the active table (power-control models)")
        self.active_label = QtWidgets.QLabel("Active table: none")
        self.active_label.setWordWrap(True)
        for row in ((self.save_button, self.load_button), (self.export_csv_button, self.export_vsz_button),
                    (self.delete_button, self.clear_button)):
            use_layout.addWidget(labelled_row(*row))
        use_layout.addWidget(self.show_expected_check)
        use_layout.addWidget(self.correct_check)
        use_layout.addWidget(self.active_label)
        left.addWidget(use_box)
        left.addStretch(1)

        right = QtWidgets.QVBoxLayout()
        self.power_table = QtWidgets.QTableWidget(0, len(self.POWER_COLUMNS))
        self.power_table.setHorizontalHeaderLabels(self.POWER_COLUMNS)
        self.power_table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.power_table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.power_table.verticalHeader().setVisible(False)     # "#" column numbers rows
        right.addWidget(self.power_table, 2)
        if HAVE_PYQTGRAPH:
            self.power_plot = pg.PlotWidget()
            self.power_plot.setLabel("bottom", "Frequency", units="GHz")
            self.power_plot.setLabel("left", "Level at RF OUT", units="dBm")
            self.power_plot.showGrid(x=True, y=True, alpha=0.3)
            self.power_plot.addLegend(offset=(-10, 10))          # top right
            right.addWidget(self.power_plot, 3)
        else:
            self.power_plot = None
            right.addWidget(QtWidgets.QLabel("pyqtgraph is not installed; the table has the data."))
        layout.addLayout(left, 2)
        layout.addLayout(right, 3)

        c = self.ctl
        self.generate_button.clicked.connect(lambda: c.guard(self._make_plan))
        self.path_combo.activated.connect(lambda _i: c.guard(self._path_changed))
        self.path_const.valueChanged.connect(lambda _v: c.guard(self._path_changed))
        self.path_file_button.clicked.connect(lambda: c.guard(self._load_path_file))
        self.goto_button.clicked.connect(lambda: c.guard(self._goto_point))
        self.prev_button.clicked.connect(lambda: self._step_point(-1))
        self.next_button.clicked.connect(lambda: self._step_point(+1))
        self.record_button.clicked.connect(lambda: self._record_manual())
        self._enter_filter = EnterApplies(self.reading_spin, self._record_manual)
        self.read_meter_button.clicked.connect(lambda: c.guard(self._read_power_meter))
        self.auto_run_button.clicked.connect(lambda: c.guard(self._start_auto_run))
        self.abort_button.clicked.connect(self._stop_auto_run)
        self.save_button.clicked.connect(lambda: self._guard_local(self._save_table))
        self.load_button.clicked.connect(lambda: self._guard_local(self._load_table_dialog))
        self.export_csv_button.clicked.connect(lambda: self._guard_local(self._export_csv_dialog))
        self.export_vsz_button.clicked.connect(lambda: self._guard_local(self._export_vszh5_dialog))
        self.delete_button.clicked.connect(self._delete_rows)
        self.clear_button.clicked.connect(self._new_table)
        self.show_expected_check.toggled.connect(lambda _on: self._main_tab_update())
        self.correct_check.toggled.connect(lambda _on: self._main_tab_update())
        return page

    def _guard_local(self, action: Callable[[], Any]) -> Any:
        """Like AppController.guard, but for file work that needs no instrument."""
        try:
            return action()
        except (QuickSynError, OSError, ValueError) as exc:
            self.ctl.status_message(f"Error: {exc}")
            return None

    def _unit(self) -> tuple[str, str, str]:
        """(model, serial, firmware) of the connected unit, or blanks."""
        driver = self.ctl.driver
        if driver is None:
            return "", "", ""
        ident = driver.identity
        return ident.model, ident.serial, ident.firmware

    def _has_power_control(self) -> bool:
        driver = self.ctl.driver
        return bool(driver is not None and driver.capability.has_power_control)

    def _make_plan(self) -> None:
        """Frequency list x level list, clamped to the model's range."""
        start, stop, step = (self.start_f.value() * 1e9, self.stop_f.value() * 1e9,
                             self.step_f.value() * 1e9)
        if stop < start:
            raise CalibrationError("Stop is below start.")
        count = int(math.floor((stop - start) / step + 1e-9)) + 1
        if count > 5000:
            raise CalibrationError(f"{count} points is too many; use a larger step.")
        freqs = [start + i * step for i in range(count)]
        if abs(freqs[-1] - stop) > 1e-3 * step:
            freqs.append(stop)
        driver = self.ctl.driver
        dropped = 0
        if driver is not None:
            cap = driver.capability
            low = cap.f_min_opt1_hz if cap.f_min_opt1_hz is not None else cap.f_min_hz
            kept = [f for f in freqs if low - 1e-3 <= f <= cap.f_max_hz + 1e-3]
            dropped = len(freqs) - len(kept)
            freqs = kept
        if not freqs:
            raise CalibrationError("No points inside the model's frequency range.")
        levels: list[float | None] = [None]
        text = self.levels_edit.text().strip()
        if text and self._has_power_control():
            try:
                levels = [quantise_power_dbm(float(v)) for v in re.split(r"[,; ]+", text) if v]
            except ValueError as exc:
                raise CalibrationError(f"Levels {text!r}: {exc}") from exc
        elif text:
            self.ctl.status_message("Levels ignored: this model has a fixed output level.")
        self.plan = [(f, level) for level in levels for f in freqs]
        self.plan_index = 0
        self.plan_label.setText(
            f"{len(self.plan)} points ({len(freqs)} frequencies x {len(levels)} level"
            f"{'s' if len(levels) > 1 else ''})" + (f"; {dropped} outside the model's range dropped"
                                                     if dropped else "") + ".")
        self._refresh_point_label()

    def _current_point(self) -> tuple[float, float | None] | None:
        return self.plan[self.plan_index] if 0 <= self.plan_index < len(self.plan) else None

    def _refresh_point_label(self) -> None:
        point = self._current_point()
        if point is None:
            self.point_label.setText("Make a point list first." if not self.plan else "All points done.")
            return
        f, level = point
        level_text = "fixed output" if level is None else f"set {level:+.1f} dBm"
        try:
            loss = self.path.loss_at(f)
            loss_text = f"path loss {loss:.2f} dB"
        except CalibrationError as exc:
            loss_text = f"<span style='color:#d9483b;'>{html.escape(str(exc))}</span>"
        self.point_label.setText(f"Point {self.plan_index + 1} of {len(self.plan)}: "
                                 f"{f / 1e9:.6f} GHz, {level_text}; {loss_text}")

    def _step_point(self, delta: int) -> None:
        if self.plan:
            self.plan_index = min(max(self.plan_index + delta, 0), len(self.plan))
            self._refresh_point_label()

    def _goto_point(self) -> None:
        """Command the current point's frequency (and level) and switch RF on."""
        point = self._current_point()
        if point is None:
            raise CalibrationError("No point to set; make a point list first.")
        f, level = point
        driver = self.ctl.driver
        driver.set_frequency(f)
        if level is not None:
            driver.set_power(level)
        driver.set_rf_output(True)
        main = self.ctl.window.tab_main
        main.freq_spin.setValue(f / 1e9)
        if level is not None:
            main.power_spin.setValue(level)
        main.update_status(driver.get_status())        # RF on, read back
        main.update_cal_output()
        self.ctl.status_message(f"Calibration point set: {f / 1e9:.6f} GHz"
                                + ("" if level is None else f", {level:+.1f} dBm") + ", RF on.")

    def _record(self, reading_dbm: float, source: str) -> None:
        """Store a reading for the current point and move on if asked."""
        point = self._current_point()
        if point is None:
            raise CalibrationError("No current point; make a point list first.")
        f, level = point
        loss = self.path.loss_at(f)
        model, serial, _ = self._unit()
        if self.table.points and serial and self.table.serial and \
                (self.table.model, self.table.serial) != (model, serial):
            raise CalibrationError(
                f"This table belongs to {self.table.model} {self.table.serial}, not the unit "
                f"connected ({model} {serial}); press New table first.")
        if not self.table.points:
            model, serial, firmware = self._unit()
            self.table.model, self.table.serial, self.table.firmware = model, serial, firmware
            self.table.created_iso = utc_iso(time.time())
            try:
                import getpass
                self.table.operator = getpass.getuser()
            except Exception:  # pragma: no cover - platform specific
                self.table.operator = ""
        self.table.path = self.path.to_dict()
        self.table.add(PowerCalPoint(f, level, float(reading_dbm), loss, time.time(), source))
        self._refresh_power_view()
        self.ctl.status_message(f"Recorded {reading_dbm:+.3f} dBm at {f / 1e9:.6f} GHz "
                                f"(RF OUT {reading_dbm + loss:+.3f} dBm).")
        if self.auto_advance.isChecked():
            self.plan_index += 1
            self._refresh_point_label()
            if self._current_point() is not None and self.ctl.driver is not None and not self._auto_running:
                self.ctl.guard(self._goto_point)
        else:
            self._refresh_point_label()

    def _record_manual(self) -> None:
        if self.reading_spin.take_rejected_text() is not None:
            return
        self._guard_local(lambda: self._record(self.reading_spin.value(), "manual"))

    def _reader(self, key: str) -> InstrumentReader:
        cfg = self.power_meter_cfg if key == "power" else self.counter_cfg
        reader = self.readers.get(key)
        if reader is None or reader.config is not cfg:
            reader = InstrumentReader(cfg)
            self.readers[key] = reader
        return reader

    def _read_power_meter(self) -> None:
        point = self._current_point()
        if point is None:
            raise CalibrationError("No current point; make a point list first.")
        self._apply_meter_fields()
        reader = self._reader("power")
        value = reader.read(point[0])
        self.reading_spin.setValue(value)
        if not self.table.meter and reader.idn:
            self.table.meter = reader.idn
        self._record(value, self.power_meter_cfg.resource or "meter")

    # --- automatic run with a meter -----------------------------------------
    def _start_auto_run(self) -> None:
        if self._current_point() is None:
            raise CalibrationError("No points left; make a point list first.")
        self._apply_meter_fields()
        self._reader("power").open()
        self._auto_running = True
        self.auto_run_button.setEnabled(False)
        self.abort_button.setEnabled(True)
        self._auto_step()

    def _auto_step(self) -> None:
        if not self._auto_running:
            return
        if self._current_point() is None or self.ctl.driver is None:
            self._stop_auto_run("Automatic run finished.")
            return
        if self.ctl.guard(lambda: (self._goto_point(), True)[1]) is None:
            self._stop_auto_run("Automatic run stopped: could not set the point.")
            return
        QtCore.QTimer.singleShot(int(self.settle_spin.value() * 1000), self._auto_read)

    def _auto_read(self) -> None:
        if not self._auto_running:
            return
        before = len(self.table.points)
        self.ctl.guard(self._read_power_meter)
        if len(self.table.points) == before:
            self._stop_auto_run("Automatic run stopped: the meter read failed.")
            return
        if not self.auto_advance.isChecked():
            self.plan_index += 1
            self._refresh_point_label()
        QtCore.QTimer.singleShot(0, self._auto_step)

    def _stop_auto_run(self, message: str = "Automatic run stopped.") -> None:
        was = self._auto_running
        self._auto_running = False
        self.auto_run_button.setEnabled(True)
        self.abort_button.setEnabled(False)
        if was:
            self.ctl.status_message(message)

    # --- path loss -------------------------------------------------------------
    def _path_changed(self) -> None:
        kind = self.path_combo.currentData()
        if kind == "none":
            self.path = PathLoss()
        elif kind == "constant":
            self.path = PathLoss(kind="constant", constant_db=self.path_const.value())
        self.path_label.setText(self.path.describe())
        self._refresh_point_label()

    def _load_path_file(self, path: str | None = None) -> None:
        kind = self.path_combo.currentData()
        if kind not in ("csv", "s2p"):
            self.path_combo.setCurrentIndex(self.path_combo.findData("s2p"))
            kind = "s2p"
        if path is None:
            pattern = "Touchstone (*.s2p *.S2P)" if kind == "s2p" else "CSV (*.csv *.txt)"
            path, _ = QtWidgets.QFileDialog.getOpenFileName(self, "Path-loss file", "", pattern)
            if not path:
                return
        self.path = PathLoss.from_touchstone(path) if kind == "s2p" else PathLoss.from_csv(path)
        self.path_label.setText(self.path.describe())
        self._refresh_point_label()

    # --- table views --------------------------------------------------------------
    def _refresh_power_view(self) -> None:
        rows = self.table.points
        self.power_table.setRowCount(len(rows))
        spec = SPEC_MIN_POWER_DBM.get(self.table.model or self._unit()[0])
        for r, p in enumerate(rows):
            if p.error_db is not None:
                err = f"{p.error_db:+.2f}"
            elif spec is not None:
                err = f"{p.output_dbm - spec:+.2f} vs spec"
            else:
                err = ""
            values = (str(r + 1), f"{p.freq_hz / 1e9:.6f}",
                      "fixed" if p.set_dbm is None else f"{p.set_dbm:+.1f}",
                      f"{p.reading_dbm:+.3f}", f"{p.path_loss_db:.3f}", f"{p.output_dbm:+.3f}",
                      err, p.source)
            for col, text in enumerate(values):
                self.power_table.setItem(r, col, QtWidgets.QTableWidgetItem(text))
        self.power_table.resizeColumnsToContents()
        if self.power_plot is not None:
            self._style_plot()
            self.power_plot.clear()
            colours = ("#3b7dd8", "#d9483b", "#2e9e5b", "#b07d2a", "#8a4fbf", "#4a9aa8")
            for i, level in enumerate(self.table.levels() if rows else []):
                f, out = self.table.curve(level)
                name = "fixed output" if level is None else f"set {level:+.1f} dBm"
                pen = pg.mkPen(colours[i % len(colours)], width=2)
                self.power_plot.plot([x / 1e9 for x in f], out, pen=pen, symbol="o", symbolSize=6,
                                     symbolBrush=colours[i % len(colours)], name=name)
            if spec is not None and rows:
                span = self.table.frequency_span()
                self.power_plot.plot([span[0] / 1e9, span[1] / 1e9], [spec, spec],
                                     pen=pg.mkPen("#8c8c8c", width=1, style=QtCore.Qt.PenStyle.DashLine),
                                     name=f"datasheet minimum {spec:+.0f} dBm [R4]")

    def _style_plot(self) -> None:
        """Follow the current palette (pyqtgraph's own options only reach new plots)."""
        palette = self.palette()
        foreground = palette.color(QtGui.QPalette.ColorRole.Text)
        self.power_plot.setBackground(palette.color(QtGui.QPalette.ColorRole.Base))
        for name in ("left", "bottom"):
            axis = self.power_plot.getAxis(name)
            axis.setPen(foreground)
            axis.setTextPen(foreground)

    def changeEvent(self, event: QtCore.QEvent) -> None:  # noqa: N802 (Qt API)
        """Re-colour the plot when View > Theme changes the palette."""
        if event.type() == QtCore.QEvent.Type.PaletteChange \
                and getattr(self, "power_plot", None) is not None:
            self._style_plot()
        super().changeEvent(event)

    def _delete_rows(self) -> None:
        rows = sorted({i.row() for i in self.power_table.selectedIndexes()}, reverse=True)
        for r in rows:
            if 0 <= r < len(self.table.points):
                del self.table.points[r]
        self._refresh_power_view()

    def _new_table(self) -> None:
        self.table = PowerCalTable()
        self.plan_index = 0
        self._refresh_power_view()
        self._refresh_point_label()

    def _save_table(self) -> None:
        if not self.table.points:
            raise CalibrationError("The table is empty.")
        if not self.table.serial:
            raise CalibrationError("No unit serial: connect to the synthesizer before saving.")
        dated, active = self.store.save_power(self.table)
        self.set_active_table(PowerCalTable.load(active))
        self.ctl.status_message(f"Power calibration saved: {dated} (active for {self.table.model} "
                                f"{self.table.serial}).")

    def _load_table_dialog(self, path: str | None = None) -> None:
        if path is None:
            path, _ = QtWidgets.QFileDialog.getOpenFileName(
                self, "Power calibration", str(self.store.root), "QuickSyn power cal (*.json)")
            if not path:
                return
        self.table = PowerCalTable.load(path)
        self._refresh_power_view()
        model, serial, _ = self._unit()
        if serial and self.table.serial == serial:
            self.set_active_table(self.table)
        self.ctl.status_message(f"Loaded {Path(path).name}: {len(self.table.points)} points, "
                                f"{self.table.model} {self.table.serial}.")

    def _export_csv_dialog(self, path: str | None = None) -> None:
        if path is None:
            path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Export CSV", "power_cal.csv",
                                                            "CSV (*.csv)")
            if not path:
                return
        self.table.to_csv(path)
        self.ctl.status_message(f"Exported {path}")

    def _export_vszh5_dialog(self, path: str | None = None) -> None:
        if path is None:
            path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Export Veusz document",
                                                            "power_cal.vszh5", "Veusz HDF5 (*.vszh5)")
            if not path:
                return
        written = export_power_cal_vszh5(self.table, path)
        self.ctl.status_message(f"Exported {written}")

    def set_active_table(self, table: PowerCalTable | None) -> None:
        """Use ``table`` for the Main tab readout and level correction."""
        self.active_table = table
        if table is None:
            self.active_label.setText("Active table: none")
        else:
            span = table.frequency_span()
            band = "" if span is None else f", {span[0] / 1e9:.3f}-{span[1] / 1e9:.3f} GHz"
            self.active_label.setText(
                f"Active table: {table.model} {table.serial}, {len(table.points)} points{band}, "
                f"{table.created_iso or 'undated'}; path: "
                f"{PathLoss.from_dict(table.path).describe() if table.path else 'none'}")
        self._main_tab_update()

    def correction_enabled(self) -> bool:
        """True when commanded levels should be corrected with the active table."""
        return bool(self.correct_check.isChecked() and self.active_table is not None
                    and self.active_table.levels() != [None] and self._has_power_control())

    def _main_tab_update(self) -> None:
        main = getattr(self.ctl.window, "tab_main", None)
        if main is not None:
            main.update_cal_output()

    # ------------------------------------------------------------------ reference
    def _build_reference(self) -> QtWidgets.QWidget:
        page = QtWidgets.QWidget()
        layout = QtWidgets.QHBoxLayout(page)
        left = QtWidgets.QVBoxLayout()
        warn = QtWidgets.QLabel(
            "Tunes the internal 10 MHz OCXO with DIAG:CAL:REF:DAC [R1], the method of [R3] Step 4: "
            "counter on RF OUT, referenced to a 10 MHz standard. Measure, record, send the next DAC "
            "value, repeat until within tolerance. The original value is kept for Restore. Whether a "
            "value sent this way survives a power cycle is not documented; tick 'Apply on connect' "
            "to send the saved value each time this program connects.")
        warn.setWordWrap(True)
        left.addWidget(warn)
        box = QtWidgets.QGroupBox("Tuning")
        form = QtWidgets.QFormLayout(box)
        self.ref_target = make_double_spin(0.5, 40.0, 6, 1.0, " GHz", DEFAULT_REF_CAL_FREQ_HZ / 1e9)
        self.ref_tol = make_double_spin(0.001, 10000.0, 3, 1.0, " Hz", DEFAULT_REF_CAL_TOL_HZ)
        self.ref_step = make_int_spin(-30000, 30000, DEFAULT_REF_TRIAL_STEP, " counts")
        self.ref_start_button = QtWidgets.QPushButton("Start: read DAC, internal reference, RF on")
        self.ref_dac_label = QtWidgets.QLabel("DAC: -")
        self.ref_measured = make_double_spin(0.0, 41e9, 3, 1.0, " Hz", DEFAULT_REF_CAL_FREQ_HZ)
        self.ref_record_button = QtWidgets.QPushButton("Record measurement")
        self.ref_read_counter_button = QtWidgets.QPushButton("Read counter")
        self.ref_next_label = QtWidgets.QLabel("Next DAC: -")
        self.ref_apply_button = QtWidgets.QPushButton("Send next DAC value")
        self.ref_auto_apply = QtWidgets.QCheckBox("Send the next value automatically after recording")
        self.ref_auto_apply.setChecked(True)
        self.ref_restore_button = QtWidgets.QPushButton("Restore original DAC")
        self.ref_save_button = QtWidgets.QPushButton("Save as this unit's reference calibration")
        self.ref_apply_on_connect = QtWidgets.QCheckBox("Apply the saved value on connect")
        self.ref_saved_label = QtWidgets.QLabel("Saved: none")
        self.ref_saved_label.setWordWrap(True)
        form.addRow("Counter frequency", self.ref_target)
        form.addRow("Tolerance", self.ref_tol)
        form.addRow("First trial step", self.ref_step)
        form.addRow("", self.ref_start_button)
        form.addRow(self.ref_dac_label)
        form.addRow("Measured", self.ref_measured)
        form.addRow("", labelled_row(self.ref_record_button, self.ref_read_counter_button))
        form.addRow(self.ref_next_label)
        form.addRow("", self.ref_apply_button)
        form.addRow("", self.ref_auto_apply)
        form.addRow("", labelled_row(self.ref_restore_button, self.ref_save_button))
        form.addRow("", self.ref_apply_on_connect)
        form.addRow(self.ref_saved_label)
        left.addWidget(box)
        left.addStretch(1)
        self.ref_table = QtWidgets.QTableWidget(0, len(self.REF_COLUMNS))
        self.ref_table.setHorizontalHeaderLabels(self.REF_COLUMNS)
        self.ref_table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.ref_table.verticalHeader().setVisible(False)
        layout.addLayout(left, 2)
        layout.addWidget(self.ref_table, 3)

        c = self.ctl
        self.ref_start_button.clicked.connect(lambda: c.guard(self._ref_start))
        self.ref_record_button.clicked.connect(lambda: c.guard(self._ref_record_manual))
        self._ref_enter = EnterApplies(self.ref_measured, lambda: c.guard(self._ref_record_manual))
        self.ref_read_counter_button.clicked.connect(lambda: c.guard(self._ref_read_counter))
        self.ref_apply_button.clicked.connect(lambda: c.guard(self._ref_apply_next))
        self.ref_restore_button.clicked.connect(lambda: c.guard(self._ref_restore))
        self.ref_save_button.clicked.connect(lambda: c.guard(self._ref_save))
        self.ref_apply_on_connect.toggled.connect(self._ref_apply_on_connect_changed)
        return page

    def _ref_start(self) -> None:
        driver = self.ctl.driver
        original = driver.get_reference_dac()
        self.tuner = RefCalTuner(self.ref_target.value() * 1e9, self.ref_tol.value(),
                                 self.ref_step.value(), original)
        driver.set_reference_source(RefSource.INTERNAL)
        driver.set_frequency(self.tuner.target_hz)
        driver.set_rf_output(True)
        self.ref_measured.setValue(self.tuner.target_hz)
        self._refresh_ref_view()
        self.ctl.status_message(f"Reference tuning started: DAC {original}, internal reference, "
                                f"{self.tuner.target_hz / 1e9:.6f} GHz, RF on. Measure RF OUT.")

    def _ref_current_dac(self) -> int:
        return self.ctl.driver.get_reference_dac()

    def _ref_record(self, measured_hz: float, source: str) -> None:
        if self.tuner is None:
            raise CalibrationError("Press Start first.")
        it = self.tuner.record(self._ref_current_dac(), measured_hz, source)
        self._refresh_ref_view()
        if self.tuner.converged():
            self.ctl.status_message(f"Within tolerance: DAC {it.dac}, error {it.error_hz:+.3f} Hz "
                                    f"({it.error_ppb:+.3f} ppb). Save to keep it.")
        elif self.ref_auto_apply.isChecked():
            self._ref_apply_next()

    def _ref_record_manual(self) -> None:
        if self.ref_measured.take_rejected_text() is not None:
            return
        self._ref_record(self.ref_measured.value(), "manual")

    def _ref_read_counter(self) -> None:
        self._apply_meter_fields()
        value = self._reader("counter").read(self.tuner.target_hz if self.tuner else None)
        self.ref_measured.setValue(value)
        self._ref_record(value, self.counter_cfg.resource or "counter")

    def _ref_apply_next(self) -> None:
        if self.tuner is None:
            raise CalibrationError("Press Start first.")
        dac = self.tuner.next_dac()
        QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.CursorShape.WaitCursor)
        try:
            self.ctl.driver.set_reference_dac(dac)       # waits WAIT_REF_DAC_S
        finally:
            QtWidgets.QApplication.restoreOverrideCursor()
        self._refresh_ref_view()
        self.ctl.status_message(f"DIAG:CAL:REF:DAC {dac} sent; let the OCXO settle, then measure again.")

    def _ref_restore(self) -> None:
        if self.tuner is None:
            raise CalibrationError("Nothing to restore: tuning was not started.")
        self.ctl.driver.set_reference_dac(self.tuner.original_dac)
        self._refresh_ref_view()
        self.ctl.status_message(f"Original DAC {self.tuner.original_dac} restored.")

    def _ref_save(self) -> None:
        if self.tuner is None or not self.tuner.iterations:
            raise CalibrationError("No measurements to save.")
        best = self.tuner.best()
        model, serial, _ = self._unit()
        if not serial:
            raise CalibrationError("No unit serial: connect first.")
        if self._ref_current_dac() != best.dac:
            self.ctl.driver.set_reference_dac(best.dac)
        self.ref_record = RefCalRecord(model=model, serial=serial, dac=best.dac,
                                       original_dac=self.tuner.original_dac,
                                       target_hz=best.target_hz, measured_hz=best.measured_hz,
                                       created_iso=utc_iso(time.time()),
                                       apply_on_connect=self.ref_apply_on_connect.isChecked())
        path = self.store.save_ref(self.ref_record)
        self._refresh_ref_view()
        self.ctl.status_message(f"Reference calibration saved ({path}): DAC {best.dac}, "
                                f"error {best.error_hz:+.3f} Hz.")

    def _ref_apply_on_connect_changed(self, on: bool) -> None:
        if self.ref_record is not None:
            self.ref_record.apply_on_connect = on
            self._guard_local(lambda: self.store.save_ref(self.ref_record))
            self._refresh_ref_view()

    def _refresh_ref_view(self) -> None:
        its = self.tuner.iterations if self.tuner else []
        self.ref_table.setRowCount(len(its))
        for r, it in enumerate(its):
            for col, text in enumerate((str(r + 1), str(it.dac), f"{it.measured_hz:.3f}",
                                        f"{it.error_hz:+.3f}", f"{it.error_ppb:+.4f}", it.source)):
                self.ref_table.setItem(r, col, QtWidgets.QTableWidgetItem(text))
        self.ref_table.resizeColumnsToContents()
        if self.tuner is not None:
            slope = self.tuner.slope_hz_per_count()
            self.ref_dac_label.setText(
                f"Original DAC {self.tuner.original_dac}; "
                + (f"slope {slope:+.4f} Hz/count at {self.tuner.target_hz / 1e9:g} GHz"
                   if slope is not None else "slope not yet measured"))
            done = self.tuner.converged()
            self.ref_next_label.setText(
                f"{'Converged' if done else 'Next DAC'}: {self.tuner.next_dac()}"
                + (f" (within {self.tuner.tolerance_hz:g} Hz)" if done else ""))
        record = self.ref_record
        if record is None:
            self.ref_saved_label.setText("Saved: none for this unit")
        else:
            self.ref_saved_label.setText(
                f"Saved: DAC {record.dac} (original {record.original_dac}), error "
                f"{record.error_hz:+.3f} Hz at {record.target_hz / 1e9:g} GHz, {record.created_iso}; "
                f"apply on connect: {'yes' if record.apply_on_connect else 'no'}")
            self.ref_apply_on_connect.blockSignals(True)
            self.ref_apply_on_connect.setChecked(record.apply_on_connect)
            self.ref_apply_on_connect.blockSignals(False)

    # ------------------------------------------------------------------ meters
    def _build_meters(self) -> QtWidgets.QWidget:
        page = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(page)
        have = InstrumentReader.available()
        status = QtWidgets.QLabel(
            "PyVISA is installed." if have else
            "PyVISA is not installed, so meters cannot be read; typed readings work. "
            "Install with: mamba install -c conda-forge pyvisa pyvisa-py")
        status.setWordWrap(True)
        layout.addWidget(status)
        hint = QtWidgets.QLabel(
            "Any SCPI instrument whose query returns one number. Defaults follow common SCPI "
            "usage; check them in the instrument's manual. NI's own panel expects an Agilent "
            "E4418B power meter or an exact SCPI equivalent, and a Pendulum CNT-90, Anritsu "
            "MF2412B or Phase Matrix 346A counter [R3]. In the pre-command, {freq_hz} and "
            "{freq_ghz} are replaced by the point's frequency (for the sensor cal factor).")
        hint.setWordWrap(True)
        layout.addWidget(hint)
        self.meter_widgets: dict[str, dict[str, QtWidgets.QWidget]] = {}
        for key, title, cfg in (("power", "Power meter", self.power_meter_cfg),
                                ("counter", "Frequency counter", self.counter_cfg)):
            box = QtWidgets.QGroupBox(title)
            form = QtWidgets.QFormLayout(box)
            resource = QtWidgets.QLineEdit(cfg.resource)
            resource.setPlaceholderText("GPIB0::13::INSTR, USB0::...::INSTR, TCPIP0::host::inst0::INSTR")
            backend = QtWidgets.QComboBox()
            backend.addItem("Default VISA library (NI-VISA, Keysight IO Libraries)", "")
            backend.addItem("pyvisa-py (@py)", "@py")
            query = QtWidgets.QLineEdit(cfg.query)
            pre = QtWidgets.QLineEdit(cfg.pre_command)
            timeout = make_int_spin(100, 120_000, cfg.timeout_ms, " ms")
            test = QtWidgets.QPushButton("Connect and identify (*IDN?)")
            listing = QtWidgets.QPushButton("List resources")
            result = QtWidgets.QLabel("-")
            result.setWordWrap(True)
            for w in (test, listing):
                w.setEnabled(have)
            form.addRow("VISA resource", resource)
            form.addRow("Back end", backend)
            form.addRow("Query", query)
            form.addRow("Pre-command", pre)
            form.addRow("Timeout", timeout)
            form.addRow("", labelled_row(test, listing))
            form.addRow(result)
            layout.addWidget(box)
            self.meter_widgets[key] = {"resource": resource, "backend": backend, "query": query,
                                       "pre": pre, "timeout": timeout, "result": result}
            test.clicked.connect(lambda _c=False, k=key: self._guard_local(lambda: self._test_meter(k)))
            listing.clicked.connect(lambda _c=False, k=key: self._guard_local(lambda: self._list_meter(k)))
        layout.addStretch(1)
        return page

    def _apply_meter_fields(self) -> None:
        """Copy the Meters page into the two MeterConfig objects."""
        for key, cfg in (("power", self.power_meter_cfg), ("counter", self.counter_cfg)):
            w = self.meter_widgets[key]
            before = (cfg.resource, cfg.backend, cfg.timeout_ms)
            cfg.resource = w["resource"].text().strip()
            cfg.backend = w["backend"].currentData() or ""
            cfg.query = w["query"].text().strip() or cfg.query
            cfg.pre_command = w["pre"].text().strip()
            cfg.timeout_ms = int(w["timeout"].value())
            reader = self.readers.get(key)
            if reader is not None and before != (cfg.resource, cfg.backend, cfg.timeout_ms):
                reader.close()              # reopened with the new settings on next use

    def _test_meter(self, key: str) -> None:
        self._apply_meter_fields()
        reader = self._reader(key)
        idn = reader.open()
        self.meter_widgets[key]["result"].setText(f"Connected: {idn}")
        if key == "power":
            self.table.meter = idn

    def _list_meter(self, key: str) -> None:
        self._apply_meter_fields()
        found = self._reader(key).list_resources()
        self.meter_widgets[key]["result"].setText(", ".join(found) if found else "No resources found.")

    # ------------------------------------------------------------------ connection
    def on_connected(self) -> None:
        """Load this unit's saved tables and apply the reference value if asked."""
        model, serial, _ = self._unit()
        control = self._has_power_control()
        self.levels_edit.setEnabled(control)
        self.correct_check.setEnabled(control)
        self.ref_record = None
        self.tuner = None
        self.set_active_table(None)
        self._refresh_power_view()
        if not serial:
            self._refresh_ref_view()
            return
        try:
            self.set_active_table(self.store.load_active_power(model, serial))
            self.ref_record = self.store.load_ref(model, serial)
        except CalibrationError as exc:
            self.ctl.warn(f"Calibration file for {model} {serial} not usable: {exc}")
        self._refresh_ref_view()
        record = self.ref_record
        if record is not None and record.apply_on_connect:
            try:
                self.ctl.driver.set_reference_dac(record.dac)
            except QuickSynError as exc:
                self.ctl.warn(f"Saved reference calibration (DAC {record.dac}) not applied: {exc}")
                return
            self.ctl.status_message(f"Reference calibration applied: DIAG:CAL:REF:DAC {record.dac} "
                                    f"(saved {record.created_iso}).")

    def on_disconnected(self) -> None:
        """Stop any automatic run and close meters."""
        self._stop_auto_run()
        for reader in self.readers.values():
            reader.close()


def export_power_cal_vszh5(table: PowerCalTable, path: str | os.PathLike) -> Path:
    """Write a power calibration as a Veusz HDF5 document (h5py only, no Veusz).

    One page: level at RF OUT against frequency, one curve per commanded
    level (one curve on fixed-output models), with the datasheet minimum as
    a dashed line where [R4] gives one. Opened with Veusz 3.6 or later.
    """
    if not table.points:
        raise CalibrationError("The table is empty.")
    if vszh5_writer is None:
        raise CalibrationError("vszh5_writer.py is not next to this program.")
    vw = vszh5_writer
    spec = SPEC_MIN_POWER_DBM.get(table.model)
    colours = ("#3b7dd8", "#d9483b", "#2e9e5b", "#b07d2a", "#8a4fbf", "#4a9aa8")
    writer = vw.VeuszWriter(Path(path), writer_tag=f"{APP_NAME} {__version__}")
    doc = vw.VszDoc(generator=f"{APP_NAME} {__version__} power calibration")
    with writer:
        series: list[tuple[str, str]] = []
        for level in table.levels():
            f, out = table.curve(level)
            if level is None:
                tag, key = "fixed", "fixed output"
            else:
                tag = f"set_{level:+.1f}".replace("+", "p").replace("-", "m").replace(".", "_")
                key = f"set {level:+.1f} dBm"
            writer.dataset_1d(f"cal_freq_ghz_{tag}", np.asarray(f) / 1e9, tags=("cal",))
            writer.dataset_1d(f"cal_rf_out_dbm_{tag}", out, tags=("cal",))
            series.append((tag, key))
        if spec is not None:
            lo, hi = table.frequency_span()
            writer.dataset_1d("cal_spec_freq_ghz", [lo / 1e9, hi / 1e9], tags=("cal",))
            writer.dataset_1d("cal_spec_dbm", [spec, spec], tags=("cal",))
        title = (f"{table.model} {table.serial} - level at RF OUT - "
                 f"{table.created_iso or 'undated'}")
        doc.add("page", "page_power_cal")
        doc.to("page_power_cal")
        doc.set("width", "25cm")
        doc.set("height", "15cm")
        doc.add("label", "title")
        doc.set("title/label", vw.vz_text(title))
        doc.set("title/xPos", [0.5])
        doc.set("title/yPos", [0.965])
        doc.set("title/alignHorz", "centre")
        doc.set("title/Text/size", "10pt")
        doc.add("graph", "graph1")
        doc.to("graph1")
        doc.set("leftMargin", "2.0cm")
        doc.set("rightMargin", "0.4cm")
        doc.set("topMargin", "0.9cm")
        doc.set("bottomMargin", "1.3cm")
        doc.add("axis", "x")
        doc.add("axis", "y")
        doc.set("x/label", "Frequency (GHz)")
        doc.set("y/direction", "vertical")
        doc.set("y/label", "Level at RF OUT (dBm)")
        doc.set("y/autoRange", "+5%")
        doc.set("y/GridLines/hide", False)
        doc.set("y/GridLines/color", "#c8c8c8")
        doc.set("y/GridLines/style", "dotted")
        for i, (tag, key) in enumerate(series):
            colour = colours[i % len(colours)]
            doc.add("xy", f"xy_{tag}")
            doc.to(f"xy_{tag}")
            doc.set("xData", f"cal_freq_ghz_{tag}")
            doc.set("yData", f"cal_rf_out_dbm_{tag}")
            doc.set("key", vw.vz_text(key))
            doc.set("marker", "circle")
            doc.set("markerSize", "2.5pt")
            doc.set("PlotLine/width", "0.8pt")
            doc.set("PlotLine/color", colour)
            doc.set("MarkerFill/color", colour)
            doc.up()
        if spec is not None:
            doc.add("xy", "xy_spec")
            doc.to("xy_spec")
            doc.set("xData", "cal_spec_freq_ghz")
            doc.set("yData", "cal_spec_dbm")
            doc.set("key", vw.vz_text(f"datasheet minimum {spec:+.0f} dBm"))
            doc.set("marker", "none")
            doc.set("PlotLine/style", "dashed")
            doc.set("PlotLine/color", "#8c8c8c")
            doc.up()
        doc.add("key", "key1")
        doc.set("key1/horzPosn", "right")       # the level usually falls with frequency,
        doc.set("key1/vertPosn", "top")         # so the top right is clear
        doc.up()
        doc.up()
        return writer.finish(doc.text())


# %% ===========================================================================
#    APPLICATION CONTROLLER
# =============================================================================
class AppController(QtCore.QObject):
    """Owns the transport, driver, session and sampler, and wires the tabs.

    The tabs hold no instrument state of their own; they call through to
    this object, which centralises error handling so that a failed
    transaction surfaces as a status-bar message and a log entry rather
    than an unhandled traceback.
    """

    #: Every SCPI exchange, with its source ("GUI" or "POLL"). Emitted from
    #: whichever thread made the exchange; Qt queues it to the GUI thread.
    transactionLogged = QtCore.Signal(object, str)

    def __init__(self, window: "MainWindow") -> None:
        super().__init__(window)
        self.window = window
        self.transport: SerialTransport | None = None
        self.driver: QuickSyn | None = None
        self.session: SessionLogger | None = None
        self.writer: TelemetryWriter | None = None
        self.ring: TelemetryRingBuffer | None = None
        self.sampler: TelemetrySampler | None = None
        self.sampler_errors = 0

        #: Buffers transactions produced before a session exists, so that
        #: the identity exchange at connect time still ends up in the log.
        self._pending_transactions: list[Transaction] = []

        self._ui_timer = QtCore.QTimer(self)
        self._ui_timer.setInterval(500)
        self._ui_timer.timeout.connect(self._refresh_statistics)

        #: Veusz document export state (see export_vszh5).
        self.last_session_dir: Path | None = None
        self._export_proc: QtCore.QProcess | None = None
        self._export_output: list[str] = []
        self._export_pending: tuple[Path, bool] | None = None
        self.last_export_ok: bool | None = None
        self._vszh5_timer = QtCore.QTimer(self)
        self._vszh5_timer.timeout.connect(
            lambda: self.export_vszh5(render=False, quiet=True)
        )

        #: "Auto-read all settings every N s" (Main tab switch).
        self._auto_sync_timer = QtCore.QTimer(self)
        self._auto_sync_timer.timeout.connect(self._auto_sync_tick)
        self._auto_sync_failures = 0

    # --- Error funnel -------------------------------------------------------
    def guard(self, action: Callable[[], Any]) -> Any:
        """Run an action, routing any failure to the status bar and log.

        Parameters
        ----------
        action:
            Zero-argument callable performing instrument work.

        Returns
        -------
        Any
            Whatever the action returned, or ``None`` on failure.
        """
        if self.driver is None:
            self.status_message("Not connected.")
            return None
        try:
            return action()
        except (QuickSynError, ValueError) as exc:
            self.status_message(f"Error: {exc}")
            if self.session is not None:
                self.session.logger.error("%s", exc)
            return None
        except Exception as exc:  # pragma: no cover - unexpected failure
            self.status_message(f"Unexpected error: {exc}")
            if self.session is not None:
                self.session.logger.exception("Unexpected error")
            return None

    def status_message(self, text: str) -> None:
        """Show a message on the main window status bar and in the log."""
        self.window.statusBar().showMessage(text, 10_000)
        if self.session is not None:
            self.session.logger.info("UI %s", text)

    def rf_off(self) -> None:
        """Mute the RF output (OUTP:STAT OFF) and confirm with STAT?."""
        def action() -> None:
            self.driver.set_rf_output(False)
            status = self.driver.get_status()
            self.window.tab_main.rf_check.setChecked(status.rf_output_on)
            if status.rf_output_on:
                self.warn("OUTP:STAT OFF sent, but STAT? still reports the RF output on.")
            else:
                self.status_message("RF output OFF (confirmed by STAT?).")
        self.guard(action)

    def send_raw(self, command: str, as_query: bool) -> None:
        """Send a command typed on the console's Send line, exactly as typed.

        It goes through the same transport (64-byte check, lock shared with
        the sampler) and is logged like any other exchange; the reply shows
        in the console. No interlock or range check applies.
        """
        def action() -> None:
            if as_query:
                reply = self.driver.io.query(command)
                self.status_message(f"{command} -> {reply or '(no reply before the timeout)'}")
            else:
                self.driver.io.write(command)
                self.status_message(f"{command} sent (no reply expected).")
        self.guard(action)

    def warn(self, text: str) -> None:
        """A warning: status bar (30 s), session log and the SCPI console."""
        self.window.statusBar().showMessage(f"Warning: {text}", 30_000)
        if self.session is not None:
            self.session.logger.warning("%s", text)
        console = getattr(self.window, "console", None)
        if console is not None:
            console.add_note(f"Warning: {text}")

    # --- Transaction routing ------------------------------------------------
    def _on_transaction(self, txn: Transaction) -> None:
        """Route a transaction to the session log and the live console."""
        source = "GUI" if threading.current_thread() is threading.main_thread() else "POLL"
        self.transactionLogged.emit(txn, source)
        if self.session is not None:
            self.session.log_transaction(txn)
        else:
            self._pending_transactions.append(txn)
            # Keep the pre-session buffer bounded.
            if len(self._pending_transactions) > 5000:
                del self._pending_transactions[:1000]

    def _on_state_event(self, parameter: str, value: Any, source: str) -> None:
        """Route a commanded state change to the session log."""
        if self.session is not None:
            self.session.log_state_event(parameter, value, source)

    # --- Connection ---------------------------------------------------------
    def connect_instrument(self, port: str, baud: int, simulate: bool) -> None:
        """Open the transport, identify the unit and sync the UI."""
        try:
            tab = self.window.tab_connection
            factory = SimulatedTransport if simulate else SerialTransport
            transport = factory(on_transaction=self._on_transaction)
            transport.intercommand_gap_s = tab.gap_spin.value()
            transport.open(port, baud, tab.timeout_spin.value())
            self.transport = transport
            self.driver = QuickSyn(transport, on_state_event=self._on_state_event)

            ident = self.driver.identify()
            tab.show_identity(ident, self.driver.capability)
            tab.set_connected(True)
            self._apply_capability_limits()
            # Read-backs from a previous connection would describe another unit.
            for label in (self.window.tab_main.freq_readback, self.window.tab_main.power_readback):
                label.setText("-")
            self.sync_from_instrument()

            # No dialog for firmware below the [R1] figure of 100: the
            # FSL-0020 tested reports firmware 0008 and answers SCPI (0.0.8).
            if ident.scpi_supported is None:
                self.status_message(
                    f"Connected. Firmware field {ident.firmware!r} could not be "
                    f"parsed, so SCPI support was not confirmed."
                )
            else:
                self.status_message(
                    f"Connected to {ident.model} on {transport.port_name}"
                    + (" (simulated)." if simulate else ".")
                )
            self.window.set_connected(True)
            # Per-unit calibration: active power table, reference DAC (0.0.10).
            # Last, so its status line is the one left showing.
            self.window.tab_cal.on_connected()
            self.window.tab_main.update_cal_output()
        except QuickSynError as exc:
            QtWidgets.QMessageBox.critical(self.window, "Connection failed", str(exc))
            self.disconnect_instrument()

    def disconnect_instrument(self) -> None:
        """Stop acquisition if running and close the transport."""
        if self.sampler is not None:
            self.stop_logging()
        tab_cal = getattr(self.window, "tab_cal", None)
        if tab_cal is not None:
            tab_cal.on_disconnected()
        if self.transport is not None:
            self.transport.close()
        self.transport = None
        self.driver = None
        self.window.tab_main.auto_sync_check.setChecked(False)
        self._auto_sync_timer.stop()
        self.window.tab_connection.set_connected(False)
        self.window.set_connected(False)
        self.status_message("Disconnected.")

    def _apply_capability_limits(self) -> None:
        """Clamp the UI spin boxes to the detected model's documented limits."""
        if self.driver is None:
            return
        cap = self.driver.capability
        lower_ghz = (
            cap.f_min_opt1_hz if cap.f_min_opt1_hz is not None else cap.f_min_hz
        ) / 1e9
        upper_ghz = cap.f_max_hz / 1e9
        for spin in (
            self.window.tab_main.freq_spin,
            self.window.tab_sweep.start_freq,
            self.window.tab_sweep.stop_freq,
            self.window.tab_sweep.fixed_freq,
            self.window.tab_list.gen_start_f,
            self.window.tab_list.gen_stop_f,
            self.window.tab_memory.safe_freq,
        ):
            spin.setRange(lower_ghz, upper_ghz)
        # The FSL and mmW series expose no PULSE, AM or FM connectors
        # [R4], so offering those commands would be offering control over
        # hardware that is not fitted. Hide the tab instead.
        mod_index = self.window.tabs.indexOf(self.window.tab_modulation)
        if mod_index >= 0:
            self.window.tabs.setTabEnabled(mod_index, cap.has_modulation)
            self.window.tabs.setTabToolTip(
                mod_index,
                ""
                if cap.has_modulation
                else f"{cap.model} has no PULSE, AM or FM inputs [R4].",
            )
        for spin in (
            self.window.tab_main.power_spin,
            self.window.tab_sweep.start_power,
            self.window.tab_sweep.stop_power,
            self.window.tab_sweep.fixed_power,
            self.window.tab_list.gen_start_p,
            self.window.tab_list.gen_stop_p,
            self.window.tab_memory.safe_power,
        ):
            spin.setRange(cap.p_min_dbm, cap.p_max_dbm)
        # Power control exists only on models with a power-control option
        # (FSW, option 2 [R4]). Fixed-output models get no editable level and
        # no power sweeps, and are told why, instead of a box that snaps back.
        main = self.window.tab_main
        fixed = not cap.has_power_control
        main.power_spin.setEnabled(not fixed)
        main.set_power_button.setEnabled(not fixed)
        main.power_cmd_combo.setEnabled(not fixed)
        main.power_range_label.setText(
            f"{cap.p_min_dbm:+.1f} to {cap.p_max_dbm:+.1f} dBm ({cap.model} with power-control "
            f"option 2; without it the output stays at {cap.p_default_dbm:+.1f} dBm) [R4]"
            if not fixed else f"fixed at {cap.p_default_dbm:+.1f} dBm typical ({cap.model})")
        main.power_note.setVisible(fixed)
        listed = 2 in self.driver.identity.option_numbers
        main.power_note.setText(
            f"The {cap.model} has a fixed output level ({cap.p_default_dbm:+.1f} dBm "
            f"typical) and no power-control option [R4], so the level cannot be set."
            + (" Its option word lists option 2, but on the FSL-0020 tested POW was "
               "accepted and read back while a power meter showed no change (README 3.3)."
               if listed else "")
            if fixed else "")
        main.power_spin.setToolTip(
            "POW. Quantised to 0.1 dB. Needs power-control option 2; the level is "
            "read back with POW? after each change." if not fixed else
            f"{cap.model}: fixed output level, no power control.")
        self.window.tab_sweep.set_power_sweeps_allowed(not fixed, cap.model)

    def sync_from_instrument(self) -> None:
        """Read every settable parameter back and refresh the UI."""
        if self.driver is None:
            return
        d = self.driver
        main = self.window.tab_main
        # A box the user is typing in is left alone (auto-read, 0.0.8).
        if not main.freq_spin.hasFocus():
            main.freq_spin.setValue(d.get_frequency() / 1e9)
        if not main.power_spin.hasFocus():
            main.power_spin.setValue(d.get_power())
        status = d.get_status()
        main.update_status(status)
        main.update_temperature(d.get_temperature())
        source = d.get_reference_source()
        index = main.refsrc_combo.findData(source.value)
        if index >= 0:
            main.refsrc_combo.blockSignals(True)
            main.refsrc_combo.setCurrentIndex(index)
            main.refsrc_combo.blockSignals(False)
        main.update_reference(source, status)
        refout = d.get_reference_output_optional()
        if refout is not None:
            if refout != status.ref_output_on:
                d.refout_status_reliable = False
            main.note_reference_output(refout, status)
        self.window.tab_modulation.update_modulation(d.get_modulation_status())
        main.update_cal_output()

    def set_auto_sync(self, enabled: bool, interval_s: float) -> None:
        """Start, retime or stop the periodic "Read all settings"."""
        self._auto_sync_failures = 0
        if enabled:
            self._auto_sync_timer.start(max(100, int(round(interval_s * 1000.0))))
            self.status_message(f"Auto-read of all settings every {interval_s:g} s.")
        elif self._auto_sync_timer.isActive():
            self._auto_sync_timer.stop()
            self.status_message("Auto-read of all settings stopped.")

    def _auto_sync_tick(self) -> None:
        """One periodic read of every setting; three failures in a row stop it."""
        if self.driver is None:
            return
        try:
            self.sync_from_instrument()
            self._auto_sync_failures = 0
        except (QuickSynError, ValueError) as exc:
            self._auto_sync_failures += 1
            self.status_message(
                f"Auto-read failed ({self._auto_sync_failures}/{AUTO_SYNC_MAX_FAILURES}): {exc}")
            if self._auto_sync_failures >= AUTO_SYNC_MAX_FAILURES:
                self.window.tab_main.auto_sync_check.setChecked(False)
                self.warn(f"Auto-read stopped after {AUTO_SYNC_MAX_FAILURES} failed reads.")

    # --- Acquisition --------------------------------------------------------
    def start_logging(self) -> None:
        """Open a session, start the writer thread and start sampling."""
        if self.driver is None:
            self.status_message("Connect to an instrument before logging.")
            return
        if self.sampler is not None:
            self.status_message("Logging is already running.")
            return

        monitor = self.window.tab_monitor
        config = monitor.config()
        root = Path(monitor.logdir_edit.text()).expanduser()
        try:
            root.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            QtWidgets.QMessageBox.critical(
                self.window, "Log directory", f"Cannot create {root}: {exc}"
            )
            return

        ident = self.driver.identity
        tag = f"{ident.model or 'quicksyn'}_{ident.options or 'na'}"
        self.session = SessionLogger(root, tag=tag)

        # Drain anything captured before the session existed.
        for txn in self._pending_transactions:
            self.session.log_transaction(txn)
        self._pending_transactions.clear()

        self.writer = TelemetryWriter(self.session)
        self.writer.start()

        self.ring = TelemetryRingBuffer(
            capacity=monitor.ring_spin.value(),
            on_spill=self.writer.submit_spill,
        )

        self.session.write_metadata(
            {
                "identity": asdict(ident),
                "capability": asdict(self.driver.capability),
                "transport": {
                    "port": self.transport.port_name,
                    "baudrate": self.transport.baudrate,
                    "simulated": isinstance(self.transport, SimulatedTransport),
                    "intercommand_gap_s": self.transport.intercommand_gap_s,
                    "read_timeout_s": self.transport.read_timeout_s,
                    "terminator": "CR (0x0D)",
                    "max_command_bytes": MAX_COMMAND_BYTES,
                },
                "sampler": asdict(config),
                "temperature_double_query": TEMPERATURE_DOUBLE_QUERY,
                "ring_capacity": self.ring.capacity,
                "ring_bytes": self.ring.nbytes,
                "telemetry_dtype": TELEMETRY_DTYPE.descr,
            }
        )

        self.sampler_errors = 0
        self.sampler = TelemetrySampler(
            self.driver, config, self.ring, self.writer, parent=self
        )
        self.sampler.sampleReady.connect(self._on_sample)
        self.sampler.samplerError.connect(self._on_sampler_error)
        self.sampler.rateReport.connect(self._on_rate_report)
        self.sampler.start()

        monitor.set_running(True)
        self._ui_timer.start()
        minutes = monitor.vszh5_refresh.value()
        if minutes > 0:
            self._vszh5_timer.start(minutes * 60_000)
        self.status_message(
            f"Logging at {config.rate_hz:g} Hz into {self.session.directory}"
        )

    def stop_logging(self, detached_export: bool = False) -> None:
        """Stop sampling, flush the ring buffer and close the session.

        Parameters
        ----------
        detached_export:
            Start the end-of-session .vszh5 export as a detached process, so
            it completes even though the window is closing.
        """
        self._ui_timer.stop()
        self._vszh5_timer.stop()
        if self.sampler is not None:
            self.sampler.stop()
            self.sampler.wait(5000)
            self.sampler = None
        if self.ring is not None:
            remaining = self.ring.flush()
            if self.session is not None:
                self.session.logger.info(
                    "Flushed %d residual records at stop.", remaining.size
                )
        if self.writer is not None:
            self.writer.stop()
            if self.session is not None:
                self.session.logger.info(
                    "Writer committed %d rows and %d chunks (%d rows dropped).",
                    self.writer.rows_written,
                    self.writer.chunks_written,
                    self.writer.dropped_rows,
                )
            self.writer = None
        if self.session is not None:
            self.session.close()
            folder = self.session.directory
            self.session = None
            self.last_session_dir = folder
            self.status_message(f"Logging stopped. Session saved to {folder}")
            monitor = self.window.tab_monitor
            if monitor.chk_vszh5_stop.isChecked():
                self._launch_export(folder, monitor.chk_vszh5_render.isChecked(),
                                    detached=detached_export)
        self.ring = None
        self.window.tab_monitor.set_running(False)

    def flush_ram(self) -> None:
        """Spill the resident ring-buffer contents on demand."""
        if self.ring is None:
            self.status_message("No acquisition is running.")
            return
        block = self.ring.flush()
        self.status_message(f"Flushed {block.size} records from RAM to disk.")

    # --- Veusz document (.vszh5) --------------------------------------------
    def _session_folder(self) -> Path | None:
        """The running session's folder, else the last one, else None."""
        if self.session is not None:
            return self.session.directory
        return self.last_session_dir

    def export_vszh5(self, render: bool = False, quiet: bool = False) -> None:
        """Write (or rewrite) the session .vszh5 now.

        While logging, the RAM ring is first spilled to a chunk file and the
        writer thread is given time to commit it, so the document includes
        every sample up to this moment; acquisition continues meanwhile.
        """
        folder = self._session_folder()
        if folder is None:
            self.status_message("No session yet: start logging first.")
            return
        if self.ring is not None and self.writer is not None:
            self.ring.flush()
            self._wait_for_writer(folder, render, quiet, deadline=time.perf_counter() + 15.0)
        else:
            self._launch_export(folder, render, quiet=quiet)

    def _wait_for_writer(self, folder: Path, render: bool, quiet: bool,
                         deadline: float) -> None:
        """Poll (without blocking the GUI) until the writer queue is empty."""
        writer = self.writer
        if writer is None or writer.queue.unfinished_tasks == 0 or time.perf_counter() > deadline:
            self._launch_export(folder, render, quiet=quiet)
            return
        QtCore.QTimer.singleShot(
            100, lambda: self._wait_for_writer(folder, render, quiet, deadline)
        )

    def _export_command(self, folder: Path, render: bool) -> tuple[str, list[str]] | None:
        """Program and arguments that run the companion export script."""
        script = PROGRAM_DIR / COMPANION_EXPORT_SCRIPT
        if not script.is_file():
            self.status_message(f"{COMPANION_EXPORT_SCRIPT} not found beside the program; "
                                "cannot write the .vszh5.")
            return None
        axis = self.window.tab_monitor.vszh5_axis.currentData() or "local"
        args = [str(script), str(folder), "--time-axis", str(axis), "--workers", "2"]
        if not render:
            args.append("--no-render")
        return sys.executable, args

    def _launch_export(self, folder: Path, render: bool, detached: bool = False,
                       quiet: bool = False) -> None:
        """Run the export script for ``folder`` in a separate process."""
        command = self._export_command(folder, render)
        if command is None:
            return
        program, args = command
        if detached:
            QtCore.QProcess.startDetached(program, args)
            logging.getLogger(APP_NAME).info("Detached .vszh5 export: %s", folder)
            return
        if self._export_proc is not None:
            # One export at a time; the latest request runs when it finishes.
            self._export_pending = (folder, render)
            if not quiet:
                self.status_message("Veusz export already running; queued another.")
            return
        proc = QtCore.QProcess(self)
        proc.setProgram(program)
        proc.setArguments(args)
        proc.setWorkingDirectory(str(folder))
        proc.setProcessChannelMode(QtCore.QProcess.ProcessChannelMode.MergedChannels)
        self._export_output = []
        proc.readyReadStandardOutput.connect(
            lambda: self._export_output.append(
                bytes(proc.readAllStandardOutput()).decode("utf-8", "replace"))
        )
        proc.finished.connect(lambda *_: self._export_finished(folder))
        self._export_proc = proc
        self.last_export_ok = None
        proc.start()
        if not quiet:
            self.status_message(f"Writing Veusz document for {folder.name} ...")

    def _export_finished(self, folder: Path) -> None:
        """Report the export result and start any queued request."""
        proc = self._export_proc
        self._export_proc = None
        if proc is not None:
            self._export_output.append(
                bytes(proc.readAllStandardOutput()).decode("utf-8", "replace"))
        text = "".join(self._export_output).strip()
        code = proc.exitCode() if proc is not None else -1
        target = folder / SESSION_VSZH5_NAME
        self.last_export_ok = code == 0 and target.is_file()
        log = self.session.logger if self.session is not None else logging.getLogger(APP_NAME)
        log.info("Veusz export (exit %s):\n%s", code, text)
        if self.last_export_ok:
            extras = [ln.split(":", 1)[1].strip() for ln in text.splitlines()
                      if ln.startswith(("plots", "report")) and ":" in ln]
            self.status_message(f"Veusz document written: {target}"
                                + (f"  ({'; '.join(extras)})" if extras else ""))
        else:
            tail = text.splitlines()[-1] if text else "no output"
            self.status_message(f"Veusz export failed (exit {code}): {tail}")
        if proc is not None:
            proc.deleteLater()
        if self._export_pending is not None:
            pending, self._export_pending = self._export_pending, None
            self._launch_export(*pending)

    def open_in_veusz(self) -> None:
        """Open the session .vszh5 in the installed Veusz program."""
        folder = self._session_folder()
        target = folder / SESSION_VSZH5_NAME if folder is not None else None
        if target is None or not target.is_file():
            self.status_message("No .vszh5 yet: use 'Write .vszh5 now' first.")
            return
        exe = vszh5_writer.find_veusz_exe() if HAVE_VSZH5_WRITER else ""
        if exe:
            QtCore.QProcess.startDetached(exe, [str(target)])
            self.status_message(f"Opened {target.name} in Veusz.")
        else:
            QtGui.QDesktopServices.openUrl(QtCore.QUrl.fromLocalFile(str(target)))
            self.status_message("Veusz program not found; asked the desktop to open "
                                "the file. Set QUICKSYN_VEUSZ to veusz.exe.")

    # --- Sampler callbacks --------------------------------------------------
    def _on_sample(self, row: dict[str, Any]) -> None:
        """Update the headline readouts from the most recent sample."""
        monitor = self.window.tab_monitor
        monitor.set_stat("freq", row["freq_hz"] or "-")
        monitor.set_stat("power", row["power_dbm"] or "-")
        monitor.set_stat("temp", row["temp_c"] or "-")
        monitor.set_stat("latency", f"{float(row['latency_s']) * 1e3:.1f} ms")

    def _on_sampler_error(self, message: str) -> None:
        """Count and report a failed poll without stopping acquisition."""
        self.sampler_errors += 1
        self.window.tab_monitor.set_stat("errors", str(self.sampler_errors))
        if self.session is not None:
            self.session.logger.warning("Sampler: %s", message)

    def _on_rate_report(self, achieved_hz: float, duty: float) -> None:
        """Display the measured rate and the fraction of time spent in I/O."""
        monitor = self.window.tab_monitor
        monitor.set_stat("achieved", f"{achieved_hz:.2f} Hz")
        monitor.set_stat("duty", f"{duty * 100.0:.0f} %")
        if duty > 0.95:
            self.status_message(
                "Serial link is saturated; the requested sample rate is not "
                "being met. Reduce the rate or poll fewer fields."
            )

    def _refresh_statistics(self) -> None:
        """Periodic UI refresh for buffer, writer and plot state."""
        monitor = self.window.tab_monitor
        if self.ring is not None:
            monitor.set_stat("samples", f"{self.ring.total_written}")
            monitor.set_stat(
                "ring", f"{self.ring.fill} / {self.ring.capacity}"
            )
            monitor.set_stat("ram", f"{self.ring.nbytes / 1e6:.1f} MB")
            monitor.update_plot(self.ring.tail(DEFAULT_PLOT_WINDOW))
        if self.writer is not None:
            monitor.set_stat("chunks", str(self.writer.chunks_written))
            monitor.set_stat("rows", str(self.writer.rows_written))
            monitor.set_stat("queue", str(self.writer.queue.qsize()))
        if HAVE_PSUTIL:
            rss = psutil.Process(os.getpid()).memory_info().rss
            monitor.set_stat("rss", f"{rss / 1e6:.0f} MB")
        else:
            monitor.set_stat("rss", "psutil not installed")


